// One persisted AI selection for the whole application. Both model selectors
// publish through this bridge, so changing one immediately updates the other
// (and other open application tabs) without triggering a second save.
window.GlobalAISelection = (() => {
    const storageKey = 'marketsignals_global_ai_model';
    let channel = null;
    try {
        if ('BroadcastChannel' in window) channel = new BroadcastChannel('marketsignals-ai-selection');
    } catch (_) { channel = null; }

    function apply(model) {
        const normalized = String(model || '').trim();
        if (!normalized) return;
        ['global-ollama-model', 'preearnings-ai-model'].forEach((id) => {
            const select = document.getElementById(id);
            if (select && Array.from(select.options || []).some((option) => option.value === normalized)) {
                select.value = normalized;
            }
        });
    }

    function publish(model) {
        const normalized = String(model || '').trim();
        if (!normalized) return;
        apply(normalized);
        try { localStorage.setItem(storageKey, normalized); } catch (_) { }
        try { if (channel) channel.postMessage({ model: normalized }); } catch (_) { }
        window.dispatchEvent(new CustomEvent('marketsignals:ai-model-changed', {
            detail: { model: normalized, scope: 'global' }
        }));
    }

    if (channel) channel.addEventListener('message', (event) => apply(event.data && event.data.model));
    window.addEventListener('storage', (event) => {
        if (event.key === storageKey) apply(event.newValue);
    });
    return { apply, publish };
})();

// One renderer for every Ollama selector.  The API distinguishes models that
// are already activated in the local daemon from the live Ollama Cloud
// catalog, so a newly released cloud model is visible without pretending it
// is already installed.
window.OllamaModelCatalogUI = {
    populate(select, data) {
        if (!select) return { installed: 0, cloud: 0, total: 0 };
        const unique = (rows) => Array.from(new Set(
            (Array.isArray(rows) ? rows : [])
                .map((value) => String(value || '').trim())
                .filter(Boolean)
        ));
        const installed = unique(data && data.local_models);
        const cloud = unique(data && data.cloud_models);
        const all = unique(data && data.models);
        const installedSet = new Set(installed);
        const cloudOnly = cloud.filter((model) => !installedSet.has(model));
        // Claude models served by the owner's Claude subscription (never by Ollama).
        const subscription = unique(data && data.subscription_models);
        const knownSet = new Set([...installed, ...cloudOnly, ...subscription]);
        const configuredOnly = all.filter((model) => !knownSet.has(model));

        select.innerHTML = '';
        const addGroup = (label, models) => {
            if (!models.length) return;
            const group = document.createElement('optgroup');
            group.label = `${label} (${models.length})`;
            for (const model of models) {
                const option = document.createElement('option');
                option.value = model;
                option.textContent = model;
                group.appendChild(option);
            }
            select.appendChild(group);
        };
        addGroup('Claude subscription', subscription);
        addGroup('Activated in Ollama', installed);
        addGroup('Ollama Cloud catalog', cloudOnly);
        addGroup('Configured fallback', configuredOnly);

        if (!select.options.length) {
            const option = document.createElement('option');
            option.value = '';
            option.textContent = 'No models returned';
            select.appendChild(option);
        }
        const preferred = String((data && data.preferred_model) || '').trim();
        const active = String((data && data.active_model) || '').trim();
        const selected = [preferred, active].find((model) =>
            model && Array.from(select.options).some((option) => option.value === model)
        );
        if (selected) select.value = selected;
        return { installed: installed.length, cloud: cloud.length, total: all.length };
    },
};

const IS_DEV = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

function logRateLimited(key, message, err, intervalMs = 60000) {
    const now = Date.now();
    if (!window._logRateLimit) window._logRateLimit = {};
    const last = window._logRateLimit[key] || 0;
    if (now - last >= intervalMs) {
        window._logRateLimit[key] = now;
        if (err) {
            console.warn(message, err);
        } else {
            console.warn(message);
        }
    }
}

