    // Watchlist Operations
    async getWatchlist() {
        const res = await this.fetchWithTimeout(`${this.BASE_URL}/watchlist`, { timeout: 15000 });
        if (!res.ok) throw new Error('Failed to fetch watchlist');
        const data = await res.json();
        this._watchlistCache.ts = Date.now();
        this._watchlistCache.data = data;
        this._watchlistCache.inflight = null;
        return data;
    },
    async getWatchlistCached(ttlMs = 6000) {
        const now = Date.now();
        if (this._watchlistCache.data && (now - this._watchlistCache.ts) < ttlMs) {
            return this._watchlistCache.data;
        }
        if (this._watchlistCache.inflight) {
            return this._watchlistCache.inflight;
        }
        const req = (async () => {
            const data = await this.getWatchlist();
            this._watchlistCache.ts = Date.now();
            this._watchlistCache.data = data;
            return data;
        })();
        this._watchlistCache.inflight = req;
        try {
            return await req;
        } catch (e) {
            if (this._watchlistCache.data) {
                this._warnNetworkOnce('Watchlist fallback to stale cache', e);
                return this._watchlistCache.data;
            }
            throw e;
        } finally {
            if (this._watchlistCache.inflight === req) {
                this._watchlistCache.inflight = null;
            }
        }
    },
    async getLivePrices(symbols = [], options = {}) {
        const list = Array.isArray(symbols)
            ? symbols.map(s => String(s || '').toUpperCase().trim()).filter(Boolean)
            : String(symbols || '').split(',').map(s => s.toUpperCase().trim()).filter(Boolean);
        const unique = [...new Set(list)];
        const params = new URLSearchParams({
            remote: String(options.remote !== false),
            cache_fallback: String(options.cacheFallback !== false)
        });
        if (Number.isFinite(Number(options.maxAgeSeconds))) {
            params.set('max_age_seconds', String(Math.max(5, Number(options.maxAgeSeconds))));
        }
        if (!unique.length) {
            const res = await this.fetchWithTimeout(`${this.BASE_URL}/live-prices?${params.toString()}`, {
                timeout: options.timeout || 25000
            });
            if (!res.ok) throw new Error(`Failed to fetch live prices (${res.status})`);
            return res.json();
        }
        // One request with the whole watchlist fans out per stale symbol on the
        // server and blew past the 25s client timeout (39 symbols = 47-53s,
        // audit 2026-09-05 P1) — every row then rendered "STALE" forever.
        // Batches of 8 settle in ~5s and run in parallel.
        const CHUNK = Math.max(1, Number(options.chunkSize) || 8);
        const chunks = [];
        for (let i = 0; i < unique.length; i += CHUNK) chunks.push(unique.slice(i, i + CHUNK));
        const merge = (acc, data) => {
            if (!acc) return data;
            return {
                ...acc,
                ...data,
                prices: { ...(acc.prices || {}), ...((data && data.prices) || {}) },
                truncated: Boolean(acc.truncated || (data && data.truncated)),
                max_symbols: Math.max(Number(acc.max_symbols) || 0, Number((data && data.max_symbols) || 0))
            };
        };
        const results = await Promise.all(chunks.map(chunk => {
            const p = new URLSearchParams(params);
            p.set('symbols', chunk.join(','));
            return this.fetchWithTimeout(`${this.BASE_URL}/live-prices?${p.toString()}`, { timeout: options.timeout || 25000 })
                .then(r => {
                    if (!r.ok) throw new Error(`Failed to fetch live prices (${r.status})`);
                    return r.json();
                });
        }));
        return results.reduce((acc, d) => merge(acc, d), null);
    },
    async addTicker(ticker, options = {}) {
        const body = { ticker, ...(options || {}) };
        const res = await fetch(`${this.BASE_URL}/tickers`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(body)
        });
        if (!res.ok) {
            let detail = `Failed to add ticker (${res.status})`;
            let payload = null;
            try { payload = await res.json(); } catch (e) { }
            const info = payload && payload.detail;
            if (info && typeof info === 'object') detail = String(info.message || info.detail || info.error || detail);
            else if (info) detail = String(info);
            else if (payload && (payload.message || payload.error)) detail = String(payload.message || payload.error);
            const error = new Error(detail);
            error.status = res.status;
            // "No quote found": the caller offers "Add anyway" (same request with force:true).
            const code = String((info && typeof info === 'object' && (info.code || info.reason || info.status))
                || (payload && (payload.code || payload.reason)) || '').toLowerCase();
            error.noQuote = /no[_ ]?quote|quote[_ ]not[_ ]found|unknown[_ ]symbol|no[_ ]data/.test(code)
                || !!(payload && (payload.requires_force === true || payload.can_force === true))
                || !!(info && typeof info === 'object' && info.requires_force === true)
                || /no (live |market )?(quote|price)/i.test(detail);
            throw error;
        }
        this._watchlistCache = { ts: 0, data: null, inflight: null };
        this._newsStateCache = { ts: 0, data: null, inflight: null };
        this._resetStateCache();
        return res.json();
    },
    async removeTickers(tickers) {
        const normalized = [...new Set((Array.isArray(tickers) ? tickers : [tickers])
            .map(t => String(t || '').toUpperCase().trim())
            .filter(Boolean))];
        if (!normalized.length) throw new Error('No tickers selected');
        const res = await fetch(`${this.BASE_URL}/tickers`, {
            method: 'DELETE',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ tickers: normalized, return_state: false })
        });
        if (!res.ok) {
            let detail = `Failed to remove ticker${normalized.length === 1 ? '' : 's'} (${res.status})`;
            try {
                const payload = await res.json();
                if (payload && payload.detail) detail = String(payload.detail);
            } catch (e) { }
            throw new Error(detail);
        }
        this._watchlistCache = { ts: 0, data: null, inflight: null };
        this._newsStateCache = { ts: 0, data: null, inflight: null };
        this._resetStateCache();
        return res.json();
    },
    async removeTicker(ticker) {
        return this.removeTickers([ticker]);
    },
