UI.renderAgentAiAssignments = async function(availableModels) {
    const container = document.getElementById('agent-ai-assignments-container');
    if (!container) return;

    let models = Array.isArray(availableModels) && availableModels.length ? availableModels : [];
    if (!models.length) {
        try {
            const res = await fetch(`${API.BASE_URL}/ollama/status`);
            if (res.ok) {
                const data = await res.json();
                models = data.models || [];
            }
        } catch (e) {}
    }

    let currentAssignments = {};
    try {
        const res = await fetch(`${API.BASE_URL}/ai/assignment`);
        if (res.ok) {
            currentAssignments = await res.json();
        }
    } catch (e) {}

    // Models served through the owner's Claude subscription (Claude Code CLI).
    // Every role can use one: a Claude model id is routed to the subscription
    // wherever the app calls the AI.
    let subscriptionModels = [];
    try {
        const res = await fetch(`${API.BASE_URL}/ai/providers`);
        if (res.ok) {
            const providers = await res.json();
            const seen = new Set();
            (Array.isArray(providers) ? providers : [])
                .filter(p => p && p.enabled && p.type === 'claude_code')
                .forEach(p => {
                    const ids = (Array.isArray(p.models) && p.models.length ? p.models : [p.default_model])
                        .map(m => String(m || '').trim()).filter(Boolean);
                    ids.forEach(id => {
                        if (seen.has(id)) return;
                        seen.add(id);
                        subscriptionModels.push({ id, provider: String(p.name) });
                    });
                });
        }
    } catch (e) {}
    const subscriptionIds = new Set(subscriptionModels.map(m => m.id));

    container.innerHTML = AGENT_ROLE_METAS.map(role => {
        const selectedModel = currentAssignments[role.key] || '';
        const roleSubscriptionModels = subscriptionModels;
        // Model ids come from the provider catalog (third-party text): escape them.
        // A saved model missing from the current catalog (Ollama offline, model
        // removed) stays selectable; otherwise the row fell back to "Default"
        // and the next save silently erased the saved assignment.
        const modelIds = models.map(m => String(typeof m === 'string' ? m : (m?.name || m?.model || '')))
            .filter(id => id && !subscriptionIds.has(id));   // subscription models are listed once, labelled
        const savedMissing = selectedModel && !modelIds.includes(selectedModel)
            && !roleSubscriptionModels.some(m => m.id === selectedModel);
        const optionsHtml = [
            `<option value="">(Default Global AI)</option>`,
            ...(savedMissing
                ? [`<option value="${UI._escapeHtml(selectedModel)}" selected>${UI._escapeHtml(selectedModel)} (saved · not in current catalog)</option>`]
                : []),
            ...roleSubscriptionModels.map(m => `<option value="${UI._escapeHtml(m.id)}" data-provider="${UI._escapeHtml(m.provider)}" ${m.id === selectedModel ? 'selected' : ''}>${UI._escapeHtml(m.id)} · Claude subscription</option>`),
            ...modelIds.map(m => `<option value="${UI._escapeHtml(m)}" ${m === selectedModel ? 'selected' : ''}>${UI._escapeHtml(m)}</option>`)
        ].join('');

        return `
            <div class="gs-role">
                <div class="gs-role-id">
                    <div class="gs-role-title">${role.title}</div>
                    <div class="gs-role-desc">${role.desc}</div>
                </div>
                <div class="gs-role-control">
                    <select id="agent-ai-model-${role.key}" class="bt-input" aria-label="Model for ${role.title}">
                        ${optionsHtml}
                    </select>
                    <button class="ds-btn ds-btn--sm" type="button" onclick="UI.testAgentAiModel('${role.key}')" title="Test model for ${role.title}">Test</button>
                </div>
            </div>
        `;
    }).join('');
};

UI.testAgentAiModel = async function(roleKey) {
    const select = document.getElementById(`agent-ai-model-${roleKey}`);
    const model = select?.value || document.getElementById('global-ollama-model')?.value || '';
    if (!model) {
        UI.showToast(`No model selected for ${roleKey}.`, 'warning');
        return;
    }
    UI.showToast(`Testing model '${model}' for ${roleKey}…`, 'info');
    // A model served through the Claude subscription is tested through its own provider.
    const subscriptionProvider = select?.selectedOptions?.[0]?.dataset?.provider || '';
    if (subscriptionProvider) {
        try {
            const res = await fetch(`${API.BASE_URL}/ai/request`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ provider: subscriptionProvider, model, prompt: "Reply with the single word OK." })
            });
            const data = await res.json();
            if (res.ok && data.ok) {
                UI.showToast(`✓ [${roleKey}] '${model}' answered through the Claude subscription: ${String(data.text || '').slice(0, 80)}`, 'success');
            } else {
                UI.showToast(`✗ [${roleKey}] '${model}' test failed: ${data.error || data.detail || res.status}`, 'error');
            }
        } catch (err) {
            UI.showToast(`Test failed: ${err.message || err}`, 'error');
        }
        return;
    }
    try {
        const res = await fetch(`${API.BASE_URL}/ollama/test-model`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ model, prompt: `Role test for ${roleKey}: reply with 'OK' and model name.` })
        });
        const data = await res.json();
        if (data.ok) {
            UI.showToast(`✓ [${roleKey}] Model '${model}' verified in ${data.duration_sec}s: ${data.response}`, 'success');
        } else {
            UI.showToast(`✗ [${roleKey}] Model '${model}' test failed (${data.duration_sec}s): ${data.error}`, 'error');
        }
    } catch (err) {
        UI.showToast(`Test failed: ${err.message || err}`, 'error');
    }
};

UI.saveAgentAiAssignments = async function(options = {}) {
    const silent = !!options.silent;
    const payload = {};
    for (const role of AGENT_ROLE_METAS) {
        const select = document.getElementById(`agent-ai-model-${role.key}`);
        if (select) {
            payload[role.key] = select.value.trim() || null;
        }
    }
    const globalModel = document.getElementById('global-ollama-model')?.value || '';
    // "all" also rewrites the Ollama model server-side. Only send it while the
    // model list on screen is Ollama's; with a cloud provider selected the same
    // select holds that provider's models.
    const assignmentProvider = typeof UI._selectedGlobalAiProvider === 'function'
        ? UI._selectedGlobalAiProvider()
        : { type: 'ollama' };
    if (globalModel && assignmentProvider && assignmentProvider.type === 'ollama') payload['all'] = globalModel;

    try {
        const res = await fetch(`${API.BASE_URL}/ai/assignment`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ assignment: payload })
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.detail || `Save failed (${res.status})`);
        if (!silent) {
            UI.showToast('✓ Per-agent AI model assignments saved successfully.', 'success');
        }
        return true;
    } catch (err) {
        console.warn('Failed to save agent assignments:', err);
        if (!silent) {
            UI.showToast(`Failed to save agent model assignments: ${err.message || err}`, 'error');
        }
        return false;
    }
};

