// Reason codes that candidate and decision traces carry, in words. A sentence is
// returned as it came; an unknown bare code only loses its underscores.
UI._reasonCodeText = function (raw) {
    const text = String(raw == null ? '' : raw).trim();
    if (!text) return '';
    const labels = {
        tokenized_stock_excluded: 'Tokenised stock: excluded from autonomous entries',
        stablecoin_excluded: 'Stablecoin: excluded, its moves are not a trend',
        ai_low_entry_confidence: 'AI entry confidence is below the required level',
        'veto:model_veto_upheld_no_validated_score': 'AI veto upheld: no validated score exists that could override it',
        backtest_negative: 'Backtest negative',
        backtest_thin_sample: 'Backtest sample too thin to judge',
    };
    const key = text.toLowerCase();
    if (labels[key]) return labels[key];
    if (key.startsWith('trade_radar_blocked=')) {
        const words = text.slice(text.indexOf('=') + 1).split(',').map((code) => code.trim()).filter(Boolean)
            .map((code) => labels[code.toLowerCase()] || code.replace(/_/g, ' '));
        return `Trade Radar blocks the entry: ${words.join(', ') || 'reason not given'}`;
    }
    if (key.startsWith('veto:')) return `AI veto: ${text.slice(5).replace(/_/g, ' ')}`;
    return /^[a-z0-9_]+$/i.test(text) ? text.replace(/_/g, ' ') : text;
};

// Outcome of a request that acts on several tickers: which ones failed and why.
// null when the answer reports no failure. `status: "partial"` or a `failed` list
// ([{ticker, error}] or plain symbols) both count.
UI._bulkFailureSummary = function (result) {
    const data = result && typeof result === 'object' ? result : {};
    const failed = (Array.isArray(data.failed) ? data.failed : [])
        .map((item) => ((item && typeof item === 'object')
            ? { ticker: String(item.ticker || item.symbol || '').toUpperCase().trim(), error: String(item.error || item.reason || item.detail || '').trim().replace(/_/g, ' ') }
            : { ticker: String(item || '').toUpperCase().trim(), error: '' }))
        .filter((item) => item.ticker);
    const partial = String(data.status || '').toLowerCase() === 'partial';
    if (!failed.length && !partial) return null;
    const shown = failed.slice(0, 8).map((item) => (item.error ? `${item.ticker} (${item.error})` : item.ticker));
    const more = failed.length > 8 ? ` and ${failed.length - 8} more` : '';
    const text = failed.length
        ? `Failed: ${shown.join(', ')}${more}.`
        : (typeof data.detail === 'string' && data.detail ? data.detail : 'Some tickers failed; the server did not say which.');
    return { failed, tickers: failed.map((item) => item.ticker), text };
};

// What an add-ticker answer means. `needsForce`: the server found no quote for the
// symbol and did not add it; the same request with force:true adds it anyway.
// `verified === false`: added, but the symbol could not be checked (no connection).
UI._addTickerOutcome = function (result, error) {
    if (error) {
        return { added: false, already: false, needsForce: error.noQuote === true, verified: null, message: String(error.message || error) };
    }
    const data = result && typeof result === 'object' ? result : {};
    const status = String(data.status || data.code || data.reason || '').toLowerCase();
    const message = String(data.message || data.detail || data.error || '');
    const noQuote = data.added === false && (data.requires_force === true || data.quote_found === false
        || /no[_ ]?quote|quote[_ ]not[_ ]found|unknown[_ ]symbol|no[_ ]data/.test(status)
        || /no (live |market )?(quote|price)/i.test(message));
    return {
        added: data.added !== false,
        already: data.added === false && !noQuote,
        needsForce: noQuote,
        verified: data.verified === false ? false : (data.verified === true ? true : null),
        // found | unverified (lookup not completed) | forced (added anyway) | skipped (check off)
        verifyStatus: String(data.verify_status || '').toLowerCase(),
        message: noQuote ? (message || 'No quote was found for this symbol.') : message,
    };
};

// Toast for a ticker that was added. Says so when the symbol was not checked.
UI._addTickerToast = function (ticker, outcome) {
    const o = outcome || {};
    if (o.verifyStatus === 'forced') return { text: `${ticker} added without a quote check.`, type: 'warning' };
    if (o.verifyStatus === 'skipped') return { text: `${ticker} added to Watchlist (symbol check is switched off).`, type: 'success' };
    if (o.verified === false) return { text: 'Added, but the symbol could not be verified (no connection)', type: 'warning' };
    return { text: `${ticker} added to Watchlist.`, type: 'success' };
};

// Consolidated render function
UI._safeRender = function (name, fn) {
    try {
        fn();
    } catch (e) {
        console.error(`Render failed: ${name}`, e);
    }
};

UI._composeHomeState = function (state, dashboard) {
    const base = state || {};
    const dash = dashboard || {};
    return { ...base, ...dash };
};

UI.renderAll = function (state, watchlist, scanner, dashboard = null) {
    if (!state) return;
    UI.mergeLivePricesIntoState(UI._livePricesCache || {}, state);

    // Default scanner if missing
    if (!scanner) scanner = { hot_tickers: [] };
    const dashPayload = dashboard || cachedDashboard || UI.loadDashboardSnapshot() || null;

    // Dashboard cold start: show skeleton when no dashboard data available yet
    if (!dashPayload && !cachedDashboard) {
        const headerEl = document.getElementById('home-top-header') || document.querySelector('.home-top-header');
        if (headerEl && !headerEl.dataset.populated) {
            headerEl.innerHTML = '<div class="home-top-header-item" style="opacity:0.4;"><div class="home-top-header-label">Loading dashboard...</div><span class="kpi-value" style="background:var(--surface-alt);border-radius:4px;display:inline-block;width:80px;height:18px;"></span></div>'.repeat(6);
        }
        const healthBox = document.getElementById('home-strategy-health-content');
        if (healthBox && !healthBox.dataset.populated) {
            healthBox.innerHTML = '<div style="opacity:0.4;text-align:center;padding:12px;"><i class="fa-solid fa-spinner fa-spin"></i> Loading strategy health...</div>';
        }
    }
    const homeState = UI._composeHomeState(state, dashPayload || {});

    const stage = (name, fn, order = 0) => {
        UI.scheduleRender(`home:${name}`, () => UI._safeRender(name, fn), 20 + order * 25);
    };
    stage('updateActivityLog', () => UI.updateActivityLog(homeState, scanner), 0);
    stage('renderDashboardTopHeader', () => UI.renderDashboardTopHeader(dashPayload || {}), 1);
    stage('renderHomeMarketNarrative', () => UI.renderHomeMarketNarrative(homeState), 2);
    stage('renderDashboardStrategyHealth', () => UI.renderDashboardStrategyHealth(dashPayload || {}), 3);
    stage('renderStats', () => UI.renderStats(state), 4);
    stage('renderTimeline', () => UI.renderTimeline(state), 5);
    stage('renderSignalsFeed', () => UI.renderSignalsFeed(state), 6);
    stage('renderNews', () => UI.renderNews(homeState), 7);
    if (state.capital) stage('renderCapital', () => UI.renderCapital(state.capital), 8);
    stage('renderWatchlist', () => UI.renderWatchlist(watchlist || state.watchlist || null, homeState), 9);
    if ((ViewRouter.activeView || 'home') === 'home') {
        UI.refreshWatchlistLivePrices(watchlist || state.watchlist || null, { render: true }).catch(() => { });
    }
    stage('renderDashboardRiskFlags', () => UI.renderDashboardRiskFlags(homeState), 10);
    stage('renderDashboardEarnings', () => UI.renderDashboardEarnings(homeState), 11);
    if (scanner) stage('renderScanner', () => UI.renderScanner(scanner.hot_tickers, scanner.status), 12);

    if (ViewRouter.activeView === 'watchlist') {
        stage('renderDetailedWatchlist', () => UI.renderDetailedWatchlist(state), 13);
    }
    if (ViewRouter.activeView === 'hotlist') {
        stage('renderHotList', () => UI.renderHotList(state), 13);
    }
};

UI.renderNewsHeatmap = function (data) {
    const container = document.getElementById('news-impact-bars');
    if (!container) return;

    const now = Date.now();
    const maxAgeMs = 7 * 24 * 60 * 60 * 1000;
    const counts = { critical: 0, high: 0, medium: 0, low: 0 };

    const collect = (arr) => {
        if (!arr) return;
        arr.forEach(a => {
            const ts = a.published_at ? new Date(a.published_at).getTime() : now;
            if (now - ts > maxAgeMs) return;
            const impact = (a.impact || 'low').toLowerCase();
            if (counts[impact] !== undefined) counts[impact] += 1;
            else counts.low += 1;
        });
    };

    collect(data.market_news);
    collect(data.breaking_news);
    if (data.ticker_news) {
        Object.values(data.ticker_news).forEach(arr => collect(arr));
    }

    const maxCount = Math.max(1, ...Object.values(counts));
    const colorMap = {
        critical: 'var(--ds-neg)',
        high: 'var(--ds-warn)',
        medium: 'var(--ds-warn-line)',
        low: 'var(--ds-text-3)'
    };

    container.innerHTML = Object.entries(counts).map(([k, v]) => {
        const maxBarHeight = 24;
        const minBarHeight = 4;
        const height = Math.max(minBarHeight, (v / maxCount) * maxBarHeight);
        return `
            <div style="flex:1; text-align:center;">
                <div style="height:${height}px; background:${colorMap[k]}; border-radius:4px; margin-bottom:6px;"></div>
                <div style="font-size:0.7rem; color:var(--text-muted); text-transform:uppercase;">${k}</div>
                <div style="font-size:0.8rem; font-weight:700;">${v}</div>
            </div>
        `;
    }).join('');
};

UI._offlineErrorCount = 0;
UI.setOfflineMode = function (isOffline) {
    const banner = document.getElementById('offline-banner');
    if (!banner) return;
    if (isOffline) {
        banner.classList.remove('hidden');
    } else {
        banner.classList.add('hidden');
    }
};

UI.refreshApiUsageWidget = async function () {
    const el = document.getElementById('api-usage-widget');
    if (!el) return;
    try {
        const res = await fetch('/api/stats/api-requests');
        // A failed request used to be parsed anyway and shown as "0 / 0".
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();
        const cur = (data && data.current) || {};
        const metrics = (data && data.metrics) || {};
        // The server answers with zeros and empty metrics when it could not
        // read its counters: that is "unknown", not "no traffic".
        if (!Object.keys(metrics).length) throw new Error('no metrics');
        const byService = metrics.external_calls_by_service_last_minute || {};
        const count = (v) => Number.isFinite(Number(v)) ? Number(v) : 0;
        // The two sources a backtest downloads candles from. (The widget used
        // to list "FMP", which this app does not call, and left out Binance,
        // the source of every crypto backtest.)
        const row = (label, value) => `
            <div class="bt-usage-row">
                <span>${label}</span><span class="bt-usage-num">${count(value)}</span>
            </div>`;
        el.innerHTML = `
            <div class="bt-usage-cap">Outgoing calls in the last minute</div>
            ${row('Yahoo (stocks)', byService.yahoo ?? cur.yahoo_rpm)}
            ${row('Binance (crypto)', byService.binance)}
            ${row('All external sources', cur.external_rpm ?? metrics.external_calls_last_minute)}
        `;
    } catch (e) {
        el.innerHTML = '<span class="bt-usage-error">API usage is unavailable right now</span>';
    }
};

// Persistence Logic
UI.loadActivityLog = function () {
    try {
        const saved = localStorage.getItem('marketMuse_activityLog');
        if (saved) {
            const items = JSON.parse(saved);
            UI.activityLog = items;
            if (IS_DEV) console.log(`?? Loaded ${items.length} activity items.`);

            // Re-hydrate seen sets to prevent duplicates
            items.forEach(item => {
                if (!item.id) return; // Legacy fallback
                if (item.type === 'NEWS' || item.type === 'NEWS_CRITICAL') UI.seenNews.add(item.id);
                else if (item.type === 'OPEN' || item.type === 'CLOSE') UI.seenSignals.add(item.id);
                else if (item.type === 'WATCHLIST') UI.seenWatchlistEvents.add(item.id);
                else if (item.type === 'EARNINGS_SOON' || item.type === 'RISK_FLAG') UI.seenManualActivity.add(item.id);
                else if (item.type === 'MANUAL' || item.type === 'APP') UI.seenManualActivity.add(item.id);
            });

            // Cap seen sets to prevent memory leaks on long sessions
            if (UI.seenNews.size > UI._MAX_SEEN) UI.seenNews = new Set([...UI.seenNews].slice(-UI._MAX_SEEN));
            if (UI.seenSignals.size > UI._MAX_SEEN) UI.seenSignals = new Set([...UI.seenSignals].slice(-UI._MAX_SEEN));

            // FIX: Enforce sorting on load
            UI.activityLog.sort((a, b) => {
                const da = new Date(a.time).getTime();
                const db = new Date(b.time).getTime();
                return db - da; // Newest first
            });
        }
    } catch (e) {
        console.warn('Activity load error', e);
    }
};

async function initApp() {
    if (UI._appInitStarted) {
        return UI.refreshCurrentViewData ? UI.refreshCurrentViewData() : undefined;
    }
    UI._appInitStarted = true;
    if (IS_DEV) console.log('?? Initializing App...');
    UI.loadActivityLog();
    UI.initWatchlistQuickAiCache();
    UI.bindNotebookAutoCalc();
    UI.setWatchlistPreviewMode(HomeUIState.watchlistMode || 'priority');
    const initialHashView = window.location.hash.replace('#', '');

    // 1. Try to load from LocalStorage (Resilience)
    try {
        const savedState = localStorage.getItem('appState');
        const savedWatchlist = localStorage.getItem('appWatchlist');
        const savedScanner = localStorage.getItem('appScanner');
        cachedDashboard = UI.loadDashboardSnapshot();

        if (savedState) {
            if (IS_DEV) console.log('?? Loaded state from cache');
            const parsed = JSON.parse(savedState);
            let state = null;
            if (parsed && typeof parsed === 'object' && parsed.data && Number(parsed.snapshot_version || 0) === SNAPSHOT_VERSION) {
                state = parsed.data;
            } else if (parsed && typeof parsed === 'object' && !parsed.snapshot_version) {
                // Graceful fallback for legacy snapshots.
                state = parsed;
            }
            if (!state || typeof state !== 'object') {
                throw new Error('Invalid cached appState snapshot');
            }
            const watchlist = savedWatchlist ? JSON.parse(savedWatchlist) : null;
            const scanner = savedScanner ? JSON.parse(savedScanner) : null;
            cachedState = UI.mergeStatePreserveDetails(cachedState, state);
            if (watchlist) cachedState.watchlist = watchlist;
            if (scanner) cachedState.scanner = scanner;

            // Render the full dashboard only when the first view is Home.
            // Direct links such as #capital should not pay the cost of Home/news/signals rendering.
            if (!initialHashView || initialHashView === 'home') {
                UI.renderAll(cachedState, watchlist, scanner, cachedDashboard);
            }
        }
    } catch (e) {
        console.warn('Cache load error:', e);
    }

    // Always honor URL hash on first load (even without cache)
    ViewRouter.restoreFromHash();

    // 2. Fetch Live Data
    try {
        // Enable audio (user interaction required normally, but we setup init)
        AudioSystem.markInitialLoadComplete();

        // Start Auto Refresh Loop (which will do the first live fetch)
        startAutoRefresh();
        UI.startAutoRefreshWatchdog();
        UI.startNewsAutoRefresh();
        UI.startTradeRadarAutoRefresh();
        UI.startPremarketAutoRefresh();
        UI.startPreEarningsAutoRefresh();

        // API usage widget refresh
        if (!UI._apiStatsTimer) {
            UI.refreshApiUsageWidget();
            UI._apiStatsTimer = setInterval(() => {
                if (ViewRouter.activeView === 'backtest') UI.refreshApiUsageWidget();
            }, 20000);
        }

    } catch (e) {
        console.error('Init error:', e);
        startAutoRefresh(); // Try anyway
        UI.startAutoRefreshWatchdog();
        UI.startNewsAutoRefresh();
        UI.startTradeRadarAutoRefresh();
        UI.startPremarketAutoRefresh();
        UI.startPreEarningsAutoRefresh();
    }
}

const PerfMonitor = {
    requestWindowMs: 60000,
    requestTimestamps: [],
    tabRender: {},
    markRequest() {
        const now = Date.now();
        this.requestTimestamps.push(now);
        const cutoff = now - this.requestWindowMs;
        while (this.requestTimestamps.length && this.requestTimestamps[0] < cutoff) {
            this.requestTimestamps.shift();
        }
    },
    requestsPerMinute() {
        const now = Date.now();
        const cutoff = now - this.requestWindowMs;
        while (this.requestTimestamps.length && this.requestTimestamps[0] < cutoff) {
            this.requestTimestamps.shift();
        }
        return this.requestTimestamps.length;
    },
    markRender(tabName, durationMs) {
        const key = String(tabName || 'unknown');
        if (!this.tabRender[key]) {
            this.tabRender[key] = { count: 0, totalMs: 0, maxMs: 0 };
        }
        const row = this.tabRender[key];
        row.count += 1;
        row.totalMs += Number(durationMs || 0);
        row.maxMs = Math.max(row.maxMs, Number(durationMs || 0));
    },
    snapshot() {
        const out = {};
        Object.entries(this.tabRender).forEach(([k, v]) => {
            const count = Number(v.count || 0);
            out[k] = {
                count,
                avgMs: count > 0 ? Number((v.totalMs / count).toFixed(2)) : 0,
                maxMs: Number((v.maxMs || 0).toFixed(2))
            };
        });
        return {
            requestsPerMinute: this.requestsPerMinute(),
            tabRender: out
        };
    }
};
window.__MS_PERF = PerfMonitor;

// Decoupled refresh loops - recursive to prevent request piling and ensure independence
async function startAutoRefresh() {
    if (UI._coreAutoStarted) return;
    UI._coreAutoStarted = true;
    let coreFailCount = 0;
    let watchlistFailCount = 0;
    let scannerFailCount = 0;

    const dynamicDelay = (baseMs, failCount, inactiveMultiplier = 1.0) => {
        const offline = !navigator.onLine || UI._offlineErrorCount >= 2;
        const backoff = failCount > 0 ? Math.min(Math.pow(2, failCount), 10) : 1;
        const offlineFactor = offline ? 1.8 : 1.0;
        const hiddenFactor = (typeof document !== 'undefined' && document.hidden) ? 2.5 : 1.0;
        return UI._jitterDelay(baseMs * inactiveMultiplier * backoff * offlineFactor * hiddenFactor, 0.1);
    };
    const markRefreshSuccess = () => {
        UI._lastAutoRefreshSuccessAt = Date.now();
    };

    // 1) Core state loop
    const coreLoop = async () => {
        const activeView = ViewRouter.activeView || 'home';
        const onHome = activeView === 'home';
        try {
            const lean = !['hotlist', 'capital'].includes(activeView);
            const capitalOnly = activeView === 'capital';
            const dashboardReq = onHome
                ? API.getDashboardCached(5000).catch((e) => {
                    API._warnNetworkOnce('Dashboard auto-refresh paused', e);
                    return null;
                })
                : Promise.resolve(null);
            const stateReq = API.getStateCached({
                includeHotlist: activeView === 'hotlist',
                hotlistDetails: false,
                lean,
                include: capitalOnly ? 'capital' : null,
                unchanged: !capitalOnly,
                livePrices: capitalOnly ? false : null
            });
            const [state, dashboardResp] = await Promise.all([stateReq, dashboardReq]);
            // Smart Alerts: toast + sound for freshly fired alerts. This is the
            // only live consumer of state.alerts_triggered — the old
            // App.updateUI patch it lived in never ran (no call sites), so a
            // fired alert reached nobody (audit 2026-09-05, P1).
            UI.processTriggeredAlerts(state);
            if (dashboardResp && Number(dashboardResp.dashboard_version || 0) === 2) {
                cachedDashboard = dashboardResp;
                UI.saveDashboardSnapshot(cachedDashboard);
            } else if (!cachedDashboard) {
                cachedDashboard = UI.loadDashboardSnapshot();
            }
            let mergedState = state;
            const hasNews = (state.breaking_news && state.breaking_news.length)
                || (state.market_news && state.market_news.length)
                || (state.ticker_news && Object.keys(state.ticker_news || {}).length);
            if (!hasNews && cachedNewsData) {
                mergedState = {
                    ...state,
                    breaking_news: cachedNewsData.breaking_news || [],
                    market_news: cachedNewsData.market_news || [],
                    ticker_news: cachedNewsData.ticker_news || {},
                    news: cachedNewsData
                };
            }
            if (mergedState.hot_list && cachedState && cachedState.hot_list) {
                const hadDetails = cachedState.hot_list.some(i => i && i._details_loaded);
                const incomingDetails = mergedState.hot_list.some(i => i && i._details_loaded);
                if (hadDetails && !incomingDetails) {
                    mergedState.hot_list = UI.mergeHotListFastIntoDetails(cachedState.hot_list, mergedState.hot_list);
                }
            }
            if (!capitalOnly) {
                mergedState = await UI.reconcileSignalsState(mergedState);
            }
            cachedState = UI.mergeStatePreserveDetails(cachedState, mergedState);
            UI.mergeLivePricesIntoState(UI._livePricesCache || {}, cachedState);
            if (!capitalOnly) {
                UI.saveState(cachedState);
            }
            markRefreshSuccess();

            if (onHome) {
                const renderVersion = [
                    cachedState && cachedState.state_version ? cachedState.state_version : '',
                    cachedDashboard && cachedDashboard.dashboard_version ? cachedDashboard.dashboard_version : '',
                ].join('|');
                const renderAge = Date.now() - Number(UI._lastHomeRenderAt || 0);
                if (!renderVersion || renderVersion !== UI._lastHomeRenderVersion || renderAge > 30000) {
                    UI._lastHomeRenderVersion = renderVersion;
                    UI._lastHomeRenderAt = Date.now();
                    UI.scheduleRender('home', () => UI.renderAll(cachedState, null, cachedState.scanner, cachedDashboard), 100);
                }
            } else {
                UI.updateActivityLog(cachedState, cachedState.scanner || null);
                if (activeView === 'watchlist') UI.scheduleRender('watchlist:core-loop', () => UI.renderDetailedWatchlist(cachedState || { tickers: [] }), 80);
                if (activeView === 'hotlist') UI.scheduleRender('hotlist:core-loop', () => UI.renderHotList(cachedState), 80);
                if (activeView === 'news') UI.scheduleRender('news:core-loop', () => UI.renderNews(cachedState), 80);
                if (activeView === 'capital' && cachedState && cachedState.capital) {
                    UI.scheduleRender('capital', () => UI.renderCapital(cachedState.capital), 50);
                }
            }

            coreFailCount = 0;
            // A successful poll proves the server is reachable — clear offline state
            // immediately rather than draining a (possibly inflated) counter one at a time.
            if (UI._offlineErrorCount !== 0) UI._offlineErrorCount = 0;
            UI.setOfflineMode(false);
        } catch (e) {
            if (API.isNetworkFailure(e)) API._warnNetworkOnce('Core auto-refresh paused', e);
            else console.error('Core auto-refresh error', e);
            coreFailCount = Math.min(coreFailCount + 1, 6);
            // Only count hard connection failures toward offline mode (not timeouts/cooldown echoes).
            if (API._isHardOfflineError(e)) {
                UI._offlineErrorCount += 1;
                if (UI._offlineErrorCount >= 2) UI.setOfflineMode(true);
            }
            if (cachedState && onHome) {
                UI.scheduleRender('home', () => UI.renderAll(cachedState, null, cachedState.scanner, cachedDashboard), 100);
            }
        } finally {
            const base = onHome ? 5000 : 8500;
            setTimeout(coreLoop, dynamicDelay(base, coreFailCount, onHome ? 1.0 : 1.2));
        }
    };

    // 2) Watchlist loop
    const watchlistLoop = async () => {
        const activeView = ViewRouter.activeView || 'home';
        const onHome = activeView === 'home';
        const onWatchlist = activeView === 'watchlist';
        try {
            const watchlist = await API.getWatchlistCached();
            Actions._ensureCalendarCachesLoaded();
            const newSig = Actions.getWatchlistSignature(watchlist);
            if (newSig && newSig !== Actions._watchlistSig) {
                Actions._watchlistSig = newSig;
                try { localStorage.setItem('calendar_watchlist_sig', newSig); } catch (e) { }
                Actions.clearCalendarCache();
                if (activeView === 'calendar') {
                    Actions.renderFullCalendar(Actions.calendarState.currentDate);
                }
            }
            localStorage.setItem('appWatchlist', JSON.stringify(watchlist));
            if (cachedState) cachedState.watchlist = watchlist;
            markRefreshSuccess();
            if (onHome || onWatchlist) {
                UI.refreshWatchlistLivePrices(watchlist, { render: true }).catch(() => { });
                if (onHome) {
                    UI.scheduleRender('home:watchlist-loop', () => UI.renderWatchlist(watchlist, cachedState || {}), 80);
                } else {
                    UI.scheduleRender('watchlist:widget-loop', () => UI.renderWatchlist(watchlist, cachedState), 80);
                }
            }
            if (onWatchlist) {
                UI.scheduleRender('watchlist:detail-loop', () => UI.renderDetailedWatchlist(cachedState || { tickers: [] }), 120);
            }
            watchlistFailCount = 0;
            // A successful poll proves the server is reachable — clear offline state
            // immediately rather than draining a (possibly inflated) counter one at a time.
            if (UI._offlineErrorCount !== 0) UI._offlineErrorCount = 0;
            UI.setOfflineMode(false);
        } catch (e) {
            if (API.isNetworkFailure(e)) API._warnNetworkOnce('Watchlist auto-refresh paused', e);
            else console.error('Watchlist auto-refresh error', e);
            // Only count hard connection failures toward offline mode (not timeouts/cooldown echoes).
            if (API._isHardOfflineError(e)) {
                UI._offlineErrorCount += 1;
                if (UI._offlineErrorCount >= 2) UI.setOfflineMode(true);
            }
            watchlistFailCount = Math.min(watchlistFailCount + 1, 6);
            if (onHome || onWatchlist) {
                try {
                    const cached = localStorage.getItem('appWatchlist');
                    if (cached) {
                        const parsed = JSON.parse(cached);
                        if (cachedState) cachedState.watchlist = parsed;
                        if (onHome) {
                            UI.scheduleRender('home', () => UI.renderAll(cachedState || { tickers: [] }, parsed, (cachedState || {}).scanner, cachedDashboard), 100);
                        } else {
                            UI.scheduleRender('watchlist:cached-fallback', () => UI.renderWatchlist(parsed, cachedState), 100);
                        }
                    }
                } catch (err) { }
            }
        } finally {
            const base = (onHome || onWatchlist) ? 30000 : 45000;  // 30s auto-refresh per spec
            setTimeout(watchlistLoop, dynamicDelay(base, watchlistFailCount, (onHome || onWatchlist) ? 1.0 : 1.3));
        }
    };

    // 3) Scanner loop
    const scannerLoop = async () => {
        const activeView = ViewRouter.activeView || 'home';
        const onHome = activeView === 'home';
        const onScanner = activeView === 'scanner';
        try {
            const scanner = await API.getScannerStateCached();
            if (cachedState) cachedState.scanner = scanner;
            localStorage.setItem('appScanner', JSON.stringify(scanner));
            markRefreshSuccess();
            if (onHome) {
                UI.scheduleRender('home:scanner-loop', () => UI.renderScanner(scanner.hot_tickers, scanner.status), 80);
            }
            if (onScanner) {
                // renderFullScanner draws the movers board too, from the same snapshot.
                UI.scheduleRender('scanner:full-loop', () => UI.renderFullScanner(), 120);
            }
            scannerFailCount = 0;
            // A successful poll proves the server is reachable — clear offline state
            // immediately rather than draining a (possibly inflated) counter one at a time.
            if (UI._offlineErrorCount !== 0) UI._offlineErrorCount = 0;
            UI.setOfflineMode(false);
        } catch (e) {
            if (API.isNetworkFailure(e)) API._warnNetworkOnce('Scanner auto-refresh paused', e);
            else console.error('Scanner auto-refresh error', e);
            scannerFailCount = Math.min(scannerFailCount + 1, 6);
            // Only count hard connection failures toward offline mode (not timeouts/cooldown echoes).
            if (API._isHardOfflineError(e)) {
                UI._offlineErrorCount += 1;
                if (UI._offlineErrorCount >= 2) UI.setOfflineMode(true);
            }
        } finally {
            const base = (onHome || onScanner) ? 15000 : 26000;
            setTimeout(scannerLoop, dynamicDelay(base, scannerFailCount, (onHome || onScanner) ? 1.0 : 1.25));
        }
    };

    coreLoop();
    watchlistLoop();
    scannerLoop();
}

UI.startAutoRefreshWatchdog = function () {
    if (UI._refreshWatchdogTimer) return;
    const recover = (reason) => {
        if (UI._refreshRecoveryInFlight || !navigator.onLine) return UI._refreshRecoveryInFlight;
        API._backendUnavailableUntil = 0;
        UI._offlineErrorCount = 0;
        UI.setOfflineMode(false);
        UI._refreshRecoveryInFlight = UI.refreshCurrentViewData()
            .then(() => {
                UI._lastAutoRefreshSuccessAt = Date.now();
            })
            .catch((e) => API._warnNetworkOnce(`Auto-refresh recovery skipped (${reason})`, e))
            .finally(() => {
                UI._refreshRecoveryInFlight = null;
            });
        return UI._refreshRecoveryInFlight;
    };

    UI._refreshWatchdogTimer = setInterval(() => {
        if (typeof document !== 'undefined' && document.hidden) return;
        const staleMs = Date.now() - Number(UI._lastAutoRefreshSuccessAt || 0);
        if (staleMs > 90000) recover('watchdog');
    }, 30000);

    const resume = () => {
        if (typeof document !== 'undefined' && document.hidden) return;
        const staleMs = Date.now() - Number(UI._lastAutoRefreshSuccessAt || 0);
        if (staleMs > 45000) recover('resume');
    };
    document.addEventListener('visibilitychange', resume);
    window.addEventListener('focus', resume);
    window.addEventListener('pageshow', resume);
};

UI.startNewsAutoRefresh = function () {
    if (UI._newsAutoStarted) return;
    UI._newsAutoStarted = true;
    let newsFailCount = 0;
    
    // Main 60s loop for full news payload
    const mainLoop = async () => {
        try {
            const activeView = ViewRouter.activeView || 'home';
            if (activeView !== 'news' && activeView !== 'home') {
                // Idle: skip the fetch. Rescheduling happens ONLY in finally —
                // a second setTimeout here forks the loop exponentially.
                return;
            }
            // Background poll for Full News Tab data
            const data = await API.getNewsState();
            if (data) {
                // Audio Notifications
                if (cachedNewsData && (data.market_news || data.breaking_news)) {
                    const oldKeys = new Set();
                    const collectKeys = (source) => {
                        if (!source) return;
                        source.forEach(a => {
                            const key = (a.title || a.headline || a.id || '') + (a.published_at || '');
                            if (key) oldKeys.add(key);
                        });
                    };
                    collectKeys(cachedNewsData.market_news);
                    collectKeys(cachedNewsData.breaking_news);
                    if (cachedNewsData.ticker_news) {
                        Object.values(cachedNewsData.ticker_news).forEach(arr => collectKeys(arr));
                    }

                    const newArticles = [];
                    const CHECK_WINDOW_MS = 60 * 60 * 1000;
                    const now = Date.now();

                    // Persistent set of already-alerted articles: the backend news list can
                    // momentarily drop then re-include an article (intermittent source), which
                    // previously re-fired the alert every time it "reappeared". Alert once.
                    if (!UI._alertedNewsKeys) UI._alertedNewsKeys = new Set();
                    const checkNew = (source) => {
                        if (!source) return;
                        source.forEach(a => {
                            const key = (a.title || a.headline || a.id || '') + (a.published_at || '');
                            if (key && !oldKeys.has(key) && !UI._alertedNewsKeys.has(key)) {
                                newArticles.push(a);
                                oldKeys.add(key);
                            }
                        });
                    };

                    checkNew(data.market_news);
                    checkNew(data.breaking_news);
                    if (data.ticker_news) {
                        Object.values(data.ticker_news).forEach(arr => checkNew(arr));
                    }

                    if (newArticles.length > 0) {
                        const recentAlerts = newArticles.filter(a => {
                            if (!a.published_at) return false;
                            const t = new Date(a.published_at).getTime();
                            return (now - t) < CHECK_WINDOW_MS;
                        });

                        let maxImpact = 'low';
                        recentAlerts.forEach(a => {
                            const imp = (a.impact || 'low').toLowerCase();
                            if (imp === 'critical') maxImpact = 'critical';
                            else if (imp === 'high' && maxImpact !== 'critical') maxImpact = 'high';
                        });

                        if (recentAlerts.length > 0) {
                            if (IS_DEV) console.log(`?? Background News: Found ${recentAlerts.length} recent articles. Max impact: ${maxImpact}`);
                            if (maxImpact === 'critical' || maxImpact === 'high' || maxImpact === 'medium') {
                                AudioSystem.playNewsSound(maxImpact);
                            } else {
                                AudioSystem.playNewsSound('medium');
                            }
                            // Remember which stories these are, so the notification can
                            // lead somewhere: the News tab has a "New" focus that lists them.
                            UI.rememberNewNews(recentAlerts);
                            UI.showToast(
                                `${recentAlerts.length} new ${recentAlerts.length === 1 ? 'story' : 'stories'}`,
                                'info',
                                { action: { label: 'View', onClick: () => UI.showNewNews() } },
                            );
                            if (ViewRouter.activeView === 'home') {
                                UI.scheduleRender('home:news-alert', () => UI.renderNews(data), 50);
                            }
                        }
                        // Mark detected-new articles as alerted so a momentary backend drop +
                        // re-include doesn't re-fire the alert for the same article.
                        newArticles.forEach(a => {
                            const k = (a.title || a.headline || a.id || '') + (a.published_at || '');
                            if (k) UI._alertedNewsKeys.add(k);
                        });
                        if (UI._alertedNewsKeys.size > 2000) {
                            UI._alertedNewsKeys = new Set([...UI._alertedNewsKeys].slice(-1000));
                        }
                    }
                }

                // Sticky breaking news: keep recently-seen breaking articles (<60min) that this
                // fetch momentarily dropped, so they don't flicker out and then reappear.
                if (cachedNewsData && Array.isArray(data.breaking_news)) {
                    const prevB = Array.isArray(cachedNewsData.breaking_news) ? cachedNewsData.breaking_news : [];
                    const keyOf = (a) => a.id || ((a.title || '') + (a.published_at || ''));
                    const nextIds = new Set(data.breaking_news.map(keyOf));
                    const nowMs = Date.now();
                    const survivors = prevB.filter(a => {
                        if (nextIds.has(keyOf(a))) return false;
                        const t = a.published_at ? new Date(a.published_at).getTime() : 0;
                        return t > 0 && (nowMs - t) < 60 * 60 * 1000;
                    });
                    if (survivors.length) data.breaking_news = [...data.breaking_news, ...survivors].slice(0, 25);
                }

                cachedNewsData = data;
                if (IS_DEV) console.log('?? News cache auto-updated');
                if (ViewRouter.activeView === 'news') {
                    UI.scheduleRender('news:cockpit-loop', () => UI.renderNewsCockpit(data), 80);
                }
                if (ViewRouter.activeView === 'home') {
                    UI.scheduleRender('home:news-loop', () => UI.renderNews({ ...(cachedState || {}), ...(data || {}) }), 80);
                }
                UI.updateActivityLog(data, null);
            }
            newsFailCount = 0;
        } catch (e) {
            if (API.isNetworkFailure(e)) API._warnNetworkOnce('News auto-refresh paused', e);
            else console.error('News auto-refresh error', e);
            newsFailCount = Math.min(newsFailCount + 1, 6);
        } finally {
            const activeView = ViewRouter.activeView || 'home';
            const offline = !navigator.onLine || UI._offlineErrorCount >= 2;
            const base = (activeView === 'home' || activeView === 'news') ? 60000 : 90000;
            const backoff = newsFailCount > 0 ? Math.min(Math.pow(2, newsFailCount), 8) : 1;
            const delay = UI._jitterDelay(base * backoff * (offline ? 1.8 : 1.0), 0.1);
            setTimeout(mainLoop, delay);
        }
    };
    
    // Fast 15s loop for Breaking News (with inflight dedup)
    let breakingFailCount = 0;
    let breakingInflight = false;
    const breakingLoop = async () => {
        if (breakingInflight) {
            // Skip this cycle · previous request still in flight
            setTimeout(breakingLoop, UI._jitterDelay(15000, 0.1));
            return;
        }
        breakingInflight = true;
        try {
            const activeView = ViewRouter.activeView || 'home';
            if (activeView !== 'news' && activeView !== 'home') {
                // Idle: skip the fetch. finally is the single rescheduler.
                return;
            }
            const res = await API.fetchWithTimeout('/api/news-tab/breaking', { timeout: 10000 });
            if (res.ok) {
                const bdata = await res.json();
                const breaking = bdata.breaking || [];
                if (breaking.length > 0 && typeof AudioSystem !== 'undefined') {
                    // Quick check if any new breaking articles arrived
                    const cachedBreaking = (cachedNewsData?.breaking_news || []);
                    const oldKeys = new Set(cachedBreaking.map(a => (a.title || a.headline || a.id || '') + (a.published_at || '')));
                    if (!UI._alertedNewsKeys) UI._alertedNewsKeys = new Set();
                    const newAlerts = breaking.filter(a => {
                        const key = (a.title || a.headline || a.id || '') + (a.published_at || '');
                        return key && !oldKeys.has(key) && !UI._alertedNewsKeys.has(key);
                    });

                    if (newAlerts.length > 0) {
                        // Alert once per article — a momentary backend drop+re-include must not re-fire.
                        newAlerts.forEach(a => UI._alertedNewsKeys.add((a.title || a.headline || a.id || '') + (a.published_at || '')));
                        const impactRank = { low: 0, medium: 1, high: 2, critical: 3 };
                        const maxImpact = newAlerts.reduce((best, article) => {
                            const impact = String(article?.impact || 'medium').toLowerCase();
                            return (impactRank[impact] || 0) > (impactRank[best] || 0) ? impact : best;
                        }, 'medium');
                        AudioSystem.playNewsSound(maxImpact);
                        UI.showToast(
                            `${maxImpact === 'critical' ? 'CRITICAL NEWS' : 'BREAKING NEWS'}: ${newAlerts[0].title || newAlerts[0].headline}`,
                            maxImpact === 'critical' ? 'error' : 'info'
                        );
                        // Inject into cache to prevent repeated alerts and render
                        if (!cachedNewsData) cachedNewsData = normalizeNewsState({});
                        cachedNewsData.breaking_news = [...newAlerts, ...cachedBreaking].slice(0, 20);
                        if (activeView === 'news') {
                            UI.scheduleRender('news:breaking-loop', () => UI.renderNewsCockpit(cachedNewsData), 50);
                        }
                        if (activeView === 'home') {
                            UI.scheduleRender('home:breaking-loop', () => UI.renderNews({ ...(cachedState || {}), ...cachedNewsData }), 50);
                        }
                    }
                }
            }
            breakingFailCount = 0;
        } catch (e) {
            breakingFailCount = Math.min(breakingFailCount + 1, 6);
        } finally {
            const view = ViewRouter.activeView || 'home';
            const base = (view === 'home' || view === 'news') ? 45000 : 60000;
            const backoff = breakingFailCount > 0 ? Math.min(Math.pow(2, breakingFailCount), 16) : 1;
            setTimeout(breakingLoop, UI._jitterDelay(base * backoff, 0.1));
            breakingInflight = false;
        }
    };

    // Background prefetch: keep the heavier per-tab caches warm so switching tabs renders
    // instantly from cache instead of waiting seconds for a cold fetch. Rotates one tab per
    // cycle, skips the active view (its own loop handles it), pauses when the page is hidden
    // or offline, and only warms data (the load helpers render only when their view is active).
    let _prefetchIdx = 0;
    const prefetchLoop = async () => {
        try {
            const hidden = (typeof document !== 'undefined' && document.visibilityState === 'hidden');
            if (navigator.onLine && (UI._offlineErrorCount || 0) < 2 && !hidden) {
                const active = (typeof ViewRouter !== 'undefined' && ViewRouter.activeView) || 'home';
                const tasks = [
                    ['premarket', () => UI.loadPremarketScannerData(false)],
                    ['preearnings', () => UI.loadPreEarningsData(false)],
                    ['traderadar', () => UI.loadTradeRadarData(false)],
                    // Calendar warms its range cache via renderFullCalendar (renders into the
                    // hidden calendar wrapper); on navigate it then hits the cache instantly.
                    ['calendar', () => (typeof Actions !== 'undefined' && Actions.renderFullCalendar)
                        ? Actions.renderFullCalendar((Actions.calendarState && Actions.calendarState.currentDate) || new Date())
                        : Promise.resolve()],
                ];
                const [view, fn] = tasks[_prefetchIdx % tasks.length];
                _prefetchIdx++;
                if (view !== active) {
                    await fn().catch(() => {});
                }
            }
        } catch (e) { /* ignore prefetch errors */ }
        finally {
            // ~12s between tabs -> each warmed roughly every 36s.
            setTimeout(prefetchLoop, UI._jitterDelay(12000, 0.2));
        }
    };
    setTimeout(prefetchLoop, 5000); // start after the initial page load settles

    mainLoop();
    breakingLoop();
};

/* --- CALENDAR PAGE LOGIC --- */

// Pure helpers for the Calendar tab (no DOM) — covered by
// tests/frontend/tab_audit_calendar_alerts.cjs.
Actions.calendarUtil = {
    MONTHS: ["January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"],

    // "November 2026 – January 2027" when the range crosses a year, else
    // "March – May 2026". The old title printed one year for both ends.
    rangeTitle(months) {
        const first = months[0], last = months[months.length - 1];
        const M = this.MONTHS;
        if (first.getFullYear() === last.getFullYear()) {
            return `${M[first.getMonth()]} – ${M[last.getMonth()]} ${last.getFullYear()}`;
        }
        return `${M[first.getMonth()]} ${first.getFullYear()} – ${M[last.getMonth()]} ${last.getFullYear()}`;
    },

    // Calendar day (YYYY-MM-DD) an event belongs to. date_formatted carries
    // the provider's own day (US Eastern for macro releases); slicing the UTC
    // ISO string or running it through new Date() can move it a day.
    dayKey(e) {
        const raw = String((e && (e.date_formatted || e.date)) || '');
        const m = raw.match(/^(\d{4}-\d{2}-\d{2})/);
        return m ? m[1] : '';
    },

    // Local-midnight Date for a YYYY-MM-DD key (new Date('2026-11-05') is UTC
    // midnight, i.e. the previous day in US time zones).
    parseDay(key) {
        const m = String(key || '').match(/^(\d{4})-(\d{2})-(\d{2})/);
        return m ? new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
    },

    isHighImpact(e) {
        return String((e && e.impact) || '').toLowerCase() === 'high';
    },

    // 10 watchlist earnings · 5 high-impact macro · 4 other earnings ·
    // 3 other macro · 1 IPO/other. Earnings carry impact "high" on every row,
    // so impact only ranks economic events.
    eventPriority(e) {
        if (e.type === 'earnings') return e.is_watchlist ? 10 : 4;
        if (e.type === 'economic') return this.isHighImpact(e) ? 5 : 3;
        return 1;
    },

    // Within one day: priority, then largest market cap first (a day can hold
    // 500+ reporters — the four visible ones must be the ones that matter),
    // then alphabetical so the order is stable.
    compareEvents(a, b) {
        const U = Actions.calendarUtil;
        const prio = U.eventPriority(b) - U.eventPriority(a);
        if (prio !== 0) return prio;
        const capA = Number(a.market_cap), capB = Number(b.market_cap);
        const hasA = Number.isFinite(capA) && capA > 0, hasB = Number.isFinite(capB) && capB > 0;
        if (hasA !== hasB) return hasA ? -1 : 1;
        if (hasA && capA !== capB) return capB - capA;
        return String(a.symbol || a.title || '').localeCompare(String(b.symbol || b.title || ''));
    },

    sessionText(e) {
        const when = String((e && e.when) || '').toLowerCase();
        if (when === 'bmo') return 'Before market open';
        if (when === 'amc') return 'After market close';
        return 'Time not announced';
    },

    // How much the session label can be trusted, in the provider's own terms.
    sessionConfidenceText(e) {
        const when = String((e && e.when) || '').toLowerCase();
        if (when !== 'bmo' && when !== 'amc') return '';
        const c = String((e && e.session_confidence) || '').toLowerCase();
        if (c === 'cross_provider') return 'two providers agree';
        if (c === 'provider') return 'single provider';
        if (c === 'official') return 'company-confirmed';
        if (c === 'inferred') return 'inferred, not announced';
        return 'unverified';
    },

    sourceText(e) {
        const s = String((e && e.source) || '').toLowerCase();
        if (!s || s === 'unknown') return '';
        if (s.includes('nasdaq')) return 'Nasdaq / Zacks estimate';
        if (s === 'yfinance+calendar') return 'Yahoo Finance + earnings calendar';
        if (s.includes('yfinance')) return 'Yahoo Finance';
        if (s.includes('finnhub')) return 'Finnhub';
        return String(e.source);
    },

    dateConfidenceText(e) {
        const c = String((e && e.date_confidence) || '').toLowerCase();
        if (c === 'estimated') return 'Estimated date — not confirmed by the company';
        if (c === 'high') return e && e.confirmed ? 'Date confirmed by provider' : 'Provider date';
        if (c === 'medium') return 'Provider date, single source';
        return e && e.confirmed ? 'Date confirmed by provider' : 'Date not confirmed';
    },

    // Only macro releases with a published clock time have a real time of
    // day. Earnings and FOMC rows are date-only ("…T00:00:00") and used to be
    // printed as "00:00".
    hasClockTime(e) {
        if (!e || e.type !== 'economic') return false;
        if (e.time_precision === 'date_only') return false;
        return /T\d{2}:\d{2}/.test(String(e.date || '')) && !/T00:00(:00)?($|[^\d])/.test(String(e.date || ''));
    },

    // "15:30 (08:30 ET)" — viewer's local time plus the published ET time.
    timeText(e) {
        if (!this.hasClockTime(e)) return '';
        const d = new Date(e.date);
        if (Number.isNaN(d.getTime())) return '';
        const local = d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit' });
        const et = String(e.date_formatted || '').match(/(\d{2}:\d{2}) ET/);
        return et ? `${local} (${et[1]} ET)` : local;
    },

    marketCapText(v) {
        const n = Number(v);
        if (!Number.isFinite(n) || n <= 0) return '';
        if (n >= 1e12) return `$${(n / 1e12).toFixed(2)}T`;
        if (n >= 1e9) return `$${(n / 1e9).toFixed(1)}B`;
        if (n >= 1e6) return `$${(n / 1e6).toFixed(0)}M`;
        return `$${Math.round(n).toLocaleString('en-US')}`;
    },

    ageText(seconds) {
        const s = Number(seconds);
        if (!Number.isFinite(s) || s < 0) return 'unknown';
        if (s < 90) return 'just now';
        if (s < 5400) return `${Math.round(s / 60)} min ago`;
        if (s < 172800) return `${Math.round(s / 3600)} h ago`;
        return `${Math.round(s / 86400)} days ago`;
    },

    // Plain-language notes about what the data does NOT cover, built from the
    // server's coverage block. level: 'warn' | 'info'.
    coverageNotes(coverage, rangeStartKey, rangeEndKey, extraAgeSeconds) {
        const notes = [];
        if (!coverage || typeof coverage !== 'object') {
            notes.push({ level: 'warn', text: 'Data age and coverage are unknown (server did not report them).' });
            return notes;
        }
        const ea = coverage.earnings || {};
        const extra = Number(extraAgeSeconds) > 0 ? Number(extraAgeSeconds) : 0;
        if (coverage.agent_disabled) {
            notes.push({ level: 'warn', text: 'Calendar agent is switched off — showing the last saved data, nothing is being refreshed.' });
        }
        if (ea.fetched_at == null) {
            notes.push({ level: 'warn', text: 'Earnings list has not been refreshed since the server started — dates shown come from an older saved copy.' });
        } else {
            const age = Number(ea.age_seconds) + extra;
            notes.push({
                level: ea.stale ? 'warn' : 'info',
                text: `Earnings list ${ea.stale ? 'is stale — last refreshed' : 'refreshed'} ${this.ageText(age)}`
                    + (ea.dates_are_estimates ? ' (Nasdaq/Zacks estimates; dates can move until the company confirms).' : '.'),
            });
        }
        if (ea.last_error) {
            notes.push({ level: 'warn', text: `Last earnings refresh failed: ${ea.last_error}` });
        }
        if (ea.window_end && rangeEndKey && ea.window_end < rangeEndKey) {
            const d = this.parseDay(ea.window_end);
            const label = d ? d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : ea.window_end;
            notes.push({ level: 'warn', text: `Earnings are only listed through ${label}. Later days are not covered yet — an empty day there does not mean nobody reports.` });
        }
        const macro = coverage.macro || {};
        // A year whose schedule file is missing or cannot be read has no macro releases.
        const macroYears = [macro.years_missing, macro.years_unreadable]
            .reduce((all, list) => all.concat(Array.isArray(list) ? list : []), [])
            .map(year => String(year))
            .filter((year, index, all) => year && all.indexOf(year) === index);
        if (macroYears.length) {
            notes.push({ level: 'warn', text: `Not configured: US macro release schedule for ${macroYears.join(', ')} (CPI, Jobs, PCE, GDP, Retail Sales). Only FOMC meetings are shown for that period; the schedule has to be added to the configuration.` });
        }
        // Years published only in part: the server sends one ready sentence per year.
        (Array.isArray(macro.partial_notes) ? macro.partial_notes : []).forEach(text => {
            const sentence = String(text == null ? '' : text).trim();
            if (sentence) notes.push({ level: 'warn', text: sentence });
        });
        const ipo = coverage.ipo || {};
        if (ipo.available === false) {
            notes.push({ level: 'info', text: 'Not configured: IPO data provider. IPO listings are unavailable until one is set up.' });
        }
        return notes;
    },
};

Actions.calendarState = {
    currentDate: new Date()
};

Actions.initCalendarPage = function () {
    Actions.renderFullCalendar(Actions.calendarState.currentDate);
};

Actions.renderFullCalendar = async function (centerDate) {
    // Fix: If called from toggle event (no args), use current state
    if (!centerDate) centerDate = Actions.calendarState.currentDate || new Date();

    // Update state to preserve view on next toggle
    Actions.calendarState.currentDate = centerDate;
    const wrapper = document.getElementById('calendar-months-wrapper');
    if (!wrapper) return;

    const mNames = ["January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"];

    // Define the 3 months to show: Current, Next, Next+1
    const targetMonths = [];
    for (let i = 0; i <= 2; i++) {
        targetMonths.push(new Date(centerDate.getFullYear(), centerDate.getMonth() + i, 1));
    }

    // Update Header Text — both ends carry their year when the range crosses
    // New Year ("November 2026 – January 2027", not "November - January 2026").
    const headerText = Actions.calendarUtil.rangeTitle(targetMonths);
    const headerEl = document.getElementById('cal-current-month');
    if (headerEl) headerEl.textContent = headerText;

    // Overlapping renders (fast prev/next clicks, the background prefetch):
    // only the latest one may paint, or a slow older response overwrites it.
    const renderSeq = (Actions._calendarRenderSeq = (Actions._calendarRenderSeq || 0) + 1);

    // Helper: Format YYYY-MM-DD
    const formatDate = (d) => {
        const y = d.getFullYear();
        const m = String(d.getMonth() + 1).padStart(2, '0');
        const day = String(d.getDate()).padStart(2, '0');
        return `${y}-${m}-${day}`;
    };

    const getGridBounds = (date) => {
        const y = date.getFullYear(), m = date.getMonth();
        const first = new Date(y, m, 1);
        const last = new Date(y, m + 1, 0);

        const start = new Date(first);
        start.setDate(start.getDate() - start.getDay()); // Sunday

        const end = new Date(last);
        if (end.getDay() !== 6) end.setDate(end.getDate() + (6 - end.getDay())); // Saturday
        return { start, end };
    };

    const globalStart = getGridBounds(targetMonths[0]).start;
    const globalEnd = getGridBounds(targetMonths[2]).end;

    try {
        const apiStart = formatDate(globalStart);
        const apiEnd = formatDate(globalEnd);
        Actions._ensureCalendarCachesLoaded();
        const currentSig = Actions.getWatchlistSignature();
        if (currentSig && currentSig !== Actions._watchlistSig) {
            Actions._watchlistSig = currentSig;
            try { localStorage.setItem('calendar_watchlist_sig', currentSig); } catch (e) { }
            Actions.clearCalendarCache();
        }
        const sigForKey = Actions._watchlistSig || '';
        const cacheKey = `${apiStart}_${apiEnd}_${sigForKey}`;

        // Initialize cache if needed
        if (!Actions.calendarRangeCache) Actions.calendarRangeCache = {};

        let data;
        let refreshError = null;

        // CHECK CACHE. An entry is reused only for 10 minutes: the in-memory
        // copy had no expiry at all, so a tab left open kept showing the grid
        // it loaded first (and "today" from that day) indefinitely.
        const CAL_RANGE_TTL_MS = 10 * 60 * 1000;
        if (!Actions._calendarRangeMemTs) Actions._calendarRangeMemTs = {};
        const cachedEntry = Actions.calendarRangeCache[cacheKey];
        const cachedAt = Number(Actions._calendarRangeMemTs[cacheKey] || 0);
        if (cachedEntry && cachedAt && (Date.now() - cachedAt) < CAL_RANGE_TTL_MS) {
            if (IS_DEV) console.log('Using cached calendar data for', cacheKey);
            data = cachedEntry;
        } else {
            if (!cachedEntry) {
                wrapper.innerHTML = '<div class="cal-state">Loading events for three months…</div>';
            }
            try {
                // FETCH
                const response = await fetch(`/api/calendar/range?start=${apiStart}&end=${apiEnd}`);
                if (!response.ok) throw new Error(`server answered ${response.status}`);
                data = await response.json();

                // SAVE TO CACHE
                Actions.calendarRangeCache[cacheKey] = data;
                Actions._calendarRangeMemTs[cacheKey] = Date.now();
                if (Actions._touchCalendarCacheTs) Actions._touchCalendarCacheTs(cacheKey);
                Actions._persistCalendarCaches();
            } catch (fetchErr) {
                // Keep the older copy on screen, but say that it is old.
                if (!cachedEntry) throw fetchErr;
                data = cachedEntry;
                refreshError = fetchErr;
            }
        }
        if (renderSeq !== Actions._calendarRenderSeq) return; // a newer render took over

        Actions.calendarEventsCache = {}; // Cache for modal lookup
        const calUtil = Actions.calendarUtil;
        const escCal = UI._escapeHtml || ((value) => String(value ?? ''));

        // Group events
        const eventsByDate = {};
        const addEvent = (e, type) => {
            const d = calUtil.dayKey(e);
            if (!d) return; // no usable date — cannot be placed on a day
            if (!eventsByDate[d]) eventsByDate[d] = [];
            e.type = type;
            // Generate ID for interaction. The id is built from provider text
            // (symbols) and lands inside an inline onclick, so the lookup key
            // is reduced to characters that cannot end the JS string.
            if (!e.id) e.id = 'evt_' + Math.random().toString(36).substr(2, 9);
            e._cid = String(e.id).replace(/[^A-Za-z0-9_.:\-^=]/g, '_');
            Actions.calendarEventsCache[e._cid] = e;

            eventsByDate[d].push(e);
        };
        (data.economic || []).forEach(e => addEvent(e, 'economic'));
        (data.earnings || []).forEach(e => addEvent(e, 'earnings'));
        (data.ipo || []).forEach(e => addEvent(e, 'ipo'));

        // Expose eventsByDate for the "View All" modal to access
        Actions.currentEventsByDate = eventsByDate;
        Actions._calendarCurrentData = data;

        // Render
        wrapper.innerHTML = '';

        const todayStr = formatDate(new Date());

        // Coverage / freshness strip above the grid: data age, how far the
        // earnings list reaches, missing macro years, no IPO feed, a failed
        // refresh. Without it an uncovered month looked like "no events".
        try {
            let noteEl = document.getElementById('calendar-status-note');
            const gridCard = wrapper.parentElement;
            if (!noteEl && gridCard && gridCard.parentElement) {
                noteEl = document.createElement('div');
                noteEl.id = 'calendar-status-note';
                noteEl.className = 'cal-status';
                gridCard.parentElement.insertBefore(noteEl, gridCard);
            }
            if (noteEl) {
                const coverage = data.coverage;
                const generatedMs = coverage && coverage.generated_at ? Date.parse(coverage.generated_at) : NaN;
                const extraAge = Number.isFinite(generatedMs) ? Math.max(0, (Date.now() - generatedMs) / 1000) : 0;
                const notes = calUtil.coverageNotes(coverage, apiStart, apiEnd, extraAge);
                if (refreshError) {
                    notes.unshift({ level: 'warn', text: `Could not refresh the calendar (${refreshError.message || 'network error'}) — showing the copy loaded earlier.` });
                }
                noteEl.innerHTML = notes.map(n => `
                    <div class="cal-status-item cal-status-item--${n.level === 'warn' ? 'warn' : 'info'}">
                        <i class="fa-solid ${n.level === 'warn' ? 'fa-triangle-exclamation' : 'fa-circle-info'}" aria-hidden="true"></i><span>${escCal(n.text)}</span>
                    </div>`).join('');
                const ipoDot = document.querySelector('#view-calendar .calendar-legend .dot-indicator.ipo');
                if (ipoDot && ipoDot.parentElement) {
                    const ipoOff = !!(coverage && coverage.ipo && coverage.ipo.available === false);
                    ipoDot.parentElement.classList.toggle('is-unavailable', ipoOff);
                    ipoDot.parentElement.title = ipoOff ? 'Not configured: IPO data provider. IPO listings are unavailable until one is set up.' : '';
                    ipoDot.parentElement.lastChild.textContent = ipoOff ? ' IPO (unavailable)' : ' IPO';
                }
            }
        } catch (noteErr) {
            console.warn('Calendar status note failed:', noteErr);
        }

        targetMonths.forEach(monthDate => {
            const { start, end } = getGridBounds(monthDate);

            const section = document.createElement('div');
            section.className = 'calendar-month-section';

            const title = document.createElement('div');
            title.className = 'month-section-title';
            title.textContent = `${mNames[monthDate.getMonth()]} ${monthDate.getFullYear()}`;
            section.appendChild(title);

            // NEW: Inject Weekday Header INSIDE the section
            const weekHeader = document.createElement('div');
            weekHeader.className = 'calendar-week-header-inner';
            weekHeader.innerHTML = `
                <div>Sun</div><div>Mon</div><div>Tue</div><div>Wed</div><div>Thu</div><div>Fri</div><div>Sat</div>
            `;
            section.appendChild(weekHeader);

            const grid = document.createElement('div');
            grid.className = 'calendar-month-grid';

            let cur = new Date(start);
            let limit = 0;
            while (cur <= end && limit < 42) {
                limit++;
                const dateStr = formatDate(cur);
                const isOtherMonth = cur.getMonth() !== monthDate.getMonth();
                const isToday = dateStr === todayStr;
                const isPast = dateStr < todayStr;

                const cell = document.createElement('div');
                cell.className = 'calendar-day-cell';

                // Leading/trailing days of the neighbouring month only fill
                // the week row. They used to carry their full event list, so
                // every overflow week (e.g. Dec 1\u20135) was printed twice \u2014 once
                // under November and again under December.
                if (isOtherMonth) {
                    cell.classList.add('other-month');
                    cell.innerHTML = `<div class="day-number"><span>${cur.getDate()}</span></div>`;
                    grid.appendChild(cell);
                    cur.setDate(cur.getDate() + 1);
                    continue;
                }

                // Watchlist first, then high-impact macro, then earnings by
                // market cap (largest first).
                const dayEvents = (eventsByDate[dateStr] || []).slice().sort(calUtil.compareEvents);
                eventsByDate[dateStr] = dayEvents;

                // "today" keeps an inline, important fill so it stays visible
                // whatever the stylesheet does to cells; past and other-month
                // days are styled by class (.past / .other-month).
                if (isToday) {
                    cell.classList.add('today');
                    if (typeof cell.setAttribute === 'function') cell.setAttribute('aria-current', 'date');
                    cell.style.setProperty('background', 'var(--ds-amber-soft, rgba(245, 158, 11, 0.12))', 'important');
                } else if (isPast) {
                    cell.classList.add('past');
                }

                const MAX_SHOWN = 4;
                const shown = dayEvents.slice(0, MAX_SHOWN);
                const hidden = dayEvents.length - MAX_SHOWN;

                let evHtml = shown.map(e => {
                    const label = String(e.symbol || e.title || 'Event');
                    let css = e.type;
                    if (e.type === 'economic' && calUtil.isHighImpact(e)) css += ' high-impact';

                    // The full label is printed; the stylesheet cuts it to
                    // the cell width with an ellipsis.
                    const tip = e.type === 'earnings'
                        ? `${label}${e.company_name ? ' \u2014 ' + e.company_name : ''} \u00b7 ${calUtil.sessionText(e)}`
                        : `${label}${calUtil.timeText(e) ? ' \u00b7 ' + calUtil.timeText(e) : ''}`;

                    return `<button type="button" class="cal-event-pill ${css} ${e.is_watchlist ? 'watchlist-highlight' : ''}" title="${escCal(tip)}" onclick="Actions.openEventModal('${e._cid}')">
                                ${e.is_watchlist ? '<span class="cal-star" aria-hidden="true">\u2605</span>' : `<span class="dot-indicator ${e.type}"></span>`}<span class="cal-pill-label">${escCal(label)}</span>
                            </button>`;
                }).join('');

                if (hidden > 0) evHtml += `<button type="button" class="cal-more-events" onclick="Actions.openDayModal('${dateStr}')">+${hidden} more</button>`;

                // data-dow feeds the stacked phone layout ("Mon 16"); the
                // visual order of number and tag is set by the stylesheet.
                const dow = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][cur.getDay()];
                cell.innerHTML = `
                    <div class="day-number" data-dow="${dow}" style="${isToday ? 'flex-direction:row-reverse; justify-content:space-between; align-items:center;' : ''}"><span>${cur.getDate()}</span>${isToday ? ' <span class="cal-today-tag">TODAY</span>' : ''}</div>
                    <div class="cal-daily-events">${evHtml}</div>
                `;

                grid.appendChild(cell);
                cur.setDate(cur.getDate() + 1);
            }

            section.appendChild(grid);
            wrapper.appendChild(section);
        });

    } catch (error) {
        console.error("Calendar 3-month error:", error);
        if (renderSeq !== Actions._calendarRenderSeq) return;
        const escErr = UI._escapeHtml || ((value) => String(value ?? ''));
        const staleNote = document.getElementById('calendar-status-note');
        if (staleNote) staleNote.innerHTML = '';
        wrapper.innerHTML = `<div class="cal-state cal-state--error">
            <strong>Calendar could not be loaded</strong>
            <p>${escErr((error && error.message) || 'Unknown error')}</p>
            <button type="button" class="btn-secondary" onclick="Actions.initCalendarPage()">Retry</button>
        </div>`;
    }
};

Actions.openEventModal = function (eventId) {
    const event = Actions.calendarEventsCache[eventId];
    if (!event) return;

    // Remove existing
    const existing = document.getElementById('cal-event-modal');
    if (existing) existing.remove();

    // Data Format
    let categoryClass = event.type;
    let badgeLabel = (event.type === 'earnings' ? 'Earnings report' : (event.type === 'ipo' ? 'IPO listing' : 'Economic event'));

    let statsHtml = '';

    // Helper for null checks
    const esc = UI._escapeHtml || ((value) => String(value ?? ''));
    const calUtil = Actions.calendarUtil;
    // Every value is provider text → escaped. Missing values read "N/A";
    // fmtMoney used to print "$NaN" for rows without a revenue field.
    const valOr = (v, alt = 'N/A') => (v !== null && v !== undefined && v !== '') ? esc(v) : alt;
    const fmtMoney = (v) => {
        const n = Number(v);
        return (v !== null && v !== undefined && v !== '' && Number.isFinite(n)) ? '$' + n.toLocaleString('en-US') : 'N/A';
    };
    const eventDay = calUtil.parseDay(calUtil.dayKey(event));
    const todayMidnight = new Date(); todayMidnight.setHours(0, 0, 0, 0);
    const isPastEvent = !!(eventDay && eventDay < todayMidnight);
    const sourceUrl = (() => {
        try {
            const parsed = new URL(String(event.source_url || ''), window.location.origin);
            return ['http:', 'https:'].includes(parsed.protocol) ? parsed.href : '';
        } catch (_) {
            return '';
        }
    })();
    const sourceName = String(event.source_name || '').trim();
    const provenanceHtml = sourceName || sourceUrl ? `
        <div class="modal-footer-date">
            <span>${sourceUrl ? `<a href="${esc(sourceUrl)}" target="_blank" rel="noopener noreferrer">${esc(sourceName || 'View source')}</a>` : `Source: ${esc(sourceName)}`}</span>
            ${event.time_precision === 'date_only' ? '<small>Date only — no release time was assumed.</small>' : ''}
        </div>` : '';

    if (event.type === 'earnings') {
        // Session + how far it can be trusted, the date's confidence and the
        // source — the box used to print the raw code ("UNKNOWN", "BMO").
        const sessionConfidence = calUtil.sessionConfidenceText(event);
        const sourceText = calUtil.sourceText(event);
        const capText = calUtil.marketCapText(event.market_cap);
        statsHtml = `
            ${event.company_name ? `<div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Company</div>
                <div class="modal-stat-value modal-stat-value--text">${esc(event.company_name)}${capText ? ` <small>· market cap ${esc(capText)}</small>` : ''}</div>
            </div>` : ''}
            <div class="modal-stat-box">
                <div class="modal-stat-label">EPS estimate</div>
                <div class="modal-stat-value">${valOr(event.eps_estimated)}</div>
            </div>
            <div class="modal-stat-box">
                <div class="modal-stat-label">EPS actual</div>
                <div class="modal-stat-value">${valOr(event.eps_actual, isPastEvent ? 'Not in feed' : 'Not reported yet')}</div>
            </div>
            <div class="modal-stat-box">
                <div class="modal-stat-label">Revenue estimate</div>
                <div class="modal-stat-value">${fmtMoney(event.revenue_estimated)}</div>
            </div>
            <div class="modal-stat-box">
                <div class="modal-stat-label">Revenue actual</div>
                <div class="modal-stat-value">${fmtMoney(event.revenue_actual)}</div>
            </div>
            <div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Report session</div>
                <div class="modal-stat-value modal-stat-value--text">${esc(calUtil.sessionText(event))}${sessionConfidence ? ` <small>(${esc(sessionConfidence)})</small>` : ''}</div>
            </div>
            <div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Date reliability</div>
                <div class="modal-stat-value modal-stat-value--text">${esc(calUtil.dateConfidenceText(event))}${sourceText ? ` <small class="modal-stat-note--block">Source: ${esc(sourceText)}${event.fiscal_period ? ' · fiscal period ' + esc(event.fiscal_period) : ''}</small>` : ''}</div>
            </div>
        `;
    } else if (event.type === 'ipo') {
        statsHtml = `
            <div class="modal-stat-box">
                <div class="modal-stat-label">Exchange</div>
                <div class="modal-stat-value">${valOr(event.exchange)}</div>
            </div>
            <div class="modal-stat-box">
                <div class="modal-stat-label">Price range</div>
                <div class="modal-stat-value">${valOr(event.price_range)}</div>
            </div>
        `;
    } else {
        // Economic
        const impactClass = calUtil.isHighImpact(event) ? ' modal-stat-value--high' : '';
        const timeText = calUtil.timeText(event);
        // Schedule-only rows (official release calendar, FOMC dates) carry no
        // actual/forecast/previous — show the release time instead of a wall
        // of empty boxes. `estimate || forecast` used to always print "-".
        const hasFigures = [event.actual, event.forecast, event.estimate, event.previous]
            .some(v => v !== null && v !== undefined && v !== '');
        const forecastValue = (event.forecast !== null && event.forecast !== undefined && event.forecast !== '') ? event.forecast : event.estimate;
        statsHtml = `
             <div class="modal-stat-box">
                <div class="modal-stat-label">Release time</div>
                <div class="modal-stat-value">${timeText ? esc(timeText) : 'Not published'}</div>
            </div>
             <div class="modal-stat-box">
                <div class="modal-stat-label">Impact</div>
                <div class="modal-stat-value modal-stat-value--text modal-stat-value--impact${impactClass}">${valOr(event.impact)}</div>
            </div>
            ${hasFigures ? `
             <div class="modal-stat-box">
                <div class="modal-stat-label">Actual</div>
                <div class="modal-stat-value">${valOr(event.actual, isPastEvent ? 'N/A' : 'Not released yet')}</div>
            </div>
             <div class="modal-stat-box">
                <div class="modal-stat-label">Forecast</div>
                <div class="modal-stat-value">${valOr(forecastValue)}</div>
            </div>
             <div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Previous</div>
                <div class="modal-stat-value">${valOr(event.previous)}</div>
            </div>` : `
             <div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Figures</div>
                <div class="modal-stat-value modal-stat-value--text">Schedule only — forecast and actual values are not provided by this source.</div>
            </div>`}
            ${event.description ? `
             <div class="modal-stat-box modal-stat-box--wide">
                <div class="modal-stat-label">Details</div>
                <div class="modal-stat-value modal-stat-value--text">${esc(event.description)}</div>
            </div>` : ''}
        `;
    }

    const modal = document.createElement('div');
    modal.id = 'cal-event-modal';
    // Use GLOBAL classes: modal-overlay (not cal-modal-overlay)
    modal.className = 'modal-overlay';
    modal.style.display = 'flex'; // Force display flex for centering
    modal.onclick = (e) => { if (e.target === modal) Actions.closeEventModal(); };

    // The event's own calendar day (see calendarUtil.dayKey) — new Date() on a
    // "+00:00" midnight stamp showed the previous day west of UTC.
    const dateStr = eventDay
        ? eventDay.toLocaleDateString("en-US", { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
        : 'Date unknown';

    // Use GLOBAL classes: modal-content, modal-header, modal-body
    modal.innerHTML = `
        <div class="modal-content" role="dialog" aria-modal="true" aria-labelledby="cal-event-modal-title">
            <div class="modal-header">
                <div class="cal-event-head">
                    <h3 id="cal-event-modal-title">${event.is_watchlist ? '<span class="cal-star" title="On your watchlist">★</span> ' : ''}${esc(event.symbol || event.title || 'Event')}</h3>
                    <div class="cal-event-sub">
                        <span class="modal-event-badge ${categoryClass}">${badgeLabel}</span>
                        <span class="cal-event-date">${esc(dateStr)}${isPastEvent ? ' (past)' : ''}</span>
                    </div>
                </div>
                <button class="btn-icon" onclick="Actions.closeEventModal()" aria-label="Close"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button>
            </div>
            <div class="modal-body">
                <div class="modal-data-grid">
                    ${statsHtml}
                </div>
                ${provenanceHtml}
            </div>
        </div>
    `;

    document.body.appendChild(modal);
};

Actions.closeEventModal = function () {
    const el = document.getElementById('cal-event-modal');
    if (el) el.remove();
};

Actions.calendarNextMonth = function () {
    // Jump 3 months forward. Anchor on the 1st: setMonth() on the 29th–31st
    // overflows into the following month (31 Aug + 3 → "31 Nov" = 1 Dec) and
    // the view skipped a month.
    const cur = Actions.calendarState.currentDate || new Date();
    Actions.calendarState.currentDate = new Date(cur.getFullYear(), cur.getMonth() + 3, 1);
    Actions.initCalendarPage();
};

Actions.calendarPrevMonth = function () {
    // Jump 3 months back (same 1st-of-month anchor as calendarNextMonth)
    const cur = Actions.calendarState.currentDate || new Date();
    Actions.calendarState.currentDate = new Date(cur.getFullYear(), cur.getMonth() - 3, 1);
    Actions.initCalendarPage();
};

Actions.calendarGoToday = function () {
    Actions.calendarState.currentDate = new Date();
    Actions.initCalendarPage();
};

// ============ ADD TICKER MODAL ============
Actions.addTicker = function () {
    const modal = document.getElementById('add-ticker-modal');
    if (modal) {
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
        // Focus input
        const input = document.getElementById('add-ticker-input');
        if (input) {
            input.value = '';
            input.focus();
        }
        Actions._setAddTickerMessage('');
    }
};

// Message inside the Add ticker dialog. With `offerForce` it carries the "Add anyway"
// button, which repeats the request with force:true.
Actions._setAddTickerMessage = function (message, offerForce) {
    const box = document.getElementById('add-ticker-message');
    if (!box) return false;
    const text = String(message || '').trim();
    box.hidden = !text;
    box.innerHTML = text
        ? `<span>${UI._escapeHtml(text)}</span>${offerForce ? '<button type="button" class="ds-btn ds-btn--sm" data-testid="add-ticker-force" onclick="Actions.confirmAddTicker({ force: true })">Add anyway</button>' : ''}`
        : '';
    return true;
};

Actions.closeAddTickerModal = function () {
    const modal = document.getElementById('add-ticker-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
};

Actions.confirmAddTicker = async function (options) {
    const force = !!(options && options.force === true);
    const input = document.getElementById('add-ticker-input');
    if (!input) return;
    Actions._setAddTickerMessage('');

    const ticker = input.value.trim().toUpperCase();
    if (!ticker) {
        UI.showToast('Please enter a valid ticker!', 'error');
        return;
    }

    const inWatchlist = (watchlist, symbol) => {
        if (!watchlist || !symbol) return false;
        const normalized = String(symbol).toUpperCase();
        const groups = ['stocks', 'crypto', 'yahoo', 'binance', 'order', 'hot_list', 'forex'];
        return groups.some((key) => {
            const items = watchlist[key];
            return Array.isArray(items) && items.some((t) => String(t || '').toUpperCase() === normalized);
        });
    };

    try {
        const currentWatchlist = await API.getWatchlistCached(15000);
        if (inWatchlist(currentWatchlist, ticker)) {
            UI.showToast(`${ticker} is already in watchlist.`, 'warning');
            Actions.closeAddTickerModal();
            return;
        }

        let addResult = null;
        let addError = null;
        try {
            addResult = await API.addTicker(ticker, force ? { return_state: false, force: true } : { return_state: false });
        } catch (error) {
            addError = error;
        }
        const outcome = UI._addTickerOutcome(addResult, addError);
        if (outcome.needsForce && !force) {
            // The server found no quote and added nothing: show its message and let
            // the owner decide. "Add anyway" repeats the request with force:true.
            if (!Actions._setAddTickerMessage(`${ticker}: ${outcome.message}`, true)) {
                UI.showToast(`${ticker}: ${outcome.message}`, 'warning', { action: { label: 'Add anyway', onClick: () => Actions.confirmAddTicker({ force: true }) } });
            }
            return;
        }
        if (addError) throw addError;
        UI.watchlistRemovedTickers.delete(ticker);
        UI.watchlistSelectedTickers.delete(ticker);
        const wasAdded = !outcome.already;
        if (!wasAdded) {
            UI.showToast(`${ticker} is already in watchlist.`, 'info');
        } else {
            const added = UI._addTickerToast(ticker, outcome);
            UI.showToast(added.text, added.type);
        }
        Actions.closeAddTickerModal();

        // Mark as NEW for 10 seconds only when newly added
        if (wasAdded) UI.markTickerAsNew(ticker);

        // Refresh watchlist
        const state = await API.getState();
        cachedState = UI.mergeStatePreserveDetails(cachedState, state);
        UI.renderWatchlist(state.watchlist, state);
    } catch (e) {
        console.error(e);
        UI.showToast(`Error adding: ${e.message}`, 'error');
    }
};

Actions.saveAiIdeaToCarnet = async function (ticker, encodedIdea) {
    if (!ticker || !encodedIdea) return;

    let ideaText = encodedIdea;
    try {
        ideaText = decodeURIComponent(encodedIdea);
    } catch (e) {
        // ignore decode errors
    }

    const description = `AI Ollama:
${ideaText}`.trim();

    UI.showToast('Saving AI idea to notebook...', 'info');

    try {
        const res = await fetch(`/api/watchlist/settings/${ticker}`);
        const data = await res.json();
        const currentNotes = data.strategy_notes || '';

        const entries = UI.parseNotebookNotes(currentNotes);
        const newEntry = {
            type: 'NOTE',
            date: new Date().toISOString(),
            description
        };
        entries.unshift(newEntry);

        const jsonStr = JSON.stringify(entries);
        const saveRes = await fetch('/api/watchlist/settings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                ticker: ticker,
                settings: { strategy_notes: jsonStr }
            })
        });

        if (saveRes.ok) {
            UI.showToast('Idea saved to notebook.', 'success');
            const modal = document.getElementById('strategy-notes-modal');
            if (modal && !modal.classList.contains('hidden')) {
                const currentTicker = document.getElementById('strategy-ticker-id').value;
                if (currentTicker === ticker) {
                    window._currentNotebookNotes = jsonStr;
                    UI.renderNotebookCards(ticker, jsonStr);
                }
            }
            if (window.App && window.App.fetchData) window.App.fetchData();
        } else {
            throw new Error('Save failed');
        }
    } catch (e) {
        console.error(e);
        UI.showToast('Failed to save AI idea.', 'error');
    }
};

Actions.saveIdeasToNotes = async function (ticker, encodedData) {
    if (!ticker || !encodedData) return;

    let payload;
    try {
        let decoded = encodedData;
        try {
            decoded = decodeURIComponent(encodedData);
        } catch (e) {
            // Leave as-is if decoding fails
        }
        payload = JSON.parse(decoded);
    } catch (e) {
        let decoded = encodedData;
        try {
            decoded = decodeURIComponent(encodedData);
        } catch (err) {
            // ignore
        }
        payload = { title: 'Analysis', ideas: decoded };
    }

    const { title, drivers, risks, ideas } = payload;
    let description = `NEWS: ${title}\n\n`;
    if (drivers) description += `PRICE DRIVERS:\n${drivers}\n\n`;
    if (risks) description += `RISKS:\n${risks}\n\n`;
    if (ideas) description += `TRADING IDEAS:\n${ideas}\n`;

    UI.showToast('Saving to strategy notebook...', 'info');

    try {
        // 1. Fetch current notes
        const res = await fetch(`/api/watchlist/settings/${ticker}`);
        const data = await res.json();
        const currentNotes = data.strategy_notes || '';

        // 2. Parse and Add New Entry
        const entries = UI.parseNotebookNotes(currentNotes);
        const newEntry = {
            type: 'NOTE',
            date: new Date().toISOString(),
            description: description.trim()
        };
        entries.unshift(newEntry);

        // 3. Save back
        const jsonStr = JSON.stringify(entries);
        const saveRes = await fetch('/api/watchlist/settings', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                ticker: ticker,
                settings: { strategy_notes: jsonStr }
            })
        });

        if (saveRes.ok) {
            UI.showToast('Saved to Strategy Notebook!', 'success');
            if (window.App && window.App.fetchData) window.App.fetchData();
        } else {
            throw new Error('Save failed');
        }

    } catch (e) {
        console.error(e);
        UI.showToast('Failed to save notes', 'error');
    }
};

// Start App
document.addEventListener('DOMContentLoaded', async () => {
    await (window.MSAuthReady || Promise.resolve());
    // Defer heavy startup so DOMContentLoaded can complete promptly in real browsers and E2E.
    window.setTimeout(() => {
        initApp().catch((e) => {
            console.error('Deferred init error:', e);
        });
    }, 0);
    // Allow direct hash navigation after initial load
    window.addEventListener('hashchange', () => ViewRouter.restoreFromHash());
    // Initialize sound icon state
    UI.updateSoundIcon(AudioSystem.isActivityMuted);
    // Initialize Sort Dropdown
    const sortSelect = document.getElementById('scanner-sort-select');
    if (sortSelect) sortSelect.value = UI.scannerSortMode;
});
// Removed global call to startAutoRefresh(), now called by initApp()

/**
 * Handle "View All" click from Calendar Grid
 * Opens the main calendar modal populated with just that day's events.
 */
Actions.openDayModal = function (dateStr) {
    if (!Actions.currentEventsByDate || !Actions.currentEventsByDate[dateStr]) return;

    const events = Actions.currentEventsByDate[dateStr];

    // Construct simplified data object for renderCalendar. Watchlist tickers
    // and coverage come from the payload the grid is showing right now (it
    // used to take "the first cached range", which could be another period).
    const currentData = Actions._calendarCurrentData || {};
    const watchlistTickers = currentData.watchlist_tickers || [];

    const miniData = {
        economic: events.filter(e => e.type === 'economic'),
        earnings: events.filter(e => e.type === 'earnings'),
        ipo: events.filter(e => e.type === 'ipo'),
        watchlist_tickers: watchlistTickers,
        coverage: currentData.coverage || null,
        single_day: dateStr
    };

    // Set as current global data so filter tabs works inside modal
    window._calendarData = miniData;

    // Render "All" tab by default
    Actions.renderCalendar(miniData, 'all');

    // Show Modal
    const modal = document.getElementById('calendar-modal');
    if (modal) {
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
        // Update title to specific date
        const title = modal.querySelector('h3');
        if (title) {
            // Local calendar day in the UI language (new Date('YYYY-MM-DD') is
            // UTC midnight and the title was printed in Romanian).
            const dateObj = Actions.calendarUtil.parseDay(dateStr);
            const total = events.length;
            title.textContent = (dateObj
                ? dateObj.toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })
                : dateStr) + ` — ${total} event${total === 1 ? '' : 's'}`;
        }
    }
};

UI.renderHotList = function (state) {
    const grid = document.getElementById('hotlist-grid');
    if (!grid) return;
    try {

        if (!state || !Object.prototype.hasOwnProperty.call(state, 'hot_list')) {
            grid.innerHTML = `
            <div class="placeholder-text hl-state">
                <p class="hl-state-title">Loading the hot list…</p>
            </div>
        `;
            return;
        }

        const hotItems = state.hot_list || [];
        const detailsBtn = document.getElementById('hotlist-load-details-btn');
        if (detailsBtn && !detailsBtn.dataset.busy) {
            // "Details" are the daily-bar metrics (ADX, momentum, expected move,
            // earnings history). The old check waited for _details_loaded, a flag
            // only the retired FMP builder ever set, so the button never changed.
            const detailsLoaded = hotItems.length > 0 && hotItems.every(i => i && (i._details_loaded || (i._data_quality && i._data_quality.has_bar_metrics)));
            detailsBtn.disabled = false;
            detailsBtn.innerHTML = detailsLoaded
                ? 'Details loaded · refresh'
                : 'Load details';
            detailsBtn.title = detailsLoaded
                ? 'Daily-bar metrics are loaded for every ticker. Click to refresh them.'
                : 'Some tickers have no daily-bar metrics yet (ADX, momentum, expected move, earnings history). Click to fetch them.';
        }

        if (hotItems.length === 0) {
            grid.innerHTML = `
            <div class="placeholder-text hl-state">
                <p class="hl-state-title">Your hot list is empty</p>
                <p class="hl-state-note">Add tickers from the Watchlist table. Meanwhile, any ticker in Market heat above opens its full dossier.</p>
                <button type="button" class="ds-btn ds-btn--sm" onclick="ViewRouter.navigate('watchlist')">Open Watchlist</button>
            </div>
        `;
            // The header summary describes the cards; with no cards it must not
            // keep the counts of the list that was just emptied.
            const emptyFreshness = document.getElementById('hotlist-freshness-badge');
            if (emptyFreshness) emptyFreshness.innerHTML = '';
            UI.loadHotlistHeat();
            return;
        }
        UI.loadHotlistHeat();

        // Same current-quote source as the Watchlist: while this tab is open
        // nothing refreshed the live quotes of the hot tickers (the Watchlist
        // only polls them on its own views), so the cards kept whatever the
        // server snapshot had. Poll /api/live-prices for the hot tickers too
        // (throttled) and repaint when fresher quotes arrive.
        (function refreshHotQuotes() {
            if (typeof API === 'undefined' || typeof API.getLivePrices !== 'function' || typeof UI.mergeLivePricesIntoState !== 'function') return;
            const nowMs = Date.now();
            if (UI._hotListQuotesInFlight || (nowMs - Number(UI._hotListQuotesLastFetch || 0)) < 45000) return;
            const symbols = hotItems.map(i => i && i.ticker).filter(Boolean).slice(0, 40);
            if (!symbols.length) return;
            UI._hotListQuotesLastFetch = nowMs;
            UI._hotListQuotesInFlight = API.getLivePrices(symbols, { remote: true, cacheFallback: true, maxAgeSeconds: 45 })
                .then((data) => {
                    UI.mergeLivePricesIntoState((data && data.prices) || {}, cachedState);
                    if (typeof ViewRouter !== 'undefined' && ViewRouter.activeView === 'hotlist' && cachedState && Array.isArray(cachedState.hot_list)) {
                        UI.scheduleRender('hotlist:live-quotes', () => UI.renderHotList(cachedState), 60);
                    }
                })
                .catch((e) => { if (typeof API._warnNetworkOnce === 'function') API._warnNetworkOnce('Hot list live price refresh skipped', e); })
                .finally(() => { UI._hotListQuotesInFlight = null; });
        })();

        // Ranking comes from backend priority_score; keep received order.
        const serverOrderedItems = Array.isArray(hotItems) ? hotItems : [];

        const fmtPct = (v) => {
            if (v === null || v === undefined || Number.isNaN(Number(v))) return 'unknown';
            const n = Number(v);
            const sign = n > 0 ? '+' : '';
            return `${sign}${n.toFixed(1)}%`;
        };
        const fmtPctOrNA = (v, digits = 2) => {
            if (v === null || v === undefined || Number.isNaN(Number(v))) return 'N/A';
            return `${Number(v).toFixed(digits)}%`;
        };
        const fmtScore = (v) => {
            if (v === null || v === undefined || Number.isNaN(Number(v))) return '0.0';
            return Number(v).toFixed(1);
        };

        const compactRisk = (txt) => {
            if (!txt) return 'unknown';
            const clean = String(txt).replace(/_/g, ' ').trim();
            return clean.length > 56 ? `${clean.slice(0, 53)}...` : clean;
        };
        // Missing-input flags are data gaps, not market risks (tab audit
        // 2026-11-15: three "unknown" flags produced a 95% Risk Heat).
        const HOT_DATA_GAP_FLAGS = ['momentum_unknown', 'adx_unknown', 'earnings_history_unknown', 'earnings_date_unknown', 'news_context_unknown', 'technicals_stale', 'price_stale', 'price_missing'];
        const hotEsc = (v) => (typeof UI._escapeHtml === 'function'
            ? UI._escapeHtml(String(v == null ? '' : v))
            : String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;'));
        const hotAgeText = (seconds) => {
            if (seconds === null || seconds === undefined || seconds === '') return '';
            const s = Number(seconds);
            if (!Number.isFinite(s) || s < 0) return '';
            if (s < 90) return 'just now';
            if (s < 3600) return `${Math.round(s / 60)}m ago`;
            if (s < 48 * 3600) return `${Math.round(s / 3600)}h ago`;
            return `${Math.round(s / 86400)}d ago`;
        };
        const hotAgeSeconds = (iso) => {
            if (!iso) return null;
            const t = Date.parse(iso);
            return Number.isFinite(t) ? Math.max(0, (Date.now() - t) / 1000) : null;
        };
        // One quote per ticker across tabs: the Watchlist overlays the live
        // quotes it polls; the Hot List did not, so the same ticker showed two
        // prices. Use the newer of the server quote and the browser's live quote
        // and always carry the age, so an old price is never shown as current.
        const hotQuote = (item) => {
            const serverAge = hotAgeSeconds(item.price_as_of);
            const hasFreshnessInfo = Object.prototype.hasOwnProperty.call(item, 'price_stale');
            let q = {
                price: Number(item.price),
                changePct: (item.change_pct === null || item.change_pct === undefined || item.change_pct === '') ? NaN : Number(item.change_pct),
                ageSeconds: serverAge,
                stale: hasFreshnessInfo ? Boolean(item.price_stale) : false,
                known: hasFreshnessInfo,
                source: item.price_source || ''
            };
            const live = (UI._livePricesCache || {})[String(item.ticker || '').toUpperCase().trim()];
            const livePrice = Number(live && live.price);
            if (live && Number.isFinite(livePrice) && livePrice > 0) {
                const liveAge = hotAgeSeconds(live.timestamp);
                if (liveAge !== null && (serverAge === null || liveAge < serverAge)) {
                    q = {
                        price: livePrice,
                        changePct: (live.change_pct === null || live.change_pct === undefined) ? NaN : Number(live.change_pct),
                        ageSeconds: liveAge,
                        stale: liveAge > 1200 ? Boolean(item.price_stale) : false,
                        known: true,
                        source: live.source || ''
                    };
                }
            }
            return q;
        };

        const renderCard = (item) => {
            try {
                if (item.ticker === 'ETOR') {
                    if (IS_DEV) console.log('DEBUG ETOR CARD:', JSON.stringify(item.adx), item.momentum_1w, item);
                }
                const techStale = Boolean(item.technicals_stale);
                const techAgeText = techStale ? hotAgeText(hotAgeSeconds(item.technicals_as_of)) : '';
                const getTrendClass = (trend) => techStale ? 'text-muted' : ((trend || '').includes('BULL') ? 'text-green' : ((trend || '').includes('BEAR') ? 'text-red' : 'text-muted'));
                const quote = hotQuote(item);
                // No data / delisted: say so instead of a price and a change.
                const hotPriceState = typeof UI._tickerPriceState === 'function' ? UI._tickerPriceState(item.ticker, item) : null;
                const priceShown = !hotPriceState && Number.isFinite(quote.price) && quote.price > 0;
                const quoteAgeText = hotAgeText(quote.ageSeconds);
                const quoteChipText = !priceShown ? '' : (quote.stale
                    ? `STALE${quoteAgeText ? ' · ' + quoteAgeText : ' · age unknown'}`
                    : (quoteAgeText && quote.ageSeconds >= 90 ? quoteAgeText : ''));
                const quoteChipHtml = quoteChipText
                    ? `<span class="hot-card-quote-age ${quote.stale ? 'ds-chip ds-chip--warn' : 'hl-age'}" title="${quote.stale ? 'This quote is out of date: the market has traded since it was taken. Scores that depend on price are marked as partial.' : 'Time since this quote was taken.'}${quote.source ? ' Source: ' + hotEsc(quote.source) + '.' : ''}">${quoteChipText}</span>`
                    : '';
                const chgNum = quote.changePct;
                const chgValid = Number.isFinite(chgNum);
                const chgColor = !chgValid ? 'text-muted' : (chgNum >= 0 ? 'text-green' : 'text-red');
                const sign = chgValid && chgNum >= 0 ? '+' : '';
                const bs = item.best_strategy || {};
                const bsLabel = (bs.trade_mode && bs.risk_mode) ? `Best: ${bs.trade_mode}/${bs.risk_mode}` : '';
                const bsBadge = bsLabel ? `<span class="hot-badge ds-chip" title="Best back-tested trade mode / risk mode for this ticker.">${hotEsc(bsLabel)}</span>` : '';
                const whenText = item.earnings_when ? ` ${item.earnings_when}` : '';
                const edgeScore = Number(item.earnings_edge_score || 0);
                const overallScore = Number(item.overall_score ?? edgeScore ?? 0);
                const priorityScore = Number(item.priority_score || 0);
                const setup = (item.earnings_setup || 'C').toUpperCase();
                const play = (item.earnings_play || 'WAIT').toUpperCase();
                const risk = (item.risk_level || 'med').toLowerCase();
                const confidenceScore = Math.max(0, Math.min(100, Number(item.confidence_score ?? overallScore ?? 0)));
                const riskFlags = Array.isArray(item.earnings_risk_flags) ? item.earnings_risk_flags : [];
                // 2026-09-03 owner audit: this was a FIXED gauge (90/62/28 by
                // risk level) that looked like a computed percentage. Now it
                // derives from the ticker's own risk flags + risk level, so two
                // tickers with different flags show different heats.
                // (Declaration moved ABOVE its first use — the previous order
                // threw a TDZ ReferenceError and blanked the whole grid.)
                // Tab audit 2026-11-15: only real risk factors heat the gauge.
                // Missing-input flags ("momentum_unknown", ...) are data gaps;
                // counting them printed "Risk Heat 95%" on cards with no data.
                const realRiskFlags = Array.isArray(item.risk_factor_flags)
                    ? item.risk_factor_flags
                    : riskFlags.filter(f => !HOT_DATA_GAP_FLAGS.includes(String(f)));
                const dataGapFlags = riskFlags.filter(f => HOT_DATA_GAP_FLAGS.includes(String(f)));
                const missingInputs = Array.isArray(item.missing_inputs) ? item.missing_inputs : null;
                const coveragePct = Number.isFinite(Number(item.data_coverage_pct)) && item.data_coverage_pct !== null && item.data_coverage_pct !== undefined ? Number(item.data_coverage_pct) : null;
                const verdictStatus = String(item.verdict_status || (play === 'INSUFFICIENT_DATA' ? 'insufficient_data' : 'ok'));
                const insufficientData = verdictStatus === 'insufficient_data' || play === 'INSUFFICIENT_DATA';
                const noUpcomingEarnings = verdictStatus === 'no_upcoming_earnings';
                const missingText = (missingInputs && missingInputs.length) ? missingInputs.map(m => String(m).replace(/_/g, ' ')).join(', ') : '';
                const riskFlagCount = realRiskFlags.length;
                const riskLevelPts = risk === 'high' ? 30 : (risk === 'low' ? 0 : 12);
                const riskHeatPct = Math.max(20, Math.min(95, 20 + 14 * riskFlagCount + riskLevelPts));
                const topRisk = compactRisk(item.top_risk || realRiskFlags[0] || 'unknown');
                const expectedMove = (item.expected_move_vs_avg && typeof item.expected_move_vs_avg === 'object') ? item.expected_move_vs_avg : {};
                const metricNumber = (value) => value === null || value === undefined || value === '' || !Number.isFinite(Number(value)) ? null : Number(value);
                const expectedMovePct = metricNumber(expectedMove.expected_move_pct);
                const avgMove8q = metricNumber(expectedMove.avg_move_8q);
                const expectedEdgePct = metricNumber(expectedMove.edge_pct);
                const historySummary = (item.earnings_history_summary && item.earnings_history_summary.last_8) ? item.earnings_history_summary.last_8 : null;
                const historySampled = Boolean(historySummary) && Number((item.earnings_history_summary || {}).sample_size ?? (historySummary.up_count + historySummary.down_count)) > 0;
                const historyUp = historySampled ? Number(historySummary.up_count || 0) : null;
                const historyDown = historySampled ? Number(historySummary.down_count || 0) : null;
                const historyAvgGap = historySampled ? metricNumber(historySummary.avg_gap_pct) : null;
                const safeTitle = (txt) => String(txt || '').replace(/"/g, '&quot;').replace(/\n/g, '&#10;');

                // Data-quality badge: surface partial-data so the trader knows the
                // card rests on incomplete feeds (fast path, no fundamentals, missing
                // trends/price). Pre-fix _data_quality was computed backend-side but
                // never shown, so a fast-path card looked identical to a fully-loaded
                // one (directive: nothing missing, every value honest).
                const dq = item._data_quality || {};
                const dqMissing = [];
                if (dq.has_price === false) dqMissing.push('price');
                if (dq.has_trends === false) dqMissing.push('trends');
                // Fundamentals have no provider since FMP was retired: flagging every
                // card "Partial Data" for a dataset that cannot load told the trader
                // nothing. The badge now lists the scoring inputs that are really
                // missing for THIS ticker (older payloads keep the previous rule).
                const fundamentalsExpected = dq.fundamentals_provider !== false;
                if (dq.has_fundamental_details === false && fundamentalsExpected) dqMissing.push('fundamentals');
                if (missingInputs) missingInputs.forEach(m => { const label = String(m).replace(/_/g, ' '); if (!dqMissing.includes(label) && !(label === 'trend' && dqMissing.includes('trends'))) dqMissing.push(label); });
                if (quote.stale && priceShown) dqMissing.push('current price (quote is stale)');
                if (techStale) dqMissing.push(`current trend (snapshot ${techAgeText || 'age unknown'})`);
                const dqPartial = dqMissing.length > 0 || (!missingInputs && dq.source === 'fast');
                const dqBadgeHtml = dqPartial
                    ? `<span class="hl-badge-data ds-chip ds-chip--warn" title="${safeTitle(`Partial data: ${dqMissing.join(', ') || 'fast path only'}.${coveragePct !== null ? ` ${coveragePct}% of the scoring inputs are present.` : ''} Scores may rest on incomplete feeds — verify before executing.`)}">Partial data</span>`
                    : '';

                const trend1d = String(item.trend_1d || 'N/A').split(' ')[0].toUpperCase();
                const trend4h = String(item.trend_4h || 'N/A').split(' ')[0].toUpperCase();
                const trendAlignedBull = trend1d.includes('BULL') && trend4h.includes('BULL');
                const trendAlignedBear = trend1d.includes('BEAR') && trend4h.includes('BEAR');
                const trendDecision = trendAlignedBull
                    ? 'Decision: favorable context for long setups, confirmed by risk/news.'
                    : (trendAlignedBear
                        ? 'Decision: weak context for long; prefer caution or confirm with smaller timeframe.'
                        : 'Decision: mixed trend, wait for clearer alignment before execution.');
                const trendTooltip = `What it is:\n1D/4H Trend shows the primary and intermediate direction.\n\nCurrent details:\n1D=${trend1d}, 4H=${trend4h}.\n\n${trendDecision}`;
                // Robust ADX Extraction
                let adxValue = 0;
                if (item.adx) {
                    if (typeof item.adx === 'object' && item.adx.adx !== undefined) {
                        adxValue = Number(item.adx.adx);
                    } else if (typeof item.adx === 'number') {
                        adxValue = item.adx;
                    } else if (!Number.isNaN(Number(item.adx))) {
                        adxValue = Number(item.adx);
                    }
                }
                const adxStr = adxValue > 0 ? adxValue.toFixed(1) : 'N/A';
                const adxColor = adxValue > 25 ? 'text-green' : 'text-muted';

                // No insider-data provider is connected (FMP retired): say "n/a", not
                // "unknown" — "unknown" read like a value that was still loading.
                const insiderRaw = item.insider_sentiment || (item.insider && item.insider.sentiment) || '';
                const insiderNoProvider = !insiderRaw && dq.fundamentals_provider === false;
                const insVal = (insiderRaw || (insiderNoProvider ? 'n/a' : 'unknown')).toLowerCase();
                const insColor = insVal.includes('bull') ? 'text-green' : (insVal.includes('bear') ? 'text-red' : 'text-muted');

                const newsVal = (item.news_sentiment_trend || (item.news_signals && item.news_signals.sentiment_trend) || (item.news_pulse && item.news_pulse.sentiment) || 'unknown').toLowerCase();
                const newsColor = newsVal.includes('bull') ? 'text-green' : (newsVal.includes('bear') ? 'text-red' : 'text-muted');

                // Robust Momentum
                let mom1wVal = (item.momentum_1w === null || item.momentum_1w === undefined || item.momentum_1w === '') ? NaN : Number(item.momentum_1w);
                if (Number.isNaN(mom1wVal) && item.momentum_1w) {
                    // Try parsing string "12.5%"
                    mom1wVal = parseFloat(String(item.momentum_1w).replace('%', ''));
                }

                let mom1mVal = (item.momentum_1m === null || item.momentum_1m === undefined || item.momentum_1m === '') ? NaN : Number(item.momentum_1m);
                if (Number.isNaN(mom1mVal) && item.momentum_1m) {
                    mom1mVal = parseFloat(String(item.momentum_1m).replace('%', ''));
                }

                const mom1wStr = !Number.isNaN(mom1wVal) ? fmtPct(mom1wVal) : 'N/A';
                const mom1mStr = !Number.isNaN(mom1mVal) ? fmtPct(mom1mVal) : 'N/A';
                const mom1wColor = mom1wVal > 0 ? 'text-green' : (mom1wVal < 0 ? 'text-red' : 'text-muted');
                const mom1mColor = mom1mVal > 0 ? 'text-green' : (mom1mVal < 0 ? 'text-red' : 'text-muted');

                const adxTier = adxValue >= 35 ? 'very strong' : (adxValue >= 25 ? 'strong' : (adxValue >= 18 ? 'moderate' : 'weak'));
                const adxDecision = adxValue >= 25
                    ? 'Decision: trend has force; prioritize setups in the trend direction.'
                    : 'Decision: trend is weak; avoid aggressive entries without extra confirmation.';
                const momentumBias = (mom1wVal > 0 && mom1mVal > 0)
                    ? 'positive on both horizons'
                    : (mom1wVal < 0 && mom1mVal < 0)
                        ? 'negative on both horizons'
                        : 'mixed (1W and 1M not aligned)';
                const momentumDecision = momentumBias.includes('positive')
                    ? 'Decision: momentum supports the positive trend.'
                    : (momentumBias.includes('negative')
                        ? 'Decision: momentum weakens the case for long continuation.'
                        : 'Decision: mixed momentum; timing is more important.');
                const adxMomTooltip = `What is ADX:\nMeasures trend strength (not direction).\n\nCurrent ADX details:\n${adxStr} (${adxTier}).\n${adxDecision}\n\nWhat is 1W/1M Momentum:\nSpeed of movement over 1 week and 1 month.\nCurrent details: 1W=${mom1wStr}, 1M=${mom1mStr} (${momentumBias}).\n${momentumDecision}`;

                const insDecision = insVal.includes('bull')
                    ? 'Decision: insider activity supports the bullish scenario.'
                    : (insVal.includes('bear')
                        ? 'Decision: insider activity adds caution to the setup.'
                        : 'Decision: neutral/insufficient insider signal.');
                const newsDecision = newsVal.includes('bull')
                    ? 'Decision: news sentiment supports positive moves.'
                    : (newsVal.includes('bear')
                        ? 'Decision: news sentiment may increase downside risk.'
                        : 'Decision: mixed/neutral news, not a dominant factor.');
                const insiderNewsTooltip = `What is Insider:\nSentiment derived from insider activity.\nCurrent value: ${insVal}.\n${insiderNoProvider ? 'Not configured: insider-data provider. Insider sentiment is not part of the score until one is set up.' : insDecision}\n\nWhat is News Sentiment:\nOverall tone of recent news.\nCurrent value: ${newsVal}.\n${newsDecision}`;

                // With no usable inputs and no identified risk factor, "MED" is only
                // the default — show N/A rather than a risk tier nothing supports.
                const badgeRisk = (insufficientData && realRiskFlags.length === 0) ? 'N/A' : (risk === 'high' ? 'HIGH' : (risk === 'low' ? 'LOW' : 'MED'));
                const edgeTier = edgeScore >= 75 ? 'HIGH' : (edgeScore >= 55 ? 'MEDIUM' : 'LOW');
                const edgeDecision = edgeScore >= 75
                    ? 'Decision: higher-priority ticker in the shortlist.'
                    : (edgeScore >= 55
                        ? 'Decision: usable setup, but requires risk/news verification.'
                        : 'Decision: weak setup; prefer monitoring over immediate execution.');
                const setupExplain = setup === 'A'
                    ? 'Setup A: high confluence (trend/news/risk aligned).'
                    : (setup === 'B'
                        ? 'Setup B: medium confluence, requires additional confirmation.'
                        : 'Setup C: low confluence, monitor/wait.');
                const edgeTooltip = `What is EDGE ${setup}:\nInternal quality score for the earnings setup (0-100; grades: A = 75+, B = 60-74, C = below 60; defaults apply to tickers outside the scoring universe).\n\nCurrent value: ${edgeScore} (${edgeTier}).\n${setupExplain}\n${edgeDecision}`;

                const playDecision = play === 'WAIT'
                    ? 'Decision: wait for confirmation before entry.'
                    : (play === 'PLAY_PRE'
                        ? 'Decision: pre-earnings plan active, execute only with strict risk management.'
                        : (play === 'PLAY_POST'
                            ? 'Decision: post-earnings plan active after direction confirmation.'
                            : (insufficientData
                                ? `No verdict: the inputs needed to score this ticker are missing${missingText ? ` (${missingText})` : ''}. Load the details or wait for the data before acting.`
                                : (noUpcomingEarnings
                                    ? 'Decision: not applicable — the last earnings report is behind us (or no date is known) and the next date has not been announced, so there is no earnings setup to play.'
                                    : (play === 'N/A'
                                        ? 'Decision: not applicable — crypto assets have no earnings cycle.'
                                        : (play === 'AVOID'
                                            ? 'Decision: avoid an earnings position — the setup score is low or the risk is high.'
                                            : 'Decision: follow the strategy plan for this play.'))))));
                const playLabel = insufficientData ? 'INSUFFICIENT DATA' : (noUpcomingEarnings ? 'NO EARNINGS PLAY' : play);
                const playTooltip = `What is PLAY:\nCurrent tactical recommendation for this setup.\n\nCurrent value: ${playLabel}.\n${playDecision}`;

                const riskBadgeDecision = risk === 'high'
                    ? 'Decision: reduce exposure and require multiple confirmations.'
                    : (risk === 'low'
                        ? 'Decision: relatively low risk, but still verify news and earnings.'
                        : 'Decision: medium risk; avoid entries without an exit plan.');
                const riskBadgeTooltip = `What is RISK:\nEstimated risk level of the setup.\n\nCurrent value: ${badgeRisk}.\n${riskBadgeDecision}`;

                // Earnings chip: neutral by default, warn inside 3 days, muted
                // when the date is unknown or already behind us.
                let countdownHtml = `
            <span class="hot-card-countdown ds-chip hl-chip-muted" title="No earnings date is known for this ticker.">
                <span class="countdown-label">Earnings</span>
                <span class="countdown-timer">TBA</span>
            </span>
        `;

                if (item.earnings_days >= 0) {
                    countdownHtml = `
                <span class="hot-card-countdown ds-chip${item.earnings_days <= 3 ? ' ds-chip--warn' : ''}" title="${safeTitle(`Earnings in ${item.earnings_days} days (${item.earnings_date}${whenText}).\nDecision: the closer to earnings, the higher the volatility.`)}">
                    <span class="countdown-label">Earnings in ${item.earnings_days}d${hotEsc(whenText)}</span>
                    <span class="countdown-timer">${hotEsc(item.earnings_date)}</span>
                </span>
            `;
                } else if (item.earnings_date && item.earnings_date !== 'N/A') {
                    // earnings_days < 0 with a real date => the date is in the PAST
                    // (days_until = (dt - today).days, returned only as the -1 sentinel
                    // when no date is found — and that path carries "N/A", excluded
                    // above). Pre-fix this branch labeled a past report "Earnings
                    // Next", misleading the trader into waiting for an event that
                    // already happened. Label honestly (directive: nothing invented).
                    const _lastDays = Number.isFinite(Number(item.earnings_days)) ? Math.abs(Number(item.earnings_days)) : null;
                    countdownHtml = `
                <span class="hot-card-countdown ds-chip hl-chip-muted" title="${safeTitle(`Last earnings reported ${_lastDays != null ? `${_lastDays}d ago ` : ''}on ${item.earnings_date}${whenText}.\nDecision: this report is history; watch for the next cycle's date.`)}">
                    <span class="countdown-label">Last earnings${_lastDays != null ? ` ${_lastDays}d ago` : ''}${hotEsc(whenText)}</span>
                    <span class="countdown-timer">${hotEsc(item.earnings_date)}</span>
                </span>
            `;
                }


                // Panel layout (UI v10). Display helpers only: quiet up/down marks,
                // a muted "n/a" for missing values, data words in sentence case.
                const hlNa = '<span class="hl-na">n/a</span>';
                const hlQuiet = (cls) => (cls === 'text-green' ? 'hl-up' : (cls === 'text-red' ? 'hl-down' : 'hl-na'));
                const hlTrendMark = (tf, raw) => {
                    const word = String(raw || 'N/A').split(' ')[0];
                    if (!word || word.toUpperCase() === 'N/A') return `<span class="hl-trend hl-na"><span class="hl-trend-tf">${tf}</span> n/a</span>`;
                    const arrow = word.toUpperCase().includes('BULL') ? '▲' : (word.toUpperCase().includes('BEAR') ? '▼' : '–');
                    return `<span class="hl-trend ${hlQuiet(getTrendClass(raw))}"><span class="hl-trend-tf">${tf}</span> ${arrow} ${hotEsc(word.charAt(0).toUpperCase() + word.slice(1).toLowerCase())}</span>`;
                };
                const hlPct = (v) => (v === null ? hlNa : `<span>${fmtPctOrNA(v)}</span>`);
                const hlWord = (v, cls) => ((v === 'n/a' || v === 'unknown') ? `<span class="hl-na">${v}</span>` : `<span class="${hlQuiet(cls)}">${hotEsc(v)}</span>`);
                const verdictTone = (insufficientData || noUpcomingEarnings || play === 'N/A')
                    ? 'hl-chip-muted'
                    : (play === 'AVOID' ? 'ds-chip--neg' : (play.indexOf('PLAY') === 0 ? 'ds-chip--pos' : ''));
                const missingHtml = (insufficientData && missingText)
                    ? `<span class="hl-missing">Missing: ${hotEsc(missingText)}</span>`
                    : '';
                const riskTierWord = badgeRisk === 'N/A' ? 'n/a' : (badgeRisk === 'HIGH' ? 'High' : (badgeRisk === 'LOW' ? 'Low' : 'Medium'));
                const riskTierTone = badgeRisk === 'N/A' ? 'hl-na' : `hl-tier--${risk === 'high' || risk === 'low' ? risk : 'med'}`;
                const scoreTitle = safeTitle(`Overall 0-100: weighted mix — 35% earnings edge, 20% momentum, 20% news, 15% technical alignment, 10% regime. Missing inputs are scored as neutral, so with gaps the number says little${insufficientData ? ` — it is hidden here because core inputs are missing${missingText ? ` (${missingText})` : ''}` : ''}. Priority (0 = lowest) ranks this ticker against the OTHERS in your hot list only (time to earnings + edge - risk penalty); it is a sort order, not an absolute quality grade.`);

                return `
            <article class="hotlist-card" tabindex="0" aria-label="${item.ticker}: open trends and notes" onclick="UI.showHotListDetail('${item.ticker}')" onkeydown="if ((event.key === 'Enter' || event.key === ' ') && event.target === this) { event.preventDefault(); UI.showHotListDetail('${item.ticker}'); }">
                <div class="hot-card-header">
                    <div class="hot-card-symbol-group">
                        <span class="hot-card-symbol">${item.ticker}</span>
                        <span class="hot-card-price-row">
                            ${hotPriceState ? UI._priceStateHtml(hotPriceState, quote.price) : `<span class="hot-card-price"${quote.stale && priceShown ? ' data-stale="true"' : ''}>${priceShown ? '$' + UI.formatPrice(quote.price) : 'n/a'}</span>
                            <span class="hot-card-change ${quote.stale ? 'text-muted' : chgColor}">${chgValid ? `${sign}${chgNum.toFixed(2)}%` : 'n/a'}</span>
                            ${quoteChipHtml}`}
                        </span>
                        ${countdownHtml}
                        ${bsBadge}
                    </div>
                    <div class="hot-card-verdict">
                        ${missingHtml}
                        ${missingHtml ? '' : dqBadgeHtml}
                        <span class="hl-badge-play ds-chip hl-verdict ${verdictTone}" title="${safeTitle(playTooltip)}">${hotEsc(String(playLabel).replace(/_/g, ' '))}</span>
                        <span class="hot-card-actions">
                            <button type="button" class="ds-btn ds-btn--sm btn-hot-analysis" onclick="event.stopPropagation(); Actions.analyzeTicker('${item.ticker}')">Analyze</button>
                            <button type="button" class="ds-btn ds-btn--sm ds-btn--ghost" onclick="event.stopPropagation(); UI.openTickerDossier('${item.ticker}')" title="Open full dossier (news, trades, AI history, deep analysis)">Dossier</button>
                            <button type="button" class="ds-btn ds-btn--sm ds-btn--ghost hl-icon-btn" onclick="event.stopPropagation(); Actions.toggleHotList('${item.ticker}')" title="Remove from Hot List" aria-label="Remove ${item.ticker} from the hot list"><i class="fa-solid fa-xmark"></i></button>
                        </span>
                    </div>
                </div>

                <div class="hot-card-body">
                    <section class="hot-card-col">
                        <h4 class="ds-label">Scores</h4>
                        <dl class="hl-dl">
                            <div class="hl-row" title="${scoreTitle}">
                                <dt>Overall</dt>
                                <dd><span class="${insufficientData ? 'hl-na ' : ''}hot-score-main">${insufficientData ? '—' : fmtScore(overallScore)}</span>${insufficientData ? '' : '<span class="hl-unit">/100</span>'}</dd>
                            </div>
                            <div class="hl-row" title="${scoreTitle}">
                                <dt>Priority</dt>
                                <dd data-k="priority">${fmtScore(Math.max(0, priorityScore))}</dd>
                            </div>
                            <div class="hl-row hot-card-confidence" title="${safeTitle(`Confidence ${Math.round(confidenceScore)}/100 = Overall score x share of scoring inputs that are present${coveragePct !== null ? ` (${coveragePct}% present)` : ''}.${missingText ? `\nMissing: ${missingText}.` : ''}\nIt measures how much data backs the score, not a probability of profit.`)}">
                                <dt>Confidence</dt>
                                <dd>
                                    <span class="hot-card-confidence-track" aria-hidden="true"><span class="hot-card-confidence-fill" style="width:${confidenceScore}%;"></span></span>
                                    <span>${Math.round(confidenceScore)}</span><span class="hl-unit">/100</span>
                                </dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(edgeTooltip)}">
                                <dt>Edge grade</dt>
                                <dd data-k="edge">${['A', 'B', 'C'].includes(setup) ? `<span class="hl-grade">${setup}</span> ${fmtScore(edgeScore)}` : hlNa}</dd>
                            </div>
                        </dl>
                    </section>

                    <section class="hot-card-col">
                        <h4 class="ds-label">Technicals</h4>
                        <dl class="hl-dl">
                            <div class="hl-row" title="${safeTitle(trendTooltip)}">
                                <dt><span>Trend 1D/4H${techStale ? ` <span class="ds-chip ds-chip--warn">STALE${techAgeText ? ' · ' + techAgeText : ''}</span>` : ''}</span></dt>
                                <dd>${hlTrendMark('1D', item.trend_1d)}${hlTrendMark('4H', item.trend_4h)}</dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(adxMomTooltip)}">
                                <dt>ADX</dt>
                                <dd>${adxValue > 0 ? `<span class="hl-note">${adxTier}</span> <span>${adxStr}</span>` : hlNa}</dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(adxMomTooltip)}">
                                <dt>Momentum 1W / 1M</dt>
                                <dd>${Number.isNaN(mom1wVal) ? hlNa : `<span class="${hlQuiet(mom1wColor)}">${mom1wStr}</span>`}<span class="hl-sep">/</span>${Number.isNaN(mom1mVal) ? hlNa : `<span class="${hlQuiet(mom1mColor)}">${mom1mStr}</span>`}</dd>
                            </div>
                        </dl>
                    </section>

                    <section class="hot-card-col">
                        <h4 class="ds-label">Event</h4>
                        <dl class="hl-dl">
                            <div class="hl-row" title="${safeTitle(`Expected Move vs Historical Move:\nExpected ${fmtPctOrNA(expectedMovePct)} | Avg 8Q ${fmtPctOrNA(avgMove8q)} | Edge ${fmtPctOrNA(expectedEdgePct)}`)}">
                                <dt><span>Expected vs 8Q move</span></dt>
                                <dd>${hlPct(expectedMovePct)}<span class="hl-sep">vs</span>${hlPct(avgMove8q)}</dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(historySampled ? `Earnings History (8Q): up=${historyUp}, down=${historyDown}, avg gap=${fmtPctOrNA(historyAvgGap)}` : 'Earnings History (8Q): sampled history unavailable.')}">
                                <dt>Earnings history (8Q)</dt>
                                <dd>${historySampled ? `<span>U${historyUp}/D${historyDown}${(historyUp + historyDown) < 8 ? ` (n=${historyUp + historyDown})` : ''}</span>${historyAvgGap === null ? '' : `<span class="hl-note">avg gap</span><span>${fmtPctOrNA(historyAvgGap)}</span>`}` : hlNa}</dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(insiderNewsTooltip)}">
                                <dt>Insider activity</dt>
                                <dd>${hlWord(insVal, insColor)}</dd>
                            </div>
                            <div class="hl-row" title="${safeTitle(insiderNewsTooltip)}">
                                <dt>News tone</dt>
                                <dd>${hlWord(newsVal, newsColor)}</dd>
                            </div>
                        </dl>
                    </section>
                </div>

                <div class="hot-card-foot">
                <div class="hot-card-riskheat" title="${safeTitle(insufficientData
                    ? `Risk Heat is not shown: the inputs needed to assess this ticker are missing${missingText ? ` (${missingText})` : ''}. Known risk factors so far: ${realRiskFlags.join(', ') || 'none'}.`
                    : `Risk Heat: composed from ${riskFlagCount} open risk factor(s) (${realRiskFlags.join(', ') || 'none'}) plus the ${risk.toUpperCase()} risk level.${dataGapFlags.length ? ` Data gaps (${dataGapFlags.join(', ')}) are not counted as risk.` : ''} It is a visual composite, not a probability — use Top Risk + Flags for the specifics.`)}">
                    <span class="risk-heat-label">Risk heat</span>
                    <span class="risk-heat-track" aria-hidden="true"><span class="risk-heat-fill risk-heat-${risk}" style="width:${insufficientData ? 0 : riskHeatPct}%;"></span></span>
                    <span class="risk-heat-value">${insufficientData ? 'n/a' : riskHeatPct + '%'}</span>
                </div>
                <div class="hot-card-risktier" title="${safeTitle(riskBadgeTooltip)}">
                    <span class="risk-label">Risk tier</span>
                    <span class="hl-tier ${riskTierTone}">${riskTierWord}</span>
                </div>
                <div class="hot-card-riskline" title="${safeTitle(`Top Risk: ${hotEsc(topRisk)}\nRisk factors: ${realRiskFlags.join(', ') || 'none'}.${dataGapFlags.length ? `\nData gaps: ${dataGapFlags.join(', ')}.` : ''}\nDecision: if top risk is severe, treat the signal as conditional (smaller position / wait).`)}">
                    <span class="risk-label">Top risk</span>
                    <span class="risk-value">${hotEsc(topRisk)}</span>
                </div>
                </div>
            </article>
        `;
            } catch (e) {
                console.warn('renderCard failed', e);
                return '';
            }
        };
        grid.innerHTML = serverOrderedItems.map(renderCard).join('');

        // Header freshness summary (the #hotlist-freshness-badge placeholder was
        // never filled): how many quotes are current and how many cards lack
        // the inputs for a verdict.
        const freshnessBadge = document.getElementById('hotlist-freshness-badge');
        if (freshnessBadge) {
            const total = serverOrderedItems.length;
            const staleQuotes = serverOrderedItems.filter(i => { const q = hotQuote(i); return q.stale || !(Number.isFinite(q.price) && q.price > 0); }).length;
            const noVerdict = serverOrderedItems.filter(i => String(i.verdict_status || '') === 'insufficient_data' || String(i.earnings_play || '').toUpperCase() === 'INSUFFICIENT_DATA').length;
            // Quiet meta line; only the parts that need attention become a warn chip.
            const parts = [`<span>${total} ticker${total === 1 ? '' : 's'}</span>`];
            parts.push(staleQuotes ? `<span class="ds-chip ds-chip--warn">${staleQuotes} stale quote${staleQuotes === 1 ? '' : 's'}</span>` : '<span>quotes current</span>');
            if (noVerdict) parts.push(`<span class="ds-chip ds-chip--warn">${noVerdict} without enough data</span>`);
            freshnessBadge.innerHTML = `<span class="hl-fresh" title="Quotes come from the same live-quote store as the Watchlist. A stale quote means the market has traded since it was taken.">${parts.join('<span class="hl-sep">·</span>')}</span>`;
        }

        // Persistence: If a ticker was expanded, updated it if data changed
        if (window.expandedHotListTicker) {
            UI.showHotListDetail(window.expandedHotListTicker, true); // true = updateOnly
        }
    } catch (e) {
        console.error('renderHotList failed', e);
        grid.innerHTML = `
            <div class="placeholder-text hl-state">
                <p class="hl-state-title">The hot list could not be drawn</p>
                <p class="hl-state-note">${String((e && e.message) || e).replace(/&/g, '&amp;').replace(/</g, '&lt;')} — it is redrawn on the next data refresh.</p>
            </div>
        `;
    }
};

UI.renderBacktestHistory = function (history) {
    const list = document.getElementById('bt-history-list');
    if (!list) return;

    if (!history || history.length === 0) {
        list.innerHTML = '<div class="bt-empty-note">No saved simulations</div>';
        return;
    }

    const esc = (v) => UI._escapeHtml(String(v == null ? '' : v));
    // The saved run currently shown in the results area is the marked row.
    const shown = (typeof App !== 'undefined' && App._btLastData && App._btLastData._savedRun) ? App._btLastData.timestamp : null;
    const scrollTop = list.scrollTop;
    list.innerHTML = history.map((h, i) => {
        // Date AND time: these rows are from different days (weeks apart) and
        // all showed a bare clock time, as if they were from today.
        const date = esc(App._btFormatWhen(h.timestamp));
        const ticker = esc(h.ticker || 'Multi');
        let mode = 'Standard';
        if (h.mode === 'comparison') mode = 'Strategies';
        if (h.mode === 'orb_fvg') mode = 'ORB FVG';
        if (h.mode === 'faithful') mode = 'Faithful';
        // What the period means: the number asked for, and the span of data
        // the run really covered when the server recorded it.
        const cov = h.data_coverage || {};
        const span = Number(cov.actual_span_days);
        const days = esc(h.days ?? '?');
        const period = (Number.isFinite(span) && cov.truncated)
            ? `${days} days requested · ${span.toFixed(1)} days of data`
            : `${days} days requested`;
        const detail = (h.mode === 'standard' && h.risk_mode)
            ? ` · ${esc(h.risk_mode)} / ${esc(h.trade_mode || '-')}` : '';

        const selected = shown != null && h.timestamp === shown;
        return `
            <button type="button" class="bt-history-item${selected ? ' is-selected' : ''}" onclick="App.viewBacktest(${i})"${selected ? ' aria-current="true"' : ''}>
                <span class="bt-history-line">
                    <span class="bt-history-ticker">${ticker}</span>
                    <span class="bt-history-mode">${mode}</span>
                    <span class="bt-history-when" data-testid="bt-history-when">${date}</span>
                </span>
                <span class="bt-history-period">${period}${detail}</span>
            </button>
        `;
    }).join('');
    if (scrollTop) list.scrollTop = scrollTop;
};

UI.showHotListDetail = function (ticker, updateOnly = false) {
    if (!cachedState || !cachedState.hot_list) return;
    const esc = (v) => String(v == null ? '' : v)
        .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
    const item = cachedState.hot_list.find(i => i.ticker === ticker);
    if (!item) {
        if (!updateOnly) window.expandedHotListTicker = null;
        return;
    }

    window.expandedHotListTicker = ticker;

    let modal = document.getElementById('hotlist-detail-modal');
    if (!modal) {
        if (updateOnly) return;
        modal = document.createElement('div');
        modal.id = 'hotlist-detail-modal';
        modal.className = 'modal-overlay hotlist-detail-modal';
        modal.onclick = (e) => { if (e.target === modal) UI.closeHotListDetail(); };
        document.body.appendChild(modal);
    }

    if (updateOnly && modal.classList.contains('hidden')) return;

    const prevBodyScrollTop = updateOnly ? (modal.querySelector('.hot-detail-body')?.scrollTop ?? 0) : 0;

    // null/absent change is "no data", not +0.00%; a zero/absent price is N/A.
    const chgNumDetail = (item.change_pct === null || item.change_pct === undefined || item.change_pct === '') ? NaN : Number(item.change_pct);
    const chgValidDetail = Number.isFinite(chgNumDetail);
    const chgColor = !chgValidDetail ? 'text-muted' : (chgNumDetail >= 0 ? 'text-green' : 'text-red');
    const sign = chgValidDetail && chgNumDetail >= 0 ? '+' : '';
    const detailPriceState = typeof UI._tickerPriceState === 'function' ? UI._tickerPriceState(item.ticker, item) : null;
    const priceValid = !detailPriceState && Number.isFinite(Number(item.price)) && Number(item.price) > 0;
    const detailQuoteMs = item.price_as_of ? Date.parse(item.price_as_of) : NaN;
    const detailQuoteAgeDays = Number.isFinite(detailQuoteMs) ? Math.round((Date.now() - detailQuoteMs) / 86400000) : null;
    const detailQuoteNote = (priceValid && item.price_stale)
        ? `<span class="ds-chip ds-chip--warn" title="This quote is out of date: the market has traded since it was taken.">STALE${detailQuoteAgeDays !== null ? ` · ${detailQuoteAgeDays >= 1 ? detailQuoteAgeDays + 'd' : '<1d'} old` : ' · age unknown'}</span>`
        : '';
    const detailTrendNote = item.technicals_stale
        ? '<span class="ds-chip ds-chip--warn">Snapshot is stale — not current</span>'
        : '';

    modal.innerHTML = `
        <div class="modal-content" role="dialog" aria-label="${esc(item.ticker)} trends and notes">
            <div class="hot-detail-header">
                <div class="hot-detail-id">
                    <span class="hot-detail-symbol">${esc(item.ticker)}</span>
                    <span class="hot-card-price-row">
                        ${detailPriceState ? UI._priceStateHtml(detailPriceState, item.price) : `<span class="hot-card-price">${priceValid ? '$' + UI.formatPrice(item.price) : 'n/a'}</span>
                        <span class="hot-card-change ${item.price_stale ? 'text-muted' : chgColor}">${chgValidDetail ? `${sign}${chgNumDetail.toFixed(2)}%` : 'n/a'}</span>
                        ${detailQuoteNote}`}
                    </span>
                </div>
                <div class="hot-detail-actions">
                    <button type="button" class="ds-btn ds-btn--sm ds-btn--ghost" title="Remove from Hot List" onclick="Actions.toggleHotList('${item.ticker}'); UI.closeHotListDetail();">Remove from hot list</button>
                    <button type="button" class="btn-modal-close ds-btn ds-btn--ghost" onclick="UI.closeHotListDetail()" title="Close" aria-label="Close"><i class="fa-solid fa-xmark"></i></button>
                </div>
            </div>
            <div class="hot-detail-body">
                <div class="hot-detail-section">
                    <div class="hot-detail-section-title"><span>Multi-timeframe trends</span>${detailTrendNote}</div>
                    <div class="hot-detail-grid">
                        ${['1D', '4H', '1H', '30M', '5M'].map(tf => {
        const tfKey = `trend_${tf.toLowerCase()}`;
        const val = (item[tfKey] || 'N/A').split(' ')[0];
        const isBull = (item[tfKey] || '').includes('BULL');
        const isBear = (item[tfKey] || '').includes('BEAR');
        const colorClass = item.technicals_stale ? 'hl-na' : (isBull ? 'hl-up' : (isBear ? 'hl-down' : 'hl-na'));
        const mark = val.toUpperCase() === 'N/A' ? 'n/a' : `${isBull ? '▲ ' : (isBear ? '▼ ' : '')}${esc(val.charAt(0).toUpperCase() + val.slice(1).toLowerCase())}`;
        return `
                                <div class="metric-item">
                                    <div class="metric-label">${tf}</div>
                                    <div class="metric-value ${colorClass}">${mark}</div>
                                </div>
                            `;
    }).join('')}
                    </div>
                </div>

                ${!ticker.includes('-USD') && !ticker.includes('USDT') ? `
                    <div class="hot-detail-section">
                        <div class="hot-detail-section-title"><span>Fundamentals</span></div>
                        ${UI.renderHotListFmpSection(item)}
                    </div>
                ` : ''}

                <div class="hot-detail-section">
                    <div class="hot-detail-section-title">
                        <span>Strategy notes</span>
                        <button type="button" class="btn-mini" onclick="Actions.openStrategyModal('${item.ticker}')">Edit or add</button>
                    </div>
                    <div class="hot-card-notes">
                        ${UI.renderHotListNotes(item.ticker, item.strategy_notes)}
                    </div>
                </div>
            </div>
            <div class="hot-detail-footer">
                 <button type="button" class="btn-auth ds-btn" onclick="Actions.analyzeTicker('${item.ticker}')">Start AI analysis</button>
            </div>
        </div>
    `;

    modal.classList.remove('hidden');
    modal.style.display = 'flex';

    if (updateOnly) {
        const body = modal.querySelector('.hot-detail-body');
        if (body) body.scrollTop = prevBodyScrollTop;
    }
};

UI.closeHotListDetail = function () {
    window.expandedHotListTicker = null;
    const modal = document.getElementById('hotlist-detail-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
};

UI.renderHotListFmpSection = function (item) {
    // This used to say "FMP details are not loaded" with a "Load Details"
    // button whenever _details_loaded was false. FMP is retired and nothing can
    // set that flag from the UI, so the button could never load anything. Fall
    // through to the honest "provider retired" message below instead.
    if (!item) return '';

    const insider = item.insider || {};
    const ratings = item.ratings || {};
    const sector = item.sector || {};
    const target = item.target || {};
    const financialScores = item.financialScores || {};
    const targetSummary = item.targetSummary || {};
    const congressTrades = item.congressTrades || {};
    const ownerEarnings = (item.ownerEarnings || [])[0] || {};
    const enterpriseValues = (item.enterpriseValues || [])[0] || {};
    const incomeGrowth = (item.incomeGrowth || [])[0] || {};
    const cashFlowGrowth = (item.cashFlowGrowth || [])[0] || {};
    const reportingDates = (item.reportingDates || [])[0] || {};
    const fundamentalSnapshot = item.fundamentalSnapshot || {};

    // Skip for crypto
    if (item.ticker.endsWith('-USD') || item.ticker.endsWith('USDT')) {
        return '';
    }

    // FMP was retired — the backend no longer produces any of these datasets.
    // Render an honest empty state instead of fake zeros (Piotroski "0/9" in
    // red, a bankruptcy-risk tooltip built from nothing).
    const hasFmpData = !!(insider.sentiment || ratings.rating ||
        (financialScores && Object.keys(financialScores).length) ||
        (target && Object.keys(target).length) ||
        (sector && Object.keys(sector).length) ||
        congressTrades.totalTrades);
    if (!hasFmpData) {
        return `
            <div class="hot-detail-unavailable">
                Not configured: fundamentals data provider (FMP was retired and no replacement is set up). Fundamental scores (Piotroski, Z-Score, ratings, analyst target) are unavailable until one is configured. Technical metrics (ADX, momentum, trends) are on the card, each with its own freshness.
            </div>
        `;
    }

    // Insider sentiment colors
    const insiderColor = insider.sentiment === 'bullish' ? 'var(--ds-pos)' :
        insider.sentiment === 'bearish' ? 'var(--ds-neg)' : 'var(--ds-text-3)';
    const insiderIcon = insider.sentiment === 'bullish' ? 'fa-arrow-trend-up' :
        insider.sentiment === 'bearish' ? 'fa-arrow-trend-down' : 'fa-minus';

    // Piotroski Score colors (0-3=bad, 4-6=neutral, 7-9=good)
    const piotroski = financialScores.piotroskiScore ?? null;
    const piotroskiColor = piotroski == null ? 'var(--ds-text-3)' : piotroski >= 7 ? 'var(--ds-pos)' : piotroski >= 4 ? 'var(--ds-warn)' : 'var(--ds-neg)';

    // Congress trades
    const congressSentiment = congressTrades.sentiment || 'neutral';
    const congressColor = congressSentiment === 'bullish' ? 'var(--ds-pos)' :
        congressSentiment === 'bearish' ? 'var(--ds-neg)' : 'var(--ds-text-3)';
    const congressIcon = congressSentiment === 'bullish' ? 'fa-arrow-trend-up' :
        congressSentiment === 'bearish' ? 'fa-arrow-trend-down' : 'fa-minus';
    const congressTotal = congressTrades.totalTrades ?? null;

    // Rating grade colors (A=green, B=yellow, C/D/F=red)
    const grade = (ratings.rating || '')[0] || '';
    const ratingColor = ['A'].includes(grade) ? 'var(--ds-pos)' :
        ['B'].includes(grade) ? 'var(--ds-warn)' : 'var(--ds-neg)';

    // Calculate upside/downside from target
    const currentPrice = item.price || 0;
    const targetPrice = target.targetConsensus || 0;
    const upside = currentPrice > 0 && targetPrice > 0 ? ((targetPrice - currentPrice) / currentPrice * 100) : 0;
    const upsideColor = upside >= 10 ? 'var(--ds-pos)' : upside <= -10 ? 'var(--ds-neg)' : 'var(--ds-text-3)';

    // Analyst count from targetSummary
    const analystCount = targetSummary.lastQuarterCount || 0;

    const pick = (obj, keys, fallback = null) => {
        if (!obj || typeof obj !== 'object') return fallback;
        for (const k of keys) {
            if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
            const lk = String(k).toLowerCase();
            if (obj[lk] !== undefined && obj[lk] !== null && obj[lk] !== '') return obj[lk];
        }
        return fallback;
    };
    const toNum = (v, d = NaN) => {
        if (v == null || v === '') return d;
        const n = v == null || v === '' ? NaN : Number(v);
        return Number.isFinite(n) ? n : d;
    };
    const fmtShort = (v) => {
        const n = v == null || v === '' ? NaN : Number(v);
        if (!Number.isFinite(n)) return 'N/A';
        if (Math.abs(n) >= 1e12) return `${(n / 1e12).toFixed(2)}T`;
        if (Math.abs(n) >= 1e9) return `${(n / 1e9).toFixed(2)}B`;
        if (Math.abs(n) >= 1e6) return `${(n / 1e6).toFixed(2)}M`;
        if (Math.abs(n) >= 1e3) return `${(n / 1e3).toFixed(1)}K`;
        return n.toFixed(2);
    };
    const fmtPct = (v) => {
        const n = v == null || v === '' ? NaN : Number(v);
        if (!Number.isFinite(n)) return 'N/A';
        return `${(n * 100).toFixed(2)}%`;
    };
    const pctClass = (v) => {
        const n = v == null || v === '' ? NaN : Number(v);
        if (!Number.isFinite(n)) return '';
        return n > 0 ? 'text-green' : (n < 0 ? 'text-red' : 'text-muted');
    };

    const ownerPerShare = pick(ownerEarnings, ['ownerEarningsPerShare', 'ownersEarningsPerShare', 'ownerEarningsPerShareDiluted'], pick(fundamentalSnapshot, ['owner_earnings_per_share']));
    const ownerEarningsVal = pick(ownerEarnings, ['ownerEarnings', 'ownersEarnings'], pick(fundamentalSnapshot, ['owner_earnings']));
    const enterpriseValue = pick(enterpriseValues, ['enterpriseValue'], pick(fundamentalSnapshot, ['enterprise_value']));
    const evToEbitda = pick(enterpriseValues, ['evToEbitda', 'enterpriseValueOverEBITDA'], pick(fundamentalSnapshot, ['ev_to_ebitda']));
    const revGrowth = pick(incomeGrowth, ['growthRevenue'], pick(fundamentalSnapshot, ['revenue_growth_yoy']));
    const niGrowth = pick(incomeGrowth, ['growthNetIncome'], pick(fundamentalSnapshot, ['net_income_growth_yoy']));
    const fcfGrowth = pick(cashFlowGrowth, ['growthFreeCashFlow'], pick(fundamentalSnapshot, ['free_cash_flow_growth_yoy']));
    const reportDateRaw = pick(
        reportingDates,
        ['date', 'date_formatted', 'reportDate', 'fiscalDateEnding'],
        pick(fundamentalSnapshot, ['reporting_date'], null)
    );
    const reportDate = reportDateRaw || (reportingDates && reportingDates.fiscalYear ? `${reportingDates.period || 'FY'} ${reportingDates.fiscalYear}` : 'N/A');

    // Build tooltips
    // Build Insider trades (Restore to 10)
    const insiderTradesList = (insider.trades || []).slice(0, 10).map(t => {
        const icon = t.type === 'Purchase' ? '+' : t.type === 'Sale' ? '-' : '*';
        const nameClean = (t.name.length > 20 ? t.name.substring(0, 17) + '..' : t.name).padEnd(20, ' ');
        const typeClean = t.type.padEnd(10, ' ');
        const amtStr = t.shares > 0 ? (t.shares.toLocaleString() + ' sh') : ('$' + (t.value / 1000).toFixed(0) + 'k');
        const amtClean = amtStr.padEnd(15, ' ');
        return `${icon} ${nameClean} | ${typeClean} | ${amtClean} | ${t.date}`;
    }).join('\n');

    const insiderTooltip = `INSIDER TRADING

Bullish = Buying > Selling | Bearish = Selling > Buying

Context:
Total Buying:  $${insider.netBuying == null ? 'N/A' : Number(insider.netBuying).toLocaleString()}
Total Selling: $${insider.netSelling == null ? 'N/A' : Number(insider.netSelling).toLocaleString()}

--- RECENT TRADES ---
Icon  Name                 | Type       | Amount          | Date
${insiderTradesList || 'No recent trades reported'}`;

    const zScore = parseFloat(financialScores.altmanZScore);
    const zStatus = !Number.isFinite(zScore) ? "N/A" : zScore > 2.99 ? "SAFE (Low risk)" :
        zScore >= 1.81 ? "WARNING (Gray zone)" :
            "RISK (Bankruptcy risk)";

    const piotroskiTooltip = `PIOTROSKI F-SCORE (${piotroski == null ? 'N/A' : piotroski + '/9'})
7-9: STRONG | 4-6: MEDIUM | 0-3: WEAK

Altman Z-Score: ${financialScores.altmanZScore || 'N/A'}
  Status: ${zStatus}

  Interpretation:
  > 2.99: Solid financial health
  1.81 - 2.99: Caution, average performance
  < 1.81: High risk of financial difficulties`;

    const ratingTooltip = `RATING FMP (${ratings.rating || 'N/A'})

Scale: F (weak) to A+ (excellent)
DCF: ${ratings.discountedCashFlowScore ?? 'N/A'}/5
  Discounted Cash Flow (Intrinsic value assessment)
ROE: ${ratings.returnOnEquityScore ?? 'N/A'}/5
  Return on equity (Capital utilization efficiency)
ROA: ${ratings.returnOnAssetsScore ?? 'N/A'}/5
  Return on assets (Resource utilization efficiency)
D/E: ${ratings.debtToEquityScore ?? 'N/A'}/5
  Debt/Capital Ratio (Leverage level)
P/E: ${ratings.priceToEarningsScore ?? 'N/A'}/5
  Price/Earnings Ratio (Profit assessment)
P/B: ${ratings.priceToBookScore ?? 'N/A'}/5
  Price/Book Ratio (Asset assessment)

Overall Score: ${ratings.overallScore ?? 'N/A'}/5`;

    const targetTooltip = `TARGET: $${targetPrice ? targetPrice.toFixed(0) : 'N/A'}
High: $${target.targetHigh ? target.targetHigh.toFixed(0) : 'N/A'} | Low: $${target.targetLow ? target.targetLow.toFixed(0) : 'N/A'}
Upside: ${currentPrice > 0 && targetPrice > 0 ? upside.toFixed(1) + '%' : 'N/A'}`;

    const senateTrades = (congressTrades.senate || []).slice(0, 10).map(t => {
        const nameClean = (t.name.length > 20 ? t.name.substring(0, 17) + '..' : t.name).padEnd(20, ' ');
        const typeClean = (t.type || '-').padEnd(10, ' ');
        const amtClean = t.amount.replace('$', '').substring(0, 13).padEnd(15, ' ');
        return `SEN ${nameClean} | ${typeClean} | ${amtClean} | ${t.date}`;
    }).join('\n');

    const houseTrades = (congressTrades.house || []).slice(0, 10).map(t => {
        const nameClean = (t.name.length > 20 ? t.name.substring(0, 17) + '..' : t.name).padEnd(20, ' ');
        const typeClean = (t.type || '-').padEnd(10, ' ');
        const amtClean = t.amount.replace('$', '').substring(0, 13).padEnd(15, ' ');
        return `HSE ${nameClean} | ${typeClean} | ${amtClean} | ${t.date}`;
    }).join('\n');

    const congressTooltip = `CONGRESS TRADES (${congressTotal ?? 'N/A'})

--- SENATE ---
Icon Name                 | Type       | Amount          | Date
${senateTrades || 'No recent trades'}

--- HOUSE ---
Icon Name                 | Type       | Amount          | Date
${houseTrades || 'No recent trades'}`;

    const sectorTooltip = `SECTOR & INDUSTRY

Sector: ${typeof sector === 'string' ? sector : (sector.name || sector.sector || 'N/A')}
Industry: ${sector.industry || 'N/A'}

Sector indicates the general economic group,
and industry indicates the specific niche.`;

    return `
        <div class="hot-card-fmp" style="display:grid; grid-template-columns: repeat(2, 1fr); gap:10px; margin:12px 0; padding:12px 40px; background:var(--ds-surface-inset); border-radius:8px;">
            
            <!-- Insider Trading -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${insiderTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid ${insiderIcon}" style="color:${insiderColor}; font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Insider <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600; color:${insiderColor}; text-transform:capitalize;">${insider.sentiment || 'N/A'}</div>
                </div>
            </div>
            
            <!-- Piotroski Score -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${piotroskiTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid fa-chart-line" style="color:${piotroskiColor}; font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Piotroski <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600; color:${piotroskiColor};">${piotroski == null ? 'N/A' : piotroski + '/9'}</div>
                </div>
            </div>
            
            <!-- Analyst Rating -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${ratingTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid fa-star" style="color:${ratingColor}; font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Rating <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600; color:${ratingColor};">${ratings.rating || 'N/A'}</div>
                </div>
            </div>
            
            <!-- Target Price with Upside -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${targetTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid fa-bullseye" style="color:var(--ds-info); font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Target <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600;">
                        <span style="color:var(--ds-info);">$${targetPrice ? targetPrice.toFixed(0) : 'N/A'}</span>
                        ${upside !== 0 ? `<span style="font-size:0.7rem; color:${upsideColor}; margin-left:4px;">(${upside >= 0 ? '+' : ''}${upside.toFixed(0)}%)</span>` : ''}
                    </div>
                </div>
            </div>
            
            <!-- Congress Trades -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${congressTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid ${congressIcon}" style="color:${congressColor}; font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Congress <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600; color:${congressColor};">${congressTotal > 0 ? congressTotal + ' trades' : 'N/A'}</div>
                </div>
            </div>
            
            <!-- Sector -->
            <div class="fmp-item fmp-tooltip-trigger" style="display:flex; align-items:center; gap:8px; cursor:help; position:relative;" data-tooltip="${sectorTooltip.replace(/"/g, '&quot;')}">
                <i class="fa-solid fa-industry" style="color:var(--ds-text-3); font-size:0.9rem; pointer-events:none;"></i>
                <div style="pointer-events:none;">
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Sector <i class="fa-solid fa-circle-info" style="font-size:0.6rem; opacity:0.5;"></i></div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${typeof sector === 'string' ? sector : (sector.name || sector.sector || 'N/A')}</div>
                </div>
            </div>
            
        </div>

        <div class="hot-card-fmp" style="display:grid; grid-template-columns: repeat(2, 1fr); gap:10px; margin:10px 0 6px; padding:12px 40px; background:var(--ds-surface-inset); border-radius:8px;">
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="Owner Earnings:\nReal cash generated by the business for shareholders (Warren Buffett Method).\nMore relevant than net accounting profit.">
                <i class="fa-solid fa-scale-balanced" style="color:var(--ds-text); font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Owner Earnings</div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${ownerEarningsVal !== null ? `$${fmtShort(ownerEarningsVal)}` : 'N/A'}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="Owner EPS:\nOwner earnings per share.\nShows how much real cash each share generates.">
                <i class="fa-solid fa-coins" style="color:var(--ds-text); font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Owner EPS</div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${ownerPerShare !== null ? Number(ownerPerShare).toFixed(2) : 'N/A'}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="Enterprise Value (EV):\nTotal company value.\n(Market Capitalization + Debt - Cash)\nHow much it would cost to buy the entire company.">
                <i class="fa-solid fa-building-columns" style="color:var(--ds-text); font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Enterprise Value</div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${enterpriseValue !== null ? `$${fmtShort(enterpriseValue)}` : 'N/A'}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="EV / EBITDA:\nValuation multiple (How expensive the company is).\nA lower number is usually better (undervalued).\nCompare with other companies in the same industry.">
                <i class="fa-solid fa-chart-area" style="color:var(--ds-text); font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">EV / EBITDA</div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${Number.isFinite(toNum(evToEbitda, NaN)) ? toNum(evToEbitda).toFixed(2) : 'N/A'}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="Revenue YoY:\nSales growth compared to last year.\nGreen = Growth (Good)\nRed = Decline (Bad)">
                <i class="fa-solid fa-arrow-trend-up" style="color:${!Number.isFinite(toNum(revGrowth)) ? 'var(--ds-text-3)' : toNum(revGrowth) >= 0 ? 'var(--ds-pos)' : 'var(--ds-neg)'}; font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Revenue YoY</div>
                    <div class="${pctClass(revGrowth)}" style="font-size:0.85rem; font-weight:600;">${fmtPct(revGrowth)}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px; cursor: help;" title="FCF YoY (Free Cash Flow):\nFree Cash Flow growth.\nEssential for dividends, buybacks and investments.\nGreen = Robust growth.">
                <i class="fa-solid fa-money-bill-trend-up" style="color:${!Number.isFinite(toNum(fcfGrowth)) ? 'var(--ds-text-3)' : toNum(fcfGrowth) >= 0 ? 'var(--ds-pos)' : 'var(--ds-neg)'}; font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">FCF YoY</div>
                    <div class="${pctClass(fcfGrowth)}" style="font-size:0.85rem; font-weight:600;">${fmtPct(fcfGrowth)}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px;">
                <i class="fa-solid fa-wave-square" style="color:${!Number.isFinite(toNum(niGrowth)) ? 'var(--ds-text-3)' : toNum(niGrowth) >= 0 ? 'var(--ds-pos)' : 'var(--ds-neg)'}; font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Net Income YoY</div>
                    <div class="${pctClass(niGrowth)}" style="font-size:0.85rem; font-weight:600;">${fmtPct(niGrowth)}</div>
                </div>
            </div>
            <div class="fmp-item" style="display:flex; align-items:center; gap:8px;">
                <i class="fa-regular fa-calendar-check" style="color:var(--ds-text); font-size:0.9rem;"></i>
                <div>
                    <div style="font-size:0.7rem; color:var(--ds-text-3);">Report Date</div>
                    <div style="font-size:0.85rem; font-weight:600; color:var(--ds-text);">${reportDate || 'N/A'}</div>
                </div>
            </div>
        </div>
        
        ${sector.industry && sector.industry !== 'Unknown' ? `
        <div style="font-size:0.75rem; color:var(--ds-text-3); margin-bottom:8px; display:flex; align-items:center; gap:6px;">
            <i class="fa-solid fa-building"></i>
            <span>${sector.industry}</span>
        </div>
        ` : ''}
    `;
};

Actions.toggleHotList = async function (ticker) {
    try {
        const normalized = (ticker || '').toUpperCase().trim();
        if (!normalized) return;

        const res = await fetch('/api/watchlist/hotlist/toggle', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ticker: normalized })
        });

        if (res.ok) {
            const data = await res.json();
            const isIn = !!data.is_in;
            UI.showToast(`${normalized} ${isIn ? 'added to' : 'removed from'} Hot List`, 'info');

            if (!cachedState) cachedState = {};

            // Update watchlist hot_list (for dashboard + is_hot flags)
            if (!cachedState.watchlist) {
                cachedState.watchlist = { stocks: [], crypto: [], yahoo: [], binance: [], hot_list: [] };
            }
            let wlHot = Array.isArray(cachedState.watchlist.hot_list) ? [...cachedState.watchlist.hot_list] : [];
            const wlHas = wlHot.includes(normalized);
            if (isIn && !wlHas) wlHot.push(normalized);
            if (!isIn && wlHas) wlHot = wlHot.filter(t => t !== normalized);
            cachedState.watchlist.hot_list = wlHot;

            // Update tickers list flags (watchlist table)
            if (Array.isArray(cachedState.tickers)) {
                const item = cachedState.tickers.find(i => i && i.ticker === normalized);
                if (item) item.is_hot = isIn;
            }

            // Update hot_list cards (hotlist view)
            let hotItems = Array.isArray(cachedState.hot_list) ? [...cachedState.hot_list] : [];
            const idx = hotItems.findIndex(i => i && i.ticker === normalized);
            if (isIn) {
                if (idx === -1) {
                    // Placeholder until the server row arrives (about a second).
                    // It used to carry price 0 / +0.00% / RSI 50 / EDGE C 50 /
                    // WAIT / RISK MED — a made-up quote and verdict for a ticker
                    // nothing had been computed for. Mark it as not scored yet.
                    hotItems.push({
                        ticker: normalized,
                        price: null,
                        change_pct: null,
                        trend_1d: 'N/A',
                        trend_4h: 'N/A',
                        trend_1h: 'N/A',
                        trend_30m: 'N/A',
                        trend_5m: 'N/A',
                        rsi: null,
                        macd_hist: null,
                        earnings_date: 'N/A',
                        earnings_days: -1,
                        earnings_when: '',
                        earnings_when_desc: '',
                        momentum_1w: null,
                        momentum_1m: null,
                        earnings_edge_score: 0,
                        earnings_play: 'INSUFFICIENT_DATA',
                        earnings_setup: 'N/A',
                        earnings_risk_flags: [],
                        risk_level: 'med',
                        top_risk: 'not scored yet — loading',
                        verdict_status: 'insufficient_data',
                        overall_score: 0,
                        priority_score: 0,
                        confidence_score: 0,
                        data_coverage_pct: 0,
                        missing_inputs: ['price', 'trend', 'momentum', 'adx', 'news', 'earnings_date', 'earnings_history'],
                        news_signals: {
                            counts: { '7d': 0, '30d': 0, '90d': 0, positive: 0, negative: 0, risk_events: 0 },
                            top_headlines: { '7d': [], '30d': [] },
                            catalysts_positive: [],
                            catalysts_negative: [],
                            risk_events: [],
                            sentiment_trend: 'unknown'
                        },
                        strategy_notes: '',
                        best_strategy: {},
                        _details_loaded: false
                    });
                }
            } else if (idx !== -1) {
                hotItems.splice(idx, 1);
            }
            cachedState.hot_list = hotItems;

            // Keep state cache in sync if present
            if (API._stateCache && API._stateCache.data) {
                const sc = API._stateCache.data;
                if (sc.watchlist) sc.watchlist.hot_list = wlHot;
                if (Array.isArray(sc.tickers)) {
                    const scItem = sc.tickers.find(i => i && i.ticker === normalized);
                    if (scItem) scItem.is_hot = isIn;
                }
                if (Array.isArray(sc.hot_list)) {
                    const scIdx = sc.hot_list.findIndex(i => i && i.ticker === normalized);
                    if (isIn) {
                        if (scIdx === -1) {
                            sc.hot_list.push({
                                ticker: normalized,
                                earnings_edge_score: 50,
                                earnings_play: 'WAIT',
                                earnings_setup: 'C',
                                earnings_risk_flags: [],
                                risk_level: 'med',
                                top_risk: 'unknown',
                                news_signals: {
                                    counts: { '7d': 0, '30d': 0, '90d': 0, positive: 0, negative: 0, risk_events: 0 },
                                    top_headlines: { '7d': [], '30d': [] },
                                    sentiment_trend: 'unknown'
                                },
                                _details_loaded: false
                            });
                        }
                    } else if (scIdx !== -1) {
                        sc.hot_list.splice(scIdx, 1);
                    }
                }
            }

            UI.saveState(cachedState);

            if (ViewRouter.activeView === 'hotlist') UI.scheduleRender('hotlist:toggle', () => UI.renderHotList(cachedState), 30);
            if (ViewRouter.activeView === 'watchlist') UI.scheduleRender('watchlist:hotlist-toggle', () => UI.renderDetailedWatchlist(cachedState), 30);
            if (cachedState.watchlist) {
                UI.scheduleRender('home:watchlist-hotlist-toggle', () => UI.renderWatchlist(cachedState.watchlist, cachedState), 40);
            }

            // Lightweight refresh in background to reconcile data without blocking UI
            setTimeout(() => {
                API.getState({ includeNews: false, includeHotlist: true, hotlistDetails: false, lean: false })
                    .then(state => {
                        cachedState = UI.mergeStatePreserveDetails(cachedState, state);
                        UI.saveState(cachedState);
                        if (ViewRouter.activeView === 'hotlist') UI.scheduleRender('hotlist:toggle-refresh', () => UI.renderHotList(cachedState), 30);
                        if (ViewRouter.activeView === 'watchlist') UI.scheduleRender('watchlist:hotlist-toggle-refresh', () => UI.renderDetailedWatchlist(cachedState), 30);
                        if (state.watchlist) {
                            UI.scheduleRender('home:watchlist-hotlist-refresh', () => UI.renderWatchlist(state.watchlist, cachedState), 40);
                        }
                    })
                    .catch(e => console.error('Hot list refresh failed', e));
            }, 1200);
        } else {
            // A rejected toggle (HTTP 4xx/5xx) used to do nothing at all: no
            // toast, no change — the HOT button looked dead.
            let detail = '';
            try { const body = await res.json(); detail = (body && (body.detail || body.error)) ? String(body.detail || body.error) : ''; } catch (_) { /* no JSON body */ }
            UI.showToast(`Could not update the Hot List for ${normalized} (HTTP ${res.status}${detail ? ': ' + detail : ''})`, 'error');
        }
    } catch (e) {
        console.error("Hot list toggle error", e);
        UI.showToast("Error modifying list", "error");
    }
};

Actions.analyzeTicker = async function (ticker, forceRefresh = false) {
    // One request owns the modal at a time. A request that was replaced by a
    // newer one (another ticker, or Refresh) must not touch the modal or the
    // shared abort handle when it finally settles.
    const controller = new AbortController();
    const isCurrent = () => Actions._analysisAbort === controller;
    try {
        UI.showToast(forceRefresh ? `Refreshing ${ticker}...` : `Analyzing ${ticker}...`, 'info');
        // Show loading modal immediately so user sees the server is working
        Actions.showAnalysisModal(ticker, { _loading: true });

        if (Actions._analysisAbort) {
            Actions._analysisAbort.abort();
        }
        Actions._analysisAbort = controller;
        const modePref = localStorage.getItem('signal_mode_preference') || 'V1';

        const response = await API.fetchWithTimeout(`/api/analyze-ticker`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ ticker: ticker, include_heavy: false, force_refresh: !!forceRefresh, mode: modePref }),
            timeout: 420000,
            signal: controller.signal
        });
        if (!response.ok) throw new Error(`Analysis failed (HTTP ${response.status})`);

        const analysis = await response.json();
        if (!isCurrent()) return; // a newer request owns the modal now

        // The server answers 200 with an `error` field and placeholder zeros
        // (price 0, RSI 50, MACD 0) when it could not fetch the ticker. That
        // is a failed analysis, not a result to render.
        if (Actions.analysisFailure(analysis)) {
            UI.showToast(`Error analyzing ${ticker}`, 'error');
            Actions.showAnalysisModal(ticker, { _error: true, _errorMsg: Actions.analysisFailure(analysis) });
            return;
        }

        // Show analysis in a modal or dedicated view
        Actions.showAnalysisModal(ticker, analysis);

    } catch (e) {
        if (!isCurrent()) return; // superseded: the newer request reports its own state
        console.error("Analysis error:", e);
        const msg = (e && e.message) ? e.message.toLowerCase() : '';
        if (e && (e.name === 'AbortError' || msg.includes('abort'))) {
            UI.showToast(`Analysis cancelled for ${ticker}`, 'warning');
            Actions.showAnalysisModal(ticker, { _error: true, _errorMsg: 'Analysis was cancelled by the user.' });
        } else {
            UI.showToast(`Error analyzing ${ticker}`, 'error');
            Actions.showAnalysisModal(ticker, { _error: true, _errorMsg: e.message || 'Unknown error' });
        }
    } finally {
        if (isCurrent()) Actions._analysisAbort = null;
    }
};

// Reason text when an /api/analyze-ticker payload is a failure, else ''.
Actions.analysisFailure = function (analysis) {
    if (!analysis || typeof analysis !== 'object') return 'The server returned no analysis.';
    const price = Number(analysis.price);
    if (analysis.error && !(Number.isFinite(price) && price > 0)) {
        return String(analysis.error);
    }
    return '';
};

// "12 min ago" / "3 h 05 min ago" / "2 d ago" for an analysis timestamp; '' when unknown.
Actions.analysisAgeLabel = function (timestamp, nowMs) {
    const ts = timestamp ? new Date(timestamp).getTime() : NaN;
    if (!Number.isFinite(ts)) return '';
    const minutes = Math.max(0, Math.floor(((Number.isFinite(nowMs) ? nowMs : Date.now()) - ts) / 60000));
    if (minutes < 1) return 'just now';
    if (minutes < 60) return `${minutes} min ago`;
    if (minutes < 1440) return `${Math.floor(minutes / 60)} h ${String(minutes % 60).padStart(2, '0')} min ago`;
    return `${Math.floor(minutes / 1440)} d ago`;
};

// How the AI tab must describe who wrote the analysis and what "confidence" is.
Actions.analysisAiProvenance = function (aiObject, model) {
    const source = String((aiObject && aiObject.source) || '').toLowerCase();
    const confidence = Number(aiObject && aiObject.confidence);
    const pct = Number.isFinite(confidence) ? `${Math.round(Math.max(0, Math.min(1, confidence)) * 100)}%` : 'n/a';
    if (source === 'deterministic_fallback') {
        return {
            isFallback: true,
            badge: 'Rule-based summary (no AI answer)',
            confidenceLabel: `Rule score ${pct} (not a probability)`,
            notice: String(aiObject.fallback_reason || 'The AI reply was not usable; this summary was computed by fixed rules.'),
            missing: Array.isArray(aiObject.missing_inputs) ? aiObject.missing_inputs.map(String) : [],
        };
    }
    return {
        isFallback: false,
        badge: String(model || 'AI model'),
        confidenceLabel: `AI self-rated confidence ${pct} (uncalibrated, not a probability)`,
        notice: '',
        // Inputs that were unknown when the model was asked, and figures in its
        // text that are not in the data it was given (server-side check).
        missing: Array.isArray(aiObject && aiObject.missing_inputs) ? aiObject.missing_inputs.map(String) : [],
        ungrounded: Array.isArray(aiObject && aiObject.ungrounded_numbers) ? aiObject.ungrounded_numbers.map(String) : [],
        numbersChecked: !!(aiObject && aiObject.numbers_checked),
    };
};

Actions._analysisAbort = null;
Actions.cancelAnalysis = function () {
    if (Actions._analysisAbort) {
        Actions._analysisAbort.abort();
        Actions._analysisAbort = null;
        // The aborted request no longer owns the modal, so it will not report
        // itself: replace the spinner with the cancelled state here.
        const cancelledTicker = Actions._currentAnalysisTicker;
        const modal = document.getElementById('analysis-modal');
        if (cancelledTicker && modal && !modal.classList.contains('hidden')) {
            UI.showToast(`Analysis cancelled for ${cancelledTicker}`, 'warning');
            Actions.showAnalysisModal(cancelledTicker, { _error: true, _errorMsg: 'Analysis was cancelled by the user.' });
        }
    }
};

Actions._currentAnalysisTicker = null;
Actions.forceRefreshAnalysis = function () {
    if (!Actions._currentAnalysisTicker) return;
    Actions.analyzeTicker(Actions._currentAnalysisTicker, true);
};

UI.formatAnalysisText = function (text) {
    if (!text) return '';
    // Replace long sequences of = or - with clean dividers
    let formatted = text.replace(/[=]{10,}/g, '<div class="analysis-divider"></div>');
    formatted = formatted.replace(/[-]{10,}/g, '<div class="analysis-divider"></div>');

    // Replace common headers like "TICKER ANALYSIS:" or "TYPE:" with styled versions
    formatted = formatted.replace(/([A-Z\s]+:)/g, '<span class="analysis-header-line">$1</span>');

    return formatted;
};

Actions.showAnalysisModal = function (ticker, analysis) {
    Actions._currentAnalysisTicker = ticker;
    let modal = document.getElementById('analysis-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'analysis-modal';
        modal.className = 'modal-overlay';
        // Force flex centering on overlay to ensure margin:auto works vertically
        modal.style.display = 'flex';
        modal.style.alignItems = 'center';
        modal.style.justifyContent = 'center';

        modal.innerHTML = `
            <div class="modal-content an-modal">
                <div class="modal-header an-head">
                    <h3 id="analysis-modal-title">Analysis</h3>
                    <div class="an-head-actions">
                        <button id="analysis-refresh-btn" class="ds-btn ds-btn--sm" onclick="Actions.forceRefreshAnalysis()">
                            <i class="fa-solid fa-rotate"></i> Refresh
                        </button>
                        <button class="btn-modal-close" aria-label="Close" onclick="Actions.closeAnalysisModal()"><i class="fa-solid fa-xmark" aria-hidden="true"></i></button>
                    </div>
                </div>
                <div id="analysis-tabs" class="analysis-tabs"></div>
                <div id="analysis-modal-body" class="modal-body an-body"></div>
            </div>
        `;
        document.body.appendChild(modal);
    }

    const body = document.getElementById('analysis-modal-body');
    const a = analysis;
    const escAn = UI._escapeHtml || ((value) => String(value ?? ''));
    // A cached analysis is a snapshot: say when it was made and at what price,
    // so an hour-old result is not read as the current market.
    const analysedAge = (a && !a._loading && !a._error) ? Actions.analysisAgeLabel(a.timestamp) : '';
    const analysedPrice = (a && Number.isFinite(Number(a.price)) && Number(a.price) > 0) ? `$${UI.formatPrice(a.price)}` : '';
    const snapshotText = analysedAge
        ? `analysed ${analysedAge}${analysedPrice ? ` at ${analysedPrice}` : ''}`
        : ((a && a.cached) ? 'analysis time unknown' : '');
    const cachedBadge = a && a.cached ? '<span class="ds-chip an-cached" title="This result was read from the cache, not computed now">CACHED</span>' : '';
    const snapshotBadge = snapshotText
        ? `<span id="analysis-snapshot-age" class="an-snapshot" title="${escAn(a && a.timestamp ? String(a.timestamp) : '')}">${escAn(snapshotText)}</span>`
        : '';
    document.getElementById('analysis-modal-title').innerHTML = `<span class="an-title-text">${escAn(ticker)} - Deep Analysis</span> ${cachedBadge}${snapshotBadge}`;
    const refreshBtn = document.getElementById('analysis-refresh-btn');
    if (refreshBtn) {
        refreshBtn.disabled = !!(a && a._loading);
        refreshBtn.innerHTML = `<i class="fa-solid fa-rotate"></i> ${a && a.cached ? 'Force refresh' : 'Refresh'}`;
    }
    const tabsEl = document.getElementById('analysis-tabs');

    // Update tabs on every call (modal is reused)
    if (tabsEl) {
        const hasFundamentals = a && (Object.prototype.hasOwnProperty.call(a, 'fundamentals') || Object.prototype.hasOwnProperty.call(a, 'quote'));
        const hasAI = a && Object.prototype.hasOwnProperty.call(a, 'ai_analysis');
        tabsEl.innerHTML = `
            <button class="analysis-tab-btn active" data-tab="tehnic" onclick="Actions.switchAnalysisTab('tehnic')"><i class="fa-solid fa-chart-line"></i> Technical</button>
            ${hasFundamentals ? `<button class="analysis-tab-btn" data-tab="fundamente" onclick="Actions.switchAnalysisTab('fundamente')"><i class="fa-solid fa-building-columns"></i> Fundamentals</button>` : ''}
            ${hasAI ? `<button class="analysis-tab-btn btn-ai-pulse" data-tab="ai-ollama" onclick="Actions.switchAnalysisTab('ai-ollama')"><i class="fa-solid fa-brain"></i> AI analysis</button>` : ''}
            <button class="analysis-tab-btn" data-tab="carnet" onclick="Actions.switchAnalysisTab('carnet')"><i class="fa-solid fa-book"></i> Ticker notebook</button>
        `;
    }

    // Loading/Error states
    if (a && a._loading) {
        body.innerHTML = `
            <div class="an-state">
                <div class="an-state-icon">
                    <i class="fa-solid fa-spinner fa-spin"></i>
                </div>
                <div class="an-state-title">Analysing ${escAn(ticker)}...</div>
                <div class="an-state-text">
                    Fetching market data, technical indicators and the AI review.<br>
                    <b>This can take 1-3 minutes</b> on the first run.<br>
                    The result is then cached for up to 1 hour (30 minutes near earnings).
                </div>
                <div class="an-state-actions">
                    <button class="ds-btn" onclick="Actions.cancelAnalysis()">Cancel</button>
                </div>
            </div>
        `;
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
        return;
    }
    if (a && a._error) {
        body.innerHTML = `
            <div class="an-state an-state--error">
                <div class="an-state-icon">
                    <i class="fa-solid fa-triangle-exclamation"></i>
                </div>
                <div class="an-state-title">Analysis failed</div>
                <div id="analysis-error-message" class="an-state-text">
                    ${escAn(a._errorMsg || 'Unknown error')}
                </div>
                ${(typeof UI._tickerPriceState === 'function' && UI._tickerPriceState(ticker, null))
                    ? `<div class="an-state-text an-state-note">${UI._priceStateHtml(UI._tickerPriceState(ticker, null))}</div>` : ''}
            </div>
        `;
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
        return;
    }

    // No data / delisted: the price tile says so; it is not a quote and not a move.
    const anPriceState = typeof UI._tickerPriceState === 'function' ? UI._tickerPriceState(ticker, a) : null;
    const modeScores = a.mode_scores || {};
    const modeOrder = ['PULLBACK', 'BREAKOUT', 'CONTRA'];
    const profileOrder = ['AGGRESSIVE', 'MODERATE', 'CONSERVATIVE'];
    const modeLabels = { PULLBACK: 'Pullback', BREAKOUT: 'Breakout', CONTRA: 'Contra' };
    const profileLabels = { AGGRESSIVE: 'Aggressive', MODERATE: 'Moderate', CONSERVATIVE: 'Conservative' };

    const orderedModes = [
        ...modeOrder.filter(m => modeScores[m]),
        ...Object.keys(modeScores).filter(m => !modeOrder.includes(m)),
    ];

    let bestCell = { score: -1, mode: null, profile: null, dir: '-' };
    orderedModes.forEach(mode => {
        const profiles = modeScores[mode] || {};
        profileOrder.forEach(profile => {
            const p = profiles[profile];
            if (!p) return;
            const score = Number(p.best_score ?? 0);
            if (score > bestCell.score) {
                bestCell = { score, mode, profile, dir: p.best_direction || '-', data: p };
            }
        });
    });

    const bestModeLabel = bestCell.mode ? (modeLabels[bestCell.mode] || bestCell.mode) : 'N/A';
    const bestProfileLabel = bestCell.profile ? (profileLabels[bestCell.profile] || bestCell.profile) : 'N/A';
    const bestDirectionLabel = bestCell.dir === 'LONG' ? 'LONG' : bestCell.dir === 'SHORT' ? 'SHORT' : 'N/A';
    const bestScoreVal = bestCell.score >= 0 ? bestCell.score : 0;
    const bestStrength = bestScoreVal >= 75 ? 'Strong' : bestScoreVal >= 60 ? 'Good' : bestScoreVal >= 45 ? 'Weak' : 'Very weak';

    const scoringDetailsHtml = Object.entries(modeScores || {}).map(([mode, profiles]) => {
        const rows = Object.entries(profiles || {}).map(([profile, p]) => {
            const details = p.details || {};
            const detailLines = Object.keys(details).length
                ? Object.entries(details).map(([k, v]) => `<span class="an-detail-item">${k}: ${v}</span>`).join('')
                : '<span class="text-muted">No detail data</span>';
            return `
                <div class="an-detail-row">
                    <div class="an-detail-name">${modeLabels[mode] || mode} / ${profileLabels[profile] || profile}</div>
                    <div class="an-detail-items">${detailLines}</div>
                </div>`;
        }).join('');
        return rows;
    }).join('') || '<div class="text-muted">No scoring details available.</div>';

    const modeDecision = a.mode_decision || {};
    const v2Block = a.v2 || {};
    const v2Best = v2Block.best_candidate || null;
    const v2Perf = (v2Best && v2Best.perf_snapshot) ? v2Best.perf_snapshot : {};
    const reverseInfo = v2Block.reverse_consideration || {};
    const v2ExtraHtml = v2Best ? `
        <div class="panel-section an-section">
            <h4 class="an-section-title">V2 validation snapshot</h4>
            <div class="ds-stats an-stats">
                <div class="ds-stat">
                    <div class="ds-label">Win rate</div>
                    <div class="ds-stat-value">${((Number(v2Perf.win_rate || 0) <= 1 ? Number(v2Perf.win_rate || 0) * 100 : Number(v2Perf.win_rate || 0))).toFixed(1)}%</div>
                </div>
                <div class="ds-stat">
                    <div class="ds-label">Profit factor</div>
                    <div class="ds-stat-value">${v2Perf.profit_factor == null ? 'N/A' : Number(v2Perf.profit_factor).toFixed(2)}</div>
                </div>
                <div class="ds-stat">
                    <div class="ds-label">Expectancy</div>
                    <div class="ds-stat-value">${Number(v2Perf.expectancy_R || 0).toFixed(3)}R</div>
                </div>
                <div class="ds-stat">
                    <div class="ds-label">Sample size</div>
                    <div class="ds-stat-value">${Number(v2Perf.sample_size || 0)}</div>
                </div>
            </div>
            <div class="an-note">
                Reverse check: LONG ${Number(reverseInfo.best_long_score || 0).toFixed(2)} vs SHORT ${Number(reverseInfo.best_short_score || 0).toFixed(2)} | selected ${reverseInfo.selected_direction || 'N/A'}
            </div>
        </div>
    ` : '';
    const modeDecisionHtml = modeDecision.selected ? `
        <div class="an-mode-line">
            <strong>Mode:</strong> ${modeDecision.selected} ${modeDecision.why ? `| ${modeDecision.why}` : ''}
        </div>
    ` : '';

    // TECHNICAL TAB CONTENT
    const technicalHtml = `
        <div class="analysis-tab-content active" id="tab-tehnic">
            ${modeDecisionHtml}
            <div class="ds-stats an-stats">
                <div class="ds-stat">
                    <div class="ds-label">${anPriceState ? 'Price' : 'Current price'}</div>
                    ${anPriceState ? `<div class="ds-stat-note an-price-state">${UI._priceStateHtml(anPriceState, a.price)}</div>` : `<div class="ds-stat-value">$${UI.formatPrice(a.price)}</div>
                    <div class="ds-stat-note an-num ${a.change_pct >= 0 ? 'text-green' : 'text-red'}">${a.change_pct >= 0 ? '+' : ''}${Number(a.change_pct).toFixed(2)}%</div>`}
                </div>
                <div class="ds-stat">
                    <div class="ds-label">RSI (14)</div>
                    <div class="ds-stat-value">${(a.rsi != null && Number.isFinite(Number(a.rsi))) ? Number(a.rsi).toFixed(1) : 'N/A'}</div>
                    <div class="ds-stat-note ${(a.rsi == null || !Number.isFinite(Number(a.rsi))) ? '' : Number(a.rsi) > 70 ? 'ds-neg' : Number(a.rsi) < 30 ? 'ds-pos' : ''}">
                        ${(a.rsi == null || !Number.isFinite(Number(a.rsi))) ? 'N/A' : Number(a.rsi) > 70 ? 'Overbought' : Number(a.rsi) < 30 ? 'Oversold' : 'Neutral'}
                    </div>
                </div>
                <div class="ds-stat">
                    <div class="ds-label">MACD Hist</div>
                    <div class="ds-stat-value">${a.macd_hist ? a.macd_hist.toFixed(4) : 'N/A'}</div>
                    <div class="ds-stat-note ${a.macd_hist > 0 ? 'ds-pos' : a.macd_hist < 0 ? 'ds-neg' : ''}">
                        ${a.macd_hist > 0 ? 'Bullish' : a.macd_hist < 0 ? 'Bearish' : 'N/A'}
                    </div>
                </div>
            </div>

            <div class="an-section">
                <h4 class="an-section-title">Multi-timeframe trends</h4>
                <div class="an-tf-row">
                    ${['1D', '4H', '1H', '30M', '5M'].map(tf => {
        const val = a[`trend_${tf.toLowerCase()}`] || 'N/A';
        const isBull = val.includes('BULL');
        const isBear = val.includes('BEAR');
        const tone = isBull ? 'ds-chip--pos' : isBear ? 'ds-chip--neg' : '';
        const arrow = isBull ? '<i class="fa-solid fa-caret-up" aria-hidden="true"></i>' : isBear ? '<i class="fa-solid fa-caret-down" aria-hidden="true"></i>' : '';
        return `<span class="trend-badge ds-chip ${tone}">${tf}: ${val} ${arrow}</span>`;
    }).join('')}
                </div>
            </div>

            <!-- Advanced Indicators & Scoring -->
            <div class="an-two">
                <!-- Left: Advanced Indicators -->
                <div class="panel-section an-section">
                    <h4 class="an-section-title">Advanced indicators</h4>
                    <div class="an-rows">
                        <div class="an-row">
                            <span class="an-row-label">VWAP</span>
                            <div class="an-row-value">
                                <div class="an-num">${Number.isFinite(parseFloat(a.vwap)) ? `$${UI.formatPrice(a.vwap)}` : 'N/A'}</div>
                                <div class="an-row-sub ${a.distance_from_vwap_pct < 1 ? 'ds-pos' : ''}">${a.distance_from_vwap_pct ? a.distance_from_vwap_pct.toFixed(2) : 0}% dist</div>
                            </div>
                        </div>
                        <div class="an-row">
                            <span class="an-row-label">EMA 20</span>
                            <div class="an-row-value">
                                <div class="an-num">${Number.isFinite(parseFloat(a.ema20)) ? `$${UI.formatPrice(a.ema20)}` : 'N/A'}</div>
                                <div class="an-row-sub">${a.distance_from_ema20_pct ? a.distance_from_ema20_pct.toFixed(2) : 0}% dist</div>
                            </div>
                        </div>
                        <div class="an-row">
                            <span class="an-row-label">ATR (14)</span>
                            <div class="an-row-value">
                                <div class="an-num">${a.atr ? a.atr.toFixed(4) : 'N/A'}</div>
                                <div class="an-row-sub">Volatility</div>
                            </div>
                        </div>
                    </div>
                </div>

                <!-- Right: Best Signal -->
                <div class="panel-section an-section an-best">
                    <h4 class="an-section-title">Best signal</h4>
                    ${a.best_signal ? `
                        <div class="an-best-body">
                            <span class="ds-chip ${a.best_signal.direction === 'LONG' ? 'ds-chip--pos' : 'ds-chip--neg'} an-best-dir">
                                <i class="fa-solid ${a.best_signal.direction === 'LONG' ? 'fa-arrow-trend-up' : 'fa-arrow-trend-down'}" aria-hidden="true"></i> ${a.best_signal.direction}
                            </span>
                            <div class="an-best-mode">${a.best_signal.mode} / ${a.best_signal.profile}</div>
                            <div class="an-best-score"><span class="an-num">${a.best_signal.score}</span><span class="an-best-of">/100 score</span></div>
                        </div>
                    ` : `
                        <div class="an-best-empty">No valid signal found for this ticker in the current data.</div>
                    `}
                </div>
            </div>

            ${v2ExtraHtml}

            <!-- Scoring Grid (Simplified) -->
             <div class="panel-section an-section">
                <h4 class="an-section-title">Strategy scoring matrix</h4>

                <div class="an-matrix-head">
                    <div class="an-matrix-pick">
                        <div class="ds-label">Highest rule score</div>
                        <div class="an-matrix-pick-value">
                            ${bestDirectionLabel} · ${bestModeLabel} / ${bestProfileLabel}
                        </div>
                        <div class="an-note">
                            Score ${bestScoreVal}/100 · Strength: ${bestStrength}
                        </div>
                    </div>
                    <div class="an-matrix-legend">
                        <div class="ds-label">How to read</div>
                        <div class="an-note">
                            Score 75+ = Strong, 60-74 = Good, 45-59 = Weak, &lt;45 = Very weak.
                        </div>
                    </div>
                </div>

                <div class="an-matrix-scroll">
                    <table class="an-matrix">
                        <thead>
                            <tr>
                                <th>Profile</th>
                                ${orderedModes.map(m => `<th>${modeLabels[m] || m}</th>`).join('')}
                            </tr>
                        </thead>
                        <tbody>
                            ${profileOrder.map(prof => {
        return `
                                <tr>
                                    <td class="an-matrix-profile">${profileLabels[prof] || prof}</td>
                                    ${orderedModes.map(mode => {
            const profiles = modeScores[mode] || {};
            const pData = profiles[prof] || {};
            const score = Number(pData.best_score ?? 0);
            const dir = pData.best_direction || '-';
            const dirLabel = dir === 'LONG' ? 'LONG' : dir === 'SHORT' ? 'SHORT' : 'N/A';
            const dirChip = dir === 'LONG' ? 'ds-chip--pos' : dir === 'SHORT' ? 'ds-chip--neg' : '';
            const grade = score >= 75 ? 'Strong' : score >= 60 ? 'Good' : score >= 45 ? 'Weak' : 'Very weak';
            const isBest = bestCell.mode === mode && bestCell.profile === prof && score === bestCell.score;
            return `
                                        <td>
                                            <div class="an-cell ${isBest ? 'is-best' : ''}">
                                                <div class="an-cell-top">
                                                    <span class="an-cell-score">${score > 0 ? score : '-'}</span>
                                                    ${score > 0 ? `<span class="ds-chip ${dirChip}">${dirLabel}</span>` : ''}
                                                    ${isBest && score > 0 ? '<span class="an-cell-best">Highest</span>' : ''}
                                                </div>
                                                <div class="an-cell-grade">${score > 0 ? grade : 'N/A'}</div>
                                            </div>
                                        </td>
                                    `;
        }).join('')}
                                </tr>
                            `;
    }).join('')}
                        </tbody>
                  </table>
              </div>
              <div class="an-note">
                  Each cell shows the best score and its direction. The highest score is outlined.
              </div>
              <button class="ds-btn ds-btn--sm an-details-btn" onclick="UI.toggleScoreDetails()">Score details (advanced)</button>
              <div id="score-details" class="hidden an-details">
                  ${scoringDetailsHtml}
              </div>
          </div>
      </div>
      `;

    // FUNDAMENTAL TAB CONTENT
    let fundamentalHtml = '';
    if (a && (Object.prototype.hasOwnProperty.call(a, 'fundamentals') || Object.prototype.hasOwnProperty.call(a, 'quote'))) {
        const f = a.fundamentals || {};
        const q = a.quote || {};
        const qb = a.quote_batch || {};
        const bs = (f.balance_sheet || [{}])[0] || {};
        const cf = (f.cash_flow || [{}])[0] || {};
        // 2026-09-03: analyst_estimates is a DICT now (yfinance-migrated client)
        const est = Array.isArray(f.analyst_estimates) ? (f.analyst_estimates[0] || {}) : (f.analyst_estimates || {});
        const safeText = (v) => (v === null || v === undefined || v === '' || v === 'undefined') ? 'N/A' : v;
        const rDate = (f.reporting_dates || [{}])[0];
        const nextDateStr = safeText(rDate ? (rDate.date || rDate.reportingDate || rDate.date_formatted) : null);
        const nextDateSub = safeText(rDate ? (rDate.period || rDate.fiscalDate || rDate.fiscalDateEnding) : null);
        const growth = (f.growth || [{}])[0];
        // 2026-09-03: price_change / enterprise_values / income growth are DICTS
        const priceChange = f.price_change && !Array.isArray(f.price_change) ? f.price_change : ((f.price_change || [])[0] || {});
        const inc = (f.income_statement || [{}])[0];
        const cfst = (f.cash_flow_statement || [{}])[0] || {};
        const bs2 = (f.balance_sheet_statement || [{}])[0] || {};
        const ownerEarnings = (f.owner_earnings || [{}])[0];
        const enterpriseValues = f.enterprise_values && !Array.isArray(f.enterprise_values) ? f.enterprise_values : ((f.enterprise_values || [{}])[0] || {});
        const incomeGrowth = f.income_statement_growth && !Array.isArray(f.income_statement_growth) ? f.income_statement_growth : ((f.income_statement_growth || [{}])[0] || {});
        const cashFlowGrowth = (f.cash_flow_statement_growth || [{}])[0];
        const finGrowth = (f.financial_growth || [{}])[0];
        const cashAsReported = (f.cash_flow_as_reported || [{}])[0];
        const reportsJson = (f.financial_reports_json || []);
        const reportDateObj = (f.reporting_dates || [{}])[0];
        const eodLight = f.historical_eod_light || [];
        const eodFull = f.historical_eod_full || [];
        const epsAvg = est.estimatedEpsAvg ?? est.epsEstimatedAvg ?? est.estimatedEps ?? null;
        const epsLow = est.estimatedEpsLow ?? est.epsEstimatedLow ?? null;
        const epsHigh = est.estimatedEpsHigh ?? est.epsEstimatedHigh ?? null;
        const epsDate = safeText(est.date || est.period || est.fiscalDate || est.fiscalDateEnding);

        const fmtM = (v) => (v === null || v === undefined || v === '') ? 'N/A' : (Number(v) / 1e9).toFixed(2) + 'B';
        const fmtShort = (v) => {
            if (v === null || v === undefined || v === '') return 'N/A';
            const num = Number(v);
            if (!Number.isFinite(num)) return String(v);
            if (num >= 1e12) return (num / 1e12).toFixed(2) + 'T';
            if (num >= 1e9) return (num / 1e9).toFixed(2) + 'B';
            if (num >= 1e6) return (num / 1e6).toFixed(2) + 'M';
            if (num >= 1e3) return (num / 1e3).toFixed(1) + 'K';
            return num.toFixed(2);
        };
        // Dollar amounts: a missing value is "N/A", never "$N/A".
        const usdM = (v) => { const text = fmtM(v); return text === 'N/A' ? text : `$${text}`; };
        const usdShort = (v) => { const text = fmtShort(v); return text === 'N/A' ? text : `$${text}`; };
        const fmtPct = (v) => (v === null || v === undefined) ? 'N/A' : (Number(v) > 0 ? '+' : '') + (Number(v) * 100).toFixed(2) + '%';
        const colorPct = (v) => v > 0 ? 'text-green' : (v < 0 ? 'text-red' : '');
        const colorDebt = (v) => v > 0 ? 'text-red' : (v < 0 ? 'text-green' : '');
        const safePick = (obj, keys, fallback = null) => {
            if (!obj || typeof obj !== 'object') return fallback;
            for (const k of keys) {
                if (obj[k] !== undefined && obj[k] !== null && obj[k] !== '') return obj[k];
                const lk = String(k).toLowerCase();
                if (obj[lk] !== undefined && obj[lk] !== null && obj[lk] !== '') return obj[lk];
            }
            return fallback;
        };
        const pc = (v) => (v === null || v === undefined || v === '') ? 'N/A' : `${Number(v) > 0 ? '+' : ''}${Number(v).toFixed(2)}%`;
        const pcColor = (v) => (v > 0 ? 'text-green' : (v < 0 ? 'text-red' : 'text-muted'));
        const pcGet = (obj, key, altKey) => {
            if (!obj) return null;
            const pick = (k) => {
                if (k === undefined || k === null || k === '') return undefined;
                const v = obj[k];
                return (v === null || v === undefined || v === '') ? undefined : v;
            };
            const v1 = pick(key);
            if (v1 !== undefined) return v1;
            if (altKey) {
                const v2 = pick(altKey);
                if (v2 !== undefined) return v2;
            }
            const lk = key ? key.toLowerCase() : null;
            if (lk && pick(lk) !== undefined) return pick(lk);
            if (altKey) {
                const lk2 = altKey.toLowerCase();
                if (lk2 && pick(lk2) !== undefined) return pick(lk2);
            }
            const uk = key ? key.toUpperCase() : null;
            if (uk && pick(uk) !== undefined) return pick(uk);
            if (altKey) {
                const uk2 = altKey.toUpperCase();
                if (uk2 && pick(uk2) !== undefined) return pick(uk2);
            }
            return null;
        };
        const pc1D = pcGet(priceChange, '1D');
        const pc1W = pcGet(priceChange, '1W', '5D');
        const pc1M = pcGet(priceChange, '1M');
        const pc3M = pcGet(priceChange, '3M');
        const pc6M = pcGet(priceChange, '6M');
        const pc1Y = pcGet(priceChange, '1Y');
        const pcYTD = pcGet(priceChange, 'YTD', 'ytd');

        fundamentalHtml = `
            <div class="analysis-tab-content" id="tab-fundamente">
                <!-- Market Snapshot (FMP Quote) -->
                <div class="an-fund-panel">
                    <div class="an-fund-panel-head">
                        <h4 class="an-section-title">Market snapshot</h4>
                        <div class="an-fund-note an-num">${escAn(q.symbol || ticker)}</div>
                    </div>
                    ${Object.keys(q || {}).length > 0 ? `
                    <div class="fundamental-grid">
                        <div class="f-card">
                            <div class="f-label">Market cap</div>
                            <div class="f-value">${fmtShort(q.marketCap || qb.marketCap)}</div>
                        </div>
                        <div class="f-card">
                            <div class="f-label">Volume</div>
                            <div class="f-value">${fmtShort(q.volume || qb.volume)}</div>
                        </div>
                        <div class="f-card">
                            <div class="f-label">Avg volume</div>
                            <div class="f-value">${fmtShort(q.averageVolume || q.avgVolume || qb.averageVolume)}</div>
                        </div>
                        <div class="f-card">
                            <div class="f-label">P/E</div>
                            <div class="f-value">${q.pe ? Number(q.pe).toFixed(2) : (qb.pe ? Number(qb.pe).toFixed(2) : 'N/A')}</div>
                        </div>
                        <div class="f-card">
                            <div class="f-label">EPS</div>
                            <div class="f-value">${q.eps ? Number(q.eps).toFixed(2) : (qb.eps ? Number(qb.eps).toFixed(2) : 'N/A')}</div>
                        </div>
                        <div class="f-card">
                            <div class="f-label">52W range</div>
                            <div class="f-value">${q.yearLow ? Number(q.yearLow).toFixed(2) : (qb.yearLow ? Number(qb.yearLow).toFixed(2) : 'N/A')} - ${q.yearHigh ? Number(q.yearHigh).toFixed(2) : (qb.yearHigh ? Number(qb.yearHigh).toFixed(2) : 'N/A')}</div>
                        </div>
                    </div>
                    ` : `<div class="an-fund-empty">No quote data from the fundamentals provider.</div>`}
                </div>

                <!-- Price Performance (FMP stock-price-change) -->
                <div class="an-fund-panel">
                    <h4 class="an-section-title">Price performance</h4>
                    ${Object.keys(priceChange).length > 0 ? `
                    <div class="fundamental-grid">
                        <div class="f-card"><div class="f-label">1D</div><div class="f-value ${pcColor(pc1D)}">${pc(pc1D)}</div></div>
                        <div class="f-card"><div class="f-label">1W</div><div class="f-value ${pcColor(pc1W)}">${pc(pc1W)}</div></div>
                        <div class="f-card"><div class="f-label">1M</div><div class="f-value ${pcColor(pc1M)}">${pc(pc1M)}</div></div>
                        <div class="f-card"><div class="f-label">3M</div><div class="f-value ${pcColor(pc3M)}">${pc(pc3M)}</div></div>
                        <div class="f-card"><div class="f-label">6M</div><div class="f-value ${pcColor(pc6M)}">${pc(pc6M)}</div></div>
                        <div class="f-card"><div class="f-label">1Y</div><div class="f-value ${pcColor(pc1Y)}">${pc(pc1Y)}</div></div>
                        <div class="f-card"><div class="f-label">YTD</div><div class="f-value ${pcColor(pcYTD)}">${pc(pcYTD)}</div></div>
                    </div>
                    ` : `<div class="an-fund-empty">No price-change data available.</div>`}
                </div>

                <!-- Status & Dates -->
                ${f.data_status ? `<div class="an-fund-warning"><i class="fa-solid fa-triangle-exclamation" aria-hidden="true"></i> ${escAn(f.data_note || 'Partial fundamentals loaded.')}</div>` : ''}
                <div class="fundamental-grid">
                    <div class="f-card">
                        <div class="f-label">Next earnings date</div>
                        <div class="f-value">${escAn(nextDateStr)}</div>
                        <div class="f-sub">${nextDateSub !== 'N/A' ? escAn(nextDateSub) : ''}</div>
                    </div>
                </div>

                <!-- Main Metrics Grid -->
                <h4 class="an-section-title">Financial position</h4>
                <div class="fundamental-grid">
                    <div class="f-card">
                        <div class="f-label">Cash &amp; equivalents</div>
                        <div class="f-value">${usdM(bs.cashAndCashEquivalents || bs2.cashAndCashEquivalents)}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Total debt</div>
                        <div class="f-value">${usdM(bs.totalDebt || bs2.totalDebt)}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Free cash flow</div>
                        <div class="f-value">${usdM(cf.freeCashFlow || cfst.freeCashFlow)}</div>
                    </div>
                     <div class="f-card">
                        <div class="f-label">Est. revenue</div>
                        <div class="f-value">${usdM(est.estimatedRevenueAvg)}</div>
                    </div>
                      <div class="f-card">
                          <div class="f-label">Est. EPS (avg)</div>
                          <div class="f-value">${epsAvg !== null ? `$${Number(epsAvg).toFixed(2)}` : 'N/A'}</div>
                          <div class="f-sub">${epsAvg !== null ? `Fiscal ${epsDate}` : 'No forward EPS estimate available for the current period from the data provider.'}</div>
                          ${epsLow !== null && epsHigh !== null ? `<div class="f-sub">Range: ${Number(epsLow).toFixed(2)} - ${Number(epsHigh).toFixed(2)}</div>` : ''}
                      </div>
                </div>

                <!-- Extended Fundamentals -->
                <h4 class="an-section-title">Extended fundamentals</h4>
                <div class="fundamental-grid">
                    <div class="f-card">
                        <div class="f-label">Owner earnings</div>
                        <div class="f-value">${usdShort(safePick(ownerEarnings, ['ownerEarnings', 'ownersEarnings']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Owner EPS</div>
                        <div class="f-value">${safePick(ownerEarnings, ['ownerEarningsPerShare', 'ownersEarningsPerShare', 'ownerEarningsPerShareDiluted']) !== null ? Number(safePick(ownerEarnings, ['ownerEarningsPerShare', 'ownersEarningsPerShare', 'ownerEarningsPerShareDiluted'])).toFixed(2) : 'N/A'}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Enterprise value</div>
                        <div class="f-value">${usdShort(safePick(enterpriseValues, ['enterpriseValue']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">EV / EBITDA</div>
                        <div class="f-value">${safePick(enterpriseValues, ['enterpriseToEbitda', 'evToEbitda', 'enterpriseValueOverEBITDA']) !== null ? Number(safePick(enterpriseValues, ['evToEbitda', 'enterpriseValueOverEBITDA'])).toFixed(2) : 'N/A'}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Revenue growth (YoY)</div>
                        <div class="f-value ${colorPct(safePick(incomeGrowth, ['revenueGrowth', 'growthRevenue']))}">${fmtPct(safePick(incomeGrowth, ['growthRevenue', 'revenueGrowth']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Net income growth (YoY)</div>
                        <div class="f-value ${colorPct(safePick(incomeGrowth, ['earningsGrowth', 'earningsQuarterlyGrowth', 'growthNetIncome', 'netIncomeGrowth']))}">${fmtPct(safePick(incomeGrowth, ['growthNetIncome', 'netIncomeGrowth']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">FCF growth (YoY)</div>
                        <div class="f-value ${colorPct(safePick(cashFlowGrowth, ['growthFreeCashFlow', 'freeCashFlowGrowth']))}">${fmtPct(safePick(cashFlowGrowth, ['growthFreeCashFlow', 'freeCashFlowGrowth']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">EPS growth (YoY)</div>
                        <div class="f-value ${colorPct(safePick(incomeGrowth, ['earningsQuarterlyGrowth', 'earningsGrowth', 'growthEPS', 'growthEps', 'epsGrowth']))}">${fmtPct(safePick(incomeGrowth, ['growthEPS', 'growthEps', 'epsGrowth']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Operating CF (as reported)</div>
                        <div class="f-value">${usdShort(safePick(cashAsReported, ['netCashProvidedByOperatingActivities', 'operatingCashFlow']))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Report date</div>
                        <div class="f-value">${safeText(reportDateObj.date || reportDateObj.date_formatted || reportDateObj.reportDate || reportDateObj.fiscalDateEnding || (reportDateObj.fiscalYear ? `${reportDateObj.period || 'FY'} ${reportDateObj.fiscalYear}` : 'N/A'))}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Financial reports</div>
                        <div class="f-value">${Array.isArray(reportsJson) ? reportsJson.length : 0} items</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Financial growth</div>
                        <div class="f-value ${colorPct(safePick(finGrowth, ['growthRevenue', 'growthNetIncome', 'growthEPS']))}">${fmtPct(safePick(finGrowth, ['growthRevenue', 'growthNetIncome', 'growthEPS']))}</div>
                    </div>
                </div>

                <!-- Income Statement Snapshot -->
                <h4 class="an-section-title">Income statement (latest)</h4>
                <div class="fundamental-grid">
                    <div class="f-card"><div class="f-label">Revenue</div><div class="f-value">${usdM(inc.revenue)}</div></div>
                    <div class="f-card"><div class="f-label">Gross profit</div><div class="f-value">${usdM(inc.grossProfit)}</div></div>
                    <div class="f-card"><div class="f-label">Operating income</div><div class="f-value">${usdM(inc.operatingIncome)}</div></div>
                    <div class="f-card"><div class="f-label">Net income</div><div class="f-value">${usdM(inc.netIncome)}</div></div>
                    <div class="f-card"><div class="f-label">EPS</div><div class="f-value">${inc.eps ? Number(inc.eps).toFixed(2) : 'N/A'}</div></div>
                    <div class="f-card"><div class="f-label">EBITDA</div><div class="f-value">${usdM(inc.ebitda)}</div></div>
                </div>

                <!-- EOD Snapshot -->
                <h4 class="an-section-title">EOD snapshot</h4>
                <div class="fundamental-grid">
                    <div class="f-card"><div class="f-label">Last close</div><div class="f-value">${eodLight[0] && eodLight[0].close ? `$${Number(eodLight[0].close).toFixed(2)}` : 'N/A'}</div></div>
                    <div class="f-card"><div class="f-label">Last volume</div><div class="f-value">${eodLight[0] && eodLight[0].volume ? fmtShort(eodLight[0].volume) : 'N/A'}</div></div>
                    <div class="f-card"><div class="f-label">EOD points</div><div class="f-value">${eodFull.length || eodLight.length || 0}</div></div>
                </div>

                <!-- Growth Section -->
                ${growth ? `
                <h4 class="an-section-title">Growth metrics (YoY)</h4>
                <div class="fundamental-grid">
                     <div class="f-card">
                        <div class="f-label">Cash growth</div>
                        <div class="f-value ${colorPct(growth.growthCashAndCashEquivalents)}">${fmtPct(growth.growthCashAndCashEquivalents)}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Debt growth</div>
                        <div class="f-value ${colorDebt(growth.growthTotalDebt)}">${fmtPct(growth.growthTotalDebt)}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Asset growth</div>
                        <div class="f-value ${colorPct(growth.growthTotalAssets)}">${fmtPct(growth.growthTotalAssets)}</div>
                    </div>
                    <div class="f-card">
                        <div class="f-label">Receivables growth</div>
                        <div class="f-value ${colorPct(growth.growthNetReceivables)}">${fmtPct(growth.growthNetReceivables)}</div>
                    </div>
                </div>` : ''}

                <!-- As Reported Section -->
                <div class="an-fund-panel">
                    <h4 class="an-section-title">As reported (latest)</h4>
                    <div class="an-fund-text">
                        ${((f.as_reported || []).length > 0)
                ? (f.as_reported || []).slice(0, 3).map(r => {
                    const label = safeText(r.period || r.fiscalDate || r.calendarYear);
                    const assets = r.totalAssets ?? r.assets ?? r.totalAssets;
                    const liab = r.totalLiabilities ?? r.liabilities ?? r.totalLiabilities;
                    return `- <strong>${escAn(label)}</strong>: Assets ${usdM(assets)}, Liabilities ${usdM(liab)}`;
                }).join('<br>')
                : '<span class="an-fund-empty">No as-reported data for this ticker from the fundamentals provider.</span>'}
                    </div>
                </div>
            </div>
        `;
    } else {
        fundamentalHtml = `
            <div class="analysis-tab-content" id="tab-fundamente">
                <div class="an-fund-empty an-fund-empty--block">
                    No fundamentals data available.
                </div>
            </div>
        `;
    }

    // AI TAB CONTENT
    const aiObject = (a && a.ai_analysis && typeof a.ai_analysis === 'object' && !Array.isArray(a.ai_analysis))
        ? a.ai_analysis
        : null;
    const aiText = (a && typeof a.ai_analysis === 'string') ? a.ai_analysis : '';

    let aiHtml = '';
    if (a && Object.prototype.hasOwnProperty.call(a, 'ai_analysis')) {
        if (aiObject) {
            // Everything below is model output (and may quote news text): escape it all.
            const aiProv = Actions.analysisAiProvenance(aiObject, a.model);
            const aiLine = (x) => `<li>${escAn(x)}</li>`;
            const aiList = (items) => items.length ? `<ul class="an-ai-list">${items.map(aiLine).join('')}</ul>` : '<div class="an-ai-unknown">unknown</div>';
            const aiChip = aiProv.isFallback ? 'ds-chip' : 'ds-chip ds-chip--ai';
            const aiNotice = aiProv.isFallback
                ? `<div id="analysis-ai-fallback-notice" class="an-notice an-notice--warn">
                        <strong>Not an AI answer.</strong> ${escAn(aiProv.notice)}
                        ${aiProv.missing.length ? `<div>Inputs unavailable: ${escAn(aiProv.missing.join(', '))}.</div>` : ''}
                   </div>`
                : ((aiProv.ungrounded && aiProv.ungrounded.length) || aiProv.missing.length)
                    ? `<div id="analysis-ai-data-notice" class="an-notice">
                        ${(aiProv.ungrounded && aiProv.ungrounded.length) ? `<div><strong>Figures not found in the data given to the model:</strong> ${escAn(aiProv.ungrounded.join(', '))}. They are the model's own thresholds or estimates, not market data.</div>` : ''}
                        ${aiProv.missing.length ? `<div><strong>Inputs that were unavailable when the model was asked:</strong> ${escAn(aiProv.missing.join(', '))}.</div>` : ''}
                       </div>`
                    : '';
            const newsSummary = aiObject.news_summary || {};
            const scenario = aiObject.scenario || {};
            const tradePlan = aiObject.trade_plan || {};
            const keyDrivers = Array.isArray(aiObject.key_drivers) ? aiObject.key_drivers : [];
            const risks = Array.isArray(aiObject.risks) ? aiObject.risks : [];
            const newsPos = Array.isArray(newsSummary.last_7d_positive) ? newsSummary.last_7d_positive : [];
            const newsNeg = Array.isArray(newsSummary.last_7d_negative) ? newsSummary.last_7d_negative : [];
            const riskEvents = Array.isArray(newsSummary.major_risk_events) ? newsSummary.major_risk_events : [];

            aiHtml = `
                <div class="analysis-tab-content" id="tab-ai-ollama">
                    <div class="ai-analysis-block ${aiProv.isFallback ? 'is-rules' : 'is-model'}">
                        <div class="ai-header">
                            <div class="ai-badge ${aiChip}" id="analysis-ai-source-badge">${escAn(aiProv.badge)}</div>
                            <div class="an-ai-chips">
                                <span class="${aiChip}">Sentiment: ${escAn(String(aiObject.sentiment || 'neutral').toLowerCase())}</span>
                                <span class="${aiChip}">Earnings play: ${escAn(String(aiObject.earnings_play || 'WAIT').toLowerCase())}</span>
                                <span class="${aiChip}" id="analysis-ai-confidence" title="Self-reported by the model and never checked against outcomes. It is not the probability that a trade wins.">${escAn(aiProv.confidenceLabel)}</span>
                            </div>
                        </div>
                        <div class="ai-content">
                            ${aiNotice}
                            ${snapshotText ? `<div class="an-ai-snapshot">Written from the data of this snapshot (${escAn(snapshotText)}); it does not update with the market.</div>` : ''}
                            <div class="an-ai-grid">
                                <div class="an-ai-group"><div class="ds-label">Key drivers</div>${aiList(keyDrivers)}</div>
                                <div class="an-ai-group"><div class="ds-label">Risks</div>${aiList(risks)}</div>
                                <div class="an-ai-group"><div class="ds-label">News, last 7 days, positive</div>${aiList(newsPos)}</div>
                                <div class="an-ai-group"><div class="ds-label">News, last 7 days, negative</div>${aiList(newsNeg)}</div>
                                <div class="an-ai-group"><div class="ds-label">Theme, last 30 days</div><div class="an-ai-text">${escAn(newsSummary.last_30d_theme || 'unknown')}</div></div>
                                <div class="an-ai-group"><div class="ds-label">Major risk events</div>${aiList(riskEvents)}</div>
                                <div class="an-ai-group"><div class="ds-label">Scenario</div>
                                    <dl class="an-ai-dl">
                                        <dt>Bull</dt><dd>${escAn(scenario.bull_case || 'unknown')}</dd>
                                        <dt>Base</dt><dd>${escAn(scenario.base_case || 'unknown')}</dd>
                                        <dt>Bear</dt><dd>${escAn(scenario.bear_case || 'unknown')}</dd>
                                    </dl>
                                </div>
                                <div class="an-ai-group"><div class="ds-label">Trade plan</div>
                                    <dl class="an-ai-dl">
                                        <dt>Direction</dt><dd>${escAn(tradePlan.direction || 'NONE')}</dd>
                                        <dt>Entry</dt><dd>${escAn(tradePlan.entry_condition || 'unknown')}</dd>
                                        <dt>Invalidations</dt><dd>${escAn(tradePlan.invalidations || 'unknown')}</dd>
                                        <dt>TP logic</dt><dd>${escAn(tradePlan.tp_logic || 'unknown')}</dd>
                                        <dt>Notes</dt><dd>${escAn(tradePlan.notes || 'unknown')}</dd>
                                    </dl>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            `;
        } else if (aiText) {
            const aiParagraphs = aiText.split('\n').map(p => p.trim()).filter(Boolean);
            const aiIdeasHtml = aiParagraphs.length
                ? aiParagraphs.map(p => {
                    const encoded = encodeURIComponent(p).replace(/'/g, "%27");
                    return `
                        <div class="ai-idea-row">
                            <p>${escAn(p)}</p>
                            <button class="ds-btn ds-btn--sm ai-idea-btn" onclick="Actions.saveAiIdeaToCarnet('${ticker}', '${encoded}')">
                                <i class="fa-solid fa-book-bookmark" aria-hidden="true"></i> Add to notebook
                            </button>
                        </div>
                    `;
                }).join('')
                : '<p>No AI analysis available for this ticker.</p>';

            aiHtml = `
                <div class="analysis-tab-content" id="tab-ai-ollama">
                    <div class="ai-analysis-block is-model">
                        <div class="ai-header">
                            <div class="ai-badge ds-chip ds-chip--ai">${escAn(a.model || 'Ollama AI')}</div>
                            <div class="an-ai-snapshot">${escAn(snapshotText ? `AI text, ${snapshotText}` : 'AI text')}</div>
                        </div>
                        <div class="ai-content">
                            ${aiIdeasHtml}
                        </div>
                    </div>
                </div>
            `;
        } else {
            aiHtml = `
                <div class="analysis-tab-content" id="tab-ai-ollama">
                    <div class="ai-analysis-block is-none">
                        <div class="ai-header">
                            <div class="ai-badge ds-chip ds-chip--warn">AI unavailable</div>
                            <div class="an-ai-snapshot">No AI answer for this analysis</div>
                        </div>
                        <div class="ai-content">
                            <p>No AI analysis available for this ticker. The Technical tab is computed from market data and does not depend on the AI.</p>
                        </div>
                    </div>
                </div>
            `;
        }
    }
    // CARNET TAB CONTENT
    let carnetHtml = '';
    const entriesRaw = UI.parseNotebookNotes(a.strategy_notes);
    const entries = (entriesRaw || []).slice().sort((a, b) => new Date(b.date) - new Date(a.date));
    if (entries && entries.length > 0) {
        carnetHtml = `
            <div class="analysis-tab-content" id="tab-carnet">
                <div class="an-notebook-head">
                    <button class="ds-btn ds-btn--sm" onclick="Actions.openStrategyModal('${ticker}')"><i class="fa-solid fa-pen-to-square" aria-hidden="true"></i> Edit notebook</button>
                </div>
                <div class="mini-notebook-list">
                    ${entries.map((e, idx) => {
            const type = (e.type || 'NOTE').toUpperCase();
            const typeClass = type.toLowerCase();
            const dateStr = e.date ? UI._fmtDateTime(e.date, 'date') : '';
            const closedAtRaw = e.closed_at || e.closedAt || e.closed_time || '';
            const closedAtStr = closedAtRaw ? UI._fmtDateTime(closedAtRaw) : '';
            const pnlClass = (e.pnl || '').includes('-') ? 'text-red' : 'text-green';
            const statusBadge = e.status === 'WIN'
                ? '<span class="badge-outcome badge-win ds-chip ds-chip--pos">Win</span>'
                : e.status === 'LOSS'
                    ? '<span class="badge-outcome badge-loss ds-chip ds-chip--neg">Loss</span>'
                    : '';
            const tradeMeta = (type === 'LONG' || type === 'SHORT') ? `
                            <div class="an-note-meta">
                                ${e.entry ? `<div><strong>Entry:</strong> ${e.entry}</div>` : ''}
                                ${e.exit ? `<div><strong>Exit:</strong> ${e.exit}</div>` : ''}
                                ${e.pnl ? `<div><strong title="Profit and Loss">PnL:</strong> <span class="${pnlClass}">${e.pnl}</span></div>` : ''}
                                ${closedAtStr ? `<div><strong>Closed:</strong> ${closedAtStr}</div>` : ''}
                            </div>
                        ` : '';
            return `
                        <div class="mini-card mini-card--${typeClass}">
                            <div class="mini-card-header">
                                <span class="an-note-tags"><span class="note-type-badge note-type-${typeClass}">${type.charAt(0) + type.slice(1).toLowerCase()}</span>${statusBadge}</span>
                                <div class="an-note-side">
                                    <span class="note-date">${dateStr}</span>
                                    <button class="ds-btn ds-btn--sm ds-btn--ghost" aria-label="Edit this note" title="Edit this note" onclick="Actions.openStrategyModal('${ticker}', ${idx})"><i class="fa-solid fa-pen" aria-hidden="true"></i></button>
                                </div>
                            </div>
                            <div class="note-content">${e.description || ''}</div>
                            ${tradeMeta}
                        </div>
                    `;
        }).join('')}
                </div>
            </div>
        `;
    } else {
        carnetHtml = `
            <div class="analysis-tab-content" id="tab-carnet">
                <div class="ds-empty">
                    <p>No saved notes for ${ticker}.</p>
                    <button class="ds-btn ds-btn--sm" onclick="Actions.openStrategyModal('${ticker}')"><i class="fa-solid fa-plus" aria-hidden="true"></i> Add a note</button>
                </div>
            </div>
        `;
    }

    body.innerHTML = technicalHtml + fundamentalHtml + aiHtml + carnetHtml;

    modal.classList.remove('hidden');
    modal.style.display = 'flex';
};

Actions.switchAnalysisTab = function (tabId) {
    // Buttons
    document.querySelectorAll('.analysis-tab-btn').forEach(btn => {
        // Use data-tab attribute for robust matching
        const target = btn.getAttribute('data-tab');
        btn.classList.toggle('active', target === tabId);
    });
    // Content
    document.querySelectorAll('.analysis-tab-content').forEach(content => {
        content.classList.toggle('active', content.id === `tab-${tabId}`);
    });
};

Actions.closeAnalysisModal = function () {
    const modal = document.getElementById('analysis-modal');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
};

// --- Smart Alerts UI ---
UI.showAddAlertModal = function () {
    const modal = document.getElementById('modal-add-alert');
    if (modal) {
        modal.classList.remove('hidden');
        modal.style.display = 'flex';
    }
    // The target label must match the selected type: VOLATILITY takes a
    // percent threshold, price alerts take dollars (audit 2026-09-05).
    const typeSelect = document.getElementById('alert-type');
    const label = document.getElementById('alert-target-label');
    if (typeSelect && label && !typeSelect.dataset.labelBound) {
        typeSelect.dataset.labelBound = '1';
        const syncLabel = () => {
            // VOLATILITY compares the size of the day's move (24h for crypto),
            // up or down, with the threshold — say so instead of "spike".
            label.textContent = typeSelect.value === 'VOLATILITY' ? 'Daily move threshold (%, up or down)' : 'Target price ($)';
        };
        typeSelect.addEventListener('change', syncLabel);
        syncLabel();
    }
};

UI.hideAddAlertModal = function () {
    const modal = document.getElementById('modal-add-alert');
    if (modal) {
        modal.classList.add('hidden');
        modal.style.display = 'none';
    }
};

UI.renderAlerts = async function (state) {
    const container = document.getElementById('alerts-list-container');
    if (!container) return;

    try {
        const alerts = await API.getAlerts();
        if (!Array.isArray(alerts) || alerts.length === 0) {
            container.innerHTML = '<div class="alerts-state alerts-state--empty"><strong>No alerts yet.</strong><p>Create one to be notified when a price or daily move is reached.</p><button type="button" class="btn-secondary" onclick="UI.showAddAlertModal()">Create alert</button></div>';
            return;
        }
        const esc = UI._escapeHtml;
        // Ids are generated server-side, but they come back from a file — keep
        // only characters that cannot break out of the inline onclick string.
        const safeId = (id) => String(id || '').replace(/[^A-Za-z0-9_\-]/g, '');
        // "Triggered/Off" hid whether an alert fired or was paused by hand.
        const statusOf = (a) => {
            if (a.active) return { cls: 'active', text: 'Active', sub: '' };
            if (a.triggered_at) {
                const when = new Date(a.triggered_at);
                const whenText = Number.isNaN(when.getTime()) ? '' : when.toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
                const price = Number(a.triggered_price);
                return {
                    cls: 'triggered',
                    text: 'Triggered',
                    sub: `${whenText}${Number.isFinite(price) ? ' @ ' + UI.formatPrice(price) : ''}`.trim(),
                };
            }
            return { cls: 'off', text: 'Off', sub: 'paused, or fired before trigger times were recorded' };
        };

        container.innerHTML = `
        <div class="premium-table-container">
            <table class="premium-table">
                <thead>
                    <tr>
                        <th>Ticker</th>
                        <th>Type</th>
                        <th class="num">Target</th>
                        <th>Status</th>
                        <th class="alerts-col-actions">Actions</th>
                    </tr>
                </thead>
                <tbody>
                    ${alerts.map(a => {
                        const st = statusOf(a);
                        const typeLabel = a.type === 'PRICE_UP' ? 'Price crosses up'
                            : (a.type === 'PRICE_DOWN' ? 'Price crosses down'
                                : (a.type === 'VOLATILITY' ? 'Daily move (up or down)' : String(a.type || '').replace(/_/g, ' ')));
                        return `
                            <tr>
                                <td class="alerts-ticker">${esc(a.ticker)}</td>
                                <td>${esc(typeLabel)}</td>
                                <td class="num">${(a.type === 'VOLATILITY' || a.type === 'VOLATILITY_UP' || a.type === 'VOLATILITY_DOWN' || String(a.type || '').includes('PCT') || String(a.type || '').includes('PERCENT')) ? esc(UI.formatPrice(a.target)) + '%' : '$' + esc(UI.formatPrice(a.target))}</td>
                                <td>
                                    <span class="alert-status alert-status--${st.cls}">
                                        ${esc(st.text)}
                                    </span>
                                    ${st.sub ? `<span class="alert-status-sub alert-status-sub--${st.cls}">${esc(st.sub)}</span>` : ''}
                                </td>
                                <td class="alerts-col-actions">
                                    <div class="alerts-actions">
                                        <button class="btn-mini alert-act${a.active ? ' is-on' : ''}" onclick="Actions.toggleAlert('${safeId(a.id)}')" title="${a.active ? 'Pause this alert' : 'Re-arm this alert'}" aria-label="${a.active ? 'Pause this alert' : 'Re-arm this alert'}">
                                            <i class="fa-solid ${a.active ? 'fa-toggle-on' : 'fa-toggle-off'}" aria-hidden="true"></i>
                                        </button>
                                        <button class="btn-mini alert-act alert-act--delete" onclick="Actions.deleteAlert('${safeId(a.id)}')" title="Delete" aria-label="Delete this alert">
                                            <i class="fa-solid fa-trash" aria-hidden="true"></i>
                                        </button>
                                    </div>
                                </td>
                            </tr>
                        `; }).join('')}
                </tbody>
            </table>
            </div>
        `;
    } catch (e) {
        console.error("Alerts render error:", e);
        container.innerHTML = '<div class="alerts-state alerts-state--error"><strong>Failed to load alerts</strong><p>Your saved alerts are not shown; they were not deleted.</p><button type="button" class="btn-secondary" onclick="UI.renderAlerts()">Retry</button></div>';
    }
};

// --- Telegram Delivery card (Alerts tab) ---
UI.loadTelegramDelivery = async function () {
    const ids = ['tg-enabled', 'tg-token', 'tg-chat-id', 'tg-route-news', 'tg-route-signals', 'tg-route-capital', 'tg-route-alerts'];
    if (ids.some(id => !document.getElementById(id))) return;
    try {
        const s = await API.getTelegramSettings();
        document.getElementById('tg-enabled').checked = !!s.enabled;
        document.getElementById('tg-chat-id').value = s.chat_id || '';
        const tokenInput = document.getElementById('tg-token');
        tokenInput.value = '';
        tokenInput.placeholder = s.bot_token_masked ? `stored (${s.bot_token_masked}) — leave empty to keep` : '123456:ABC-DEF…';
        const routes = s.routes || {};
        document.getElementById('tg-route-news').checked = routes.news !== false;
        document.getElementById('tg-route-signals').checked = routes.signals !== false;
        document.getElementById('tg-route-capital').checked = routes.capital !== false;
        document.getElementById('tg-route-alerts').checked = routes.alerts !== false;
        const badge = document.getElementById('tg-state-badge');
        if (badge) {
            // "Active" used to mean only "checkbox ticked + fields filled".
            // The server now reports whether the last real send with this
            // token + chat id worked (delivery_state), and the badge follows.
            const last = s.last_delivery || null;
            const fmtWhen = (iso) => {
                const d = iso ? new Date(iso) : null;
                return d && !Number.isNaN(d.getTime())
                    ? d.toLocaleString('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })
                    : '';
            };
            const state = s.delivery_state || (s.enabled && s.configured ? 'unverified' : (s.configured ? 'off' : 'not_configured'));
            if (state === 'ok') {
                badge.textContent = `● Active — last delivery OK ${fmtWhen(last && last.at)}`.trim();
                badge.title = 'The last message sent with this bot token and chat id was accepted by Telegram.';
                badge.className = 'tg-state tg-state--ok';
            } else if (state === 'failing') {
                badge.textContent = `● Delivery failing — ${(last && last.detail) || 'last send was rejected'}`;
                badge.title = `Last attempt ${fmtWhen(last && last.at)}. Check the bot token and chat id, then send a test message.`;
                badge.className = 'tg-state tg-state--failing';
            } else if (state === 'unverified') {
                badge.textContent = '● Enabled — not verified yet';
                badge.title = 'No message has been sent with this bot token and chat id yet. Use "Send test message" to confirm delivery works.';
                badge.className = 'tg-state tg-state--unverified';
            } else if (s.configured) {
                badge.textContent = '● Configured — off';
                badge.className = 'tg-state tg-state--off';
            } else {
                badge.textContent = '● Not configured';
                badge.className = 'tg-state tg-state--none';
            }
        }
    } catch (e) {
        const status = document.getElementById('tg-status');
        if (status) status.textContent = 'Could not load Telegram settings.';
    }
};

Actions.saveTelegramDelivery = async function () {
    const status = document.getElementById('tg-status');
    const saveBtn = document.getElementById('tg-save-btn');
    try {
        if (saveBtn) saveBtn.disabled = true;
        if (status) status.textContent = 'Saving…';
        const payload = {
            enabled: document.getElementById('tg-enabled').checked,
            chat_id: document.getElementById('tg-chat-id').value.trim(),
            routes: {
                news: document.getElementById('tg-route-news').checked,
                signals: document.getElementById('tg-route-signals').checked,
                capital: document.getElementById('tg-route-capital').checked,
                alerts: document.getElementById('tg-route-alerts').checked
            }
        };
        const token = document.getElementById('tg-token').value.trim();
        if (token) payload.bot_token = token; // empty = keep stored token
        const result = await API.saveTelegramSettings(payload);
        const s = (result && result.settings) || {};
        if (status) {
            // Ticking "Enable" without a token or chat id saves, but nothing
            // can be delivered — say that instead of a plain green "Saved.".
            const wantsOn = !!payload.enabled;
            if (wantsOn && !s.enabled) {
                status.textContent = `Saved, but delivery is NOT active: ${!s.has_token && !s.bot_token_masked ? 'bot token' : 'chat id'} is missing.`;
                status.style.color = 'var(--ds-neg, #b3413f)';
            } else {
                status.textContent = s.enabled
                    ? (s.verified ? 'Saved — delivery active.' : 'Saved — delivery enabled. Send a test message to verify it works.')
                    : 'Saved — delivery is off.';
                status.style.color = 'var(--ds-pos, #1c7c4c)';
            }
        }
        UI.loadTelegramDelivery();
        return true;
    } catch (e) {
        if (status) {
            status.textContent = `Save failed: ${e.message}`;
            status.style.color = 'var(--ds-neg, #b3413f)';
        }
        return false;
    } finally {
        if (saveBtn) saveBtn.disabled = false;
        // One shared timer: the save's 6 s timer used to wipe the result of a
        // test message that was still on screen.
        clearTimeout(Actions._tgStatusTimer);
        Actions._tgStatusTimer = setTimeout(() => { const el = document.getElementById('tg-status'); if (el) el.textContent = ''; }, 8000);
    }
};

Actions.testTelegramDelivery = async function () {
    const status = document.getElementById('tg-status');
    const testBtn = document.getElementById('tg-test-btn');
    try {
        if (testBtn) testBtn.disabled = true;
        if (status) status.textContent = 'Sending test…';
        // Persist current form first so the test uses what the owner sees. If
        // the save is rejected, stop: testing would use the OLD stored values
        // and could report success for settings that were never saved.
        const saved = await Actions.saveTelegramDelivery();
        if (!saved) return;
        if (status) { status.textContent = 'Sending test…'; status.style.color = ''; }
        const result = await API.testTelegram();
        if (status) {
            status.textContent = result.status === 'ok'
                ? 'Test message sent — check your Telegram.'
                : `Test failed: ${result.detail || 'no reason given'}`;
            status.style.color = result.status === 'ok' ? 'var(--ds-pos, #1c7c4c)' : 'var(--ds-neg, #b3413f)';
        }
        UI.loadTelegramDelivery(); // badge reflects the verified/failing result
    } catch (e) {
        if (status) {
            status.textContent = `Test failed: ${e.message}`;
            status.style.color = 'var(--ds-neg, #b3413f)';
        }
    } finally {
        if (testBtn) testBtn.disabled = false;
        clearTimeout(Actions._tgStatusTimer);
        Actions._tgStatusTimer = setTimeout(() => { const el = document.getElementById('tg-status'); if (el) el.textContent = ''; }, 10000);
    }
};

// --- Smart Alerts Actions ---
Actions.saveAlert = async function () {
    const tickerInput = document.getElementById('alert-ticker');
    const targetInput = document.getElementById('alert-target');
    const typeInput = document.getElementById('alert-type');

    const ticker = tickerInput.value.trim().toUpperCase();
    const type = typeInput.value;
    const target = targetInput.value;

    if (!ticker || !target) {
        UI.showToast("Please enter ticker and target value", "error");
        return;
    }
    // A zero/negative/non-numeric target can never be a valid price or
    // percent threshold; it used to be sent and stored as an "Active" alert.
    const targetNum = Number(target);
    if (!Number.isFinite(targetNum) || targetNum <= 0) {
        UI.showToast(type === 'VOLATILITY' ? "Threshold must be a positive percent" : "Target price must be a positive number", "error");
        return;
    }

    try {
        UI.showToast("Saving alert...", "info");
        await API.addAlert(ticker, type, targetNum);
        UI.showToast("Alert created successfully!", "success");
        UI.hideAddAlertModal();
        tickerInput.value = '';
        targetInput.value = '';

        // Refresh view if on alerts page (renderAlerts fetches alerts directly)
        if (ViewRouter.activeView === 'alerts') {
            UI.renderAlerts();
        }
    } catch (e) {
        console.error("Save alert error:", e);
        UI.showToast((e && e.message) ? e.message : "Failed to save alert", "error");
    }
};

Actions.toggleAlert = async function (alertId) {
    try {
        await API.toggleAlert(alertId);
        UI.renderAlerts();
    } catch (e) {
        console.error("Toggle alert error:", e);
        UI.showToast("Failed to toggle alert", "error");
    }
};

Actions.deleteAlert = async function (alertId) {
    if (!confirm("Are you sure you want to delete this alert?")) return;
    try {
        await API.deleteAlert(alertId);
        UI.renderAlerts();
        UI.showToast("Alert deleted", "success");
    } catch (e) {
        console.error("Delete alert error:", e);
        UI.showToast("Failed to delete alert", "error");
    }
};

Actions.resetCapital = async function (amount) {
    const numericAmount = Number(amount);
    if (!Number.isFinite(numericAmount) || numericAmount <= 0) {
        UI.showToast('Please enter a valid positive amount.', 'error');
        return;
    }
    const input = document.getElementById('capital-reset-amount');
    if (input) input.value = String(numericAmount);
    await Actions.submitCapitalReset();
};

Actions.submitCapitalReset = async function () {
    const input = document.getElementById('capital-reset-amount');
    const rawValue = String(input?.value || '').trim().replace(',', '.');
    const amount = Number(rawValue);
    if (!Number.isFinite(amount) || amount <= 0) {
        UI.showToast('Please enter a valid positive amount.', 'error');
        return;
    }

    try {
        const res = await fetch(`${API.BASE_URL}/capital/reset`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ amount: amount, reason: "Manual Reset via UI" })
        });
        let payload = {};
        try { payload = await res.json(); } catch (_) { payload = {}; }

          if (res.ok) {
              UI.showToast('Capital reset successfully.', 'success');

              const newBalance = Number(payload?.balance);
              const responseHistory = Array.isArray(payload?.history) ? payload.history : [];
              const responsePositions = Array.isArray(payload?.positions) ? payload.positions : [];
              if (Number.isFinite(newBalance)) {
                  UI._capitalExplainabilitySelection = { type: '', id: '' };
                  if (!cachedState || typeof cachedState !== 'object') cachedState = {};
                  if (!cachedState.capital || typeof cachedState.capital !== 'object') {
                      cachedState.capital = { balance: newBalance, history: responseHistory, positions: responsePositions };
                  } else {
                      cachedState.capital.balance = newBalance;
                      cachedState.capital.history = responseHistory;
                      cachedState.capital.positions = responsePositions;
                  }
                  UI.renderCapital(cachedState.capital);
                  await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);
              }

            // Refresh lightweight state in background to sync history, but do not fail reset toast on refresh errors
            try {
                const state = await API.getState({ includeNews: false, includeHotlist: false, hotlistDetails: false, lean: false, include: 'capital', unchanged: false, livePrices: false });
                  if (state && state.capital) {
                      cachedState = UI.mergeStatePreserveDetails(cachedState, state);
                      UI.renderCapital(state.capital);
                  }
              } catch (stateErr) {
                  console.warn('Capital reset succeeded but state refresh failed:', stateErr);
              }
              await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);

              // Close modal
              const modal = document.getElementById('capital-reset-modal');
              if (modal) modal.classList.add('hidden');
        } else {
            const detail = (payload && payload.detail)
                ? (typeof payload.detail === 'string' ? payload.detail : JSON.stringify(payload.detail))
                : `HTTP ${res.status}`;
            UI.showToast(`Failed to reset capital: ${detail}`, 'error');
        }
    } catch (e) {
        console.error('Capital reset error:', e);
        UI.showToast('Error resetting capital.', 'error');
    }
};

Actions.submitCapitalPaperOrder = async function (order, options = {}) {
    const ticker = String(order?.ticker || '').trim().toUpperCase();
    const direction = String(order?.direction || 'long').trim().toLowerCase();
    const leverage = Number(order?.leverage || 1);
    const usdSize = Number(order?.usd_size || 0);
    const stopLossPct = Number(order?.stop_loss_pct || 0);
    const takeProfitPct = Number(order?.take_profit_pct || 0);
    const percentagesAreDecimal = options.percentagesAreDecimal === true;

    const validationError = !ticker ? 'Ticker is required.'
        : !['long', 'short'].includes(direction) ? 'Direction must be LONG or SHORT.'
        : (!Number.isFinite(usdSize) || usdSize <= 0) ? 'Size must be a positive number.'
        : (!Number.isInteger(leverage) || leverage < 1 || leverage > 5) ? 'Leverage must be between 1 and 5.'
        : (!Number.isFinite(stopLossPct) || stopLossPct <= 0) ? 'Stop % must be positive.'
        : (!Number.isFinite(takeProfitPct) || takeProfitPct <= 0) ? 'Target % must be positive.'
        : '';
    if (validationError) {
        UI.showToast(validationError, 'error');
        return null;
    }

    try {
        const data = await API.openCapitalPosition({
            ticker,
            direction,
            leverage,
            usd_size: usdSize,
            stop_loss_pct: percentagesAreDecimal ? stopLossPct : stopLossPct / 100,
            take_profit_pct: percentagesAreDecimal ? takeProfitPct : takeProfitPct / 100,
            reason: String(order?.reason || '').trim() || 'Manual chart terminal order',
            strategy_type: String(order?.strategy_type || 'MANUAL_CHART')
        });
        if (!cachedState || typeof cachedState !== 'object') cachedState = {};
        const openedPositionId = String(data?.position?.position_id || '');
        if (openedPositionId) UI._capitalExplainabilitySelection = { type: 'position', id: openedPositionId };
        cachedState.capital = {
            ...(cachedState.capital || {}),
            balance: Number(data.balance || 0),
            positions: Array.isArray(data.positions) ? data.positions : [],
            history: Array.isArray(data.history) ? data.history : []
        };
        UI.renderCapital(cachedState.capital);
        await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);
        UI.showToast(`${ticker} ${direction.toUpperCase()} paper position opened.`, 'success');
        try { AudioSystem.playSignalSound(); } catch (e) {}
        try { UI.flashCapitalTab(); } catch (e) {}
        window.dispatchEvent(new CustomEvent('capital:position-opened', { detail: data.position || {} }));
        return data;
    } catch (e) {
        UI.showToast(String(e?.message || 'Failed to open position.'), 'error');
        return null;
    }
};

Actions.openCapitalPosition = async function () {
    const data = await Actions.submitCapitalPaperOrder({
        ticker: document.getElementById('capital-open-ticker')?.value,
        direction: document.getElementById('capital-open-direction')?.value,
        leverage: document.getElementById('capital-open-leverage')?.value,
        usd_size: document.getElementById('capital-open-size')?.value,
        stop_loss_pct: document.getElementById('capital-open-stop-pct')?.value,
        take_profit_pct: document.getElementById('capital-open-target-pct')?.value,
        reason: document.getElementById('capital-open-reason')?.value,
        strategy_type: 'MANUAL_TERMINAL'
    });
    if (data) {
        document.getElementById('capital-open-ticker').value = '';
        document.getElementById('capital-open-reason').value = '';
    }
    return data;
};

// What a reset destroys, in numbers, shown inside the reset dialog before the
// owner confirms. A reset removes every position (open ones are deleted, not
// closed), the stored closed-trade record and the equity curve.
UI._capitalResetImpactText = function (capital) {
    const data = capital && typeof capital === 'object' ? capital : {};
    const positions = Array.isArray(data.positions) ? data.positions : [];
    const open = positions.filter((position) => String(position?.status || '').toUpperCase() === 'OPEN').length;
    const closed = Number(data.win_rate_summary?.trades ?? data.total_closed_trades ?? 0) || 0;
    const openText = open > 0
        ? `${open} open position${open === 1 ? '' : 's'} (deleted without being closed; unrealized P&L is discarded)`
        : 'no open positions';
    const closedText = closed > 0
        ? `the stored record of ${closed} closed trade${closed === 1 ? '' : 's'} (win rate and track record restart from zero)`
        : 'the closed-trade record';
    return `This cannot be undone. A reset deletes ${openText}, ${closedText} and the equity curve.`;
};

Actions.openCapitalResetModal = function () {
    const modal = document.getElementById('capital-reset-modal');
    if (!modal) return;
    const impact = document.getElementById('capital-reset-impact');
    if (impact) impact.textContent = UI._capitalResetImpactText(cachedState?.capital);
    modal.classList.remove('hidden');
};

UI.refreshCapitalReconciliation = async function ({ force = false } = {}) {
    const container = document.getElementById('capital-reconciliation-banner');
    if (!container) return null;
    const now = Date.now();
    if (!force && UI._capitalReconciliationAt && (now - UI._capitalReconciliationAt) < 60000) {
        return UI._capitalReconciliation || null;
    }
    UI._capitalReconciliationAt = now;
    try {
        const response = await API.fetchWithTimeout(`${API.BASE_URL}/execution/control`, { timeout: 15000 });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        const payload = await response.json();
        UI._capitalReconciliation = payload?.reconciliation || null;
        container.innerHTML = UI._capitalReconciliationHtml(UI._capitalReconciliation);
        return UI._capitalReconciliation;
    } catch (error) {
        // Unknown is not healthy: keep whatever is shown rather than clearing a conflict.
        console.warn('Paper reconciliation status unavailable:', error);
        return null;
    }
};

// Owner repair for a FILLED open order whose Capital position never became
// durable. Audit event only: the server changes no cash and no position, and
// refuses when the position exists or Capital history shows the fill moved cash.
Actions.rollbackOrphanedFill = async function (orderIntentId) {
    const id = String(orderIntentId || '').trim();
    if (!id) return null;
    const details = Array.isArray(UI._capitalReconciliation?.conflict_details) ? UI._capitalReconciliation.conflict_details : [];
    const conflict = details.find((item) => String(item?.order_intent_id || '') === id);
    const reason = window.prompt(
        `${conflict?.message || `Order ${id}`}\n\n`
        + 'Recording a rollback adds an audit event to the order ledger stating that this fill never became durable in Capital. '
        + 'It does not change Capital cash or positions, and the server refuses it if the position exists or the fill moved cash.\n\n'
        + 'Reason to record (at least 10 characters), or Cancel:',
        'Fill never persisted to Capital: no position and no OPEN_POSITION cash debit exist'
    );
    if (reason === null) return null;
    const text = String(reason).trim();
    if (text.length < 10) {
        UI.showToast('A reason of at least 10 characters is required.', 'error');
        return null;
    }
    try {
        const response = await API.fetchWithTimeout(`${API.BASE_URL}/execution/reconcile/rollback-orphaned-fill`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ order_intent_id: id, reason: text }),
            timeout: 20000,
            bypassCooldown: true,
        });
        let payload = {};
        try { payload = await response.json(); } catch (_) { payload = {}; }
        if (!response.ok) {
            throw new Error(typeof payload.detail === 'string' ? payload.detail : `HTTP ${response.status}`);
        }
        const healthy = String(payload.status || '').toUpperCase() === 'HEALTHY';
        UI.showToast(
            healthy ? 'Rollback recorded. Paper reconciliation is healthy.' : `Rollback recorded. Reconciliation is still ${payload.status || 'unverified'}.`,
            healthy ? 'success' : 'info'
        );
        await UI.refreshCapitalReconciliation({ force: true });
        return payload;
    } catch (error) {
        UI.showToast(`Rollback refused: ${String(error?.message || error)}`, 'error');
        return null;
    }
};

Actions.syncCapital = async function () {
      try {
          await UI.refreshCapitalState({ showToast: true });
          await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);
      } catch (e) {
          console.warn('Capital sync failed:', e);
      }
};

Actions.setCapitalBotRunning = async function (enabled) {
    const buttons = ['capital-bot-start', 'capital-bot-stop', 'capital-cycle-run']
        .map((id) => document.getElementById(id))
        .filter(Boolean);
    buttons.forEach((button) => { button.disabled = true; });
    try {
        const response = await API.fetchWithTimeout(`${API.BASE_URL}/bot/${enabled ? 'start' : 'stop'}`, {
            method: 'POST',
            timeout: 20000,
            bypassCooldown: true,
        });
        let payload = {};
        try { payload = await response.json(); } catch (_) { payload = {}; }
        if (!response.ok || ['error', 'failed', 'blocked'].includes(String(payload.status || '').toLowerCase())) {
            throw new Error(payload.detail || payload.message || `Could not ${enabled ? 'start' : 'stop'} the paper bot.`);
        }
        API._resetStateCache();
        await UI.refreshCapitalState();
        UI.showToast(`Paper bot ${enabled ? 'started' : 'stopped'}.`, 'success');
    } catch (error) {
        UI.showToast(String(error?.message || 'Bot control failed.'), 'error');
    } finally {
        buttons.forEach((button) => { button.disabled = false; });
    }
};

Actions.runCapitalAutonomousCycle = async function () {
    const button = document.getElementById('capital-cycle-run');
    if (button) button.disabled = true;
    try {
        const response = await API.fetchWithTimeout(`${API.BASE_URL}/agents/autonomous/run-once`, {
            method: 'POST',
            timeout: 15000,
            bypassCooldown: true,
        });
        let payload = {};
        try { payload = await response.json(); } catch (_) { payload = {}; }
        if (!response.ok) {
            throw new Error(payload.detail || payload.message || 'Could not schedule the signal cycle.');
        }
        UI.showToast('Signal cycle scheduled. All risk and evidence gates remain active.', 'success');
        window.setTimeout(async () => {
            API._resetStateCache();
            await UI.refreshCapitalState().catch(() => {});
            await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT).catch(() => {});
        }, 15000);
    } catch (error) {
        UI.showToast(String(error?.message || 'Signal cycle request failed.'), 'error');
    } finally {
        if (button) button.disabled = false;
    }
};

Actions.exportCapitalHistory = function () {
    const capital = cachedState?.capital;
    const history = capital
        ? (Array.isArray(capital.ledger) ? capital.ledger : (capital.history || []))
        : [];
    if (!history.length) {
        // Used to return silently (or download a header-only file).
        UI.showToast('No Capital transactions to export yet.', 'info');
        return;
    }
    // Amounts are exported as numbers; a formula guard on "-40.51" turned every
    // debit into text ('-40.51) that spreadsheets could not sum.
    const csv = UI._capitalHistoryCsv(history);
    const blob = new Blob(['﻿', csv], { type: 'text/csv;charset=utf-8' });
    const url = window.URL.createObjectURL(blob);
    const a = document.createElement('a');
    const stamp = new Date().toISOString().slice(0, 16).replace('T', '_').replace(':', '');
    a.setAttribute('hidden', '');
    a.setAttribute('href', url);
    a.setAttribute('download', `capital_history_${stamp}_last_${history.length}_rows.csv`);
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    window.setTimeout(() => window.URL.revokeObjectURL(url), 1000);
};

Actions.clearPerformanceHistory = async function () {
    if (!cachedState || !cachedState.signals_raw) {
        UI.showToast('No performance data to clear.', 'info');
        return;
    }
    // Persist server-side first — otherwise the next /api/state poll restores everything
    try {
        const res = await API.fetchWithTimeout('/api/performance/clear', { method: 'POST', timeout: 10000 });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
    } catch (e) {
        console.error('Failed to clear performance history on server', e);
        UI.showToast('Failed to clear history on server.', 'error');
        return;
    }
    const signalsRaw = cachedState.signals_raw || {};
    const openSignals = signalsRaw.open || {};
    // Keep open signals, clear closed ones
    let cleared = 0;
    Object.keys(signalsRaw).forEach(key => {
        if (key !== 'open') {
            cleared += Array.isArray(signalsRaw[key]) ? signalsRaw[key].length : 0;
            delete signalsRaw[key];
        }
    });
    // Clear activity log
    UI.activityLog = [];
    try { localStorage.removeItem('marketMuse_activityLog'); } catch (e) { /* ignore */ }

    // Re-render the affected sections
    UI._safeRender('renderStats', () => UI.renderStats(cachedState));
    UI._safeRender('renderTimeline', () => UI.renderTimeline(cachedState));

    // Reset performance KPIs
    const statWinrateEl = document.getElementById('stat-winrate');
    if (statWinrateEl) statWinrateEl.textContent = '0%';
    const statActiveEl = document.getElementById('stat-active-signals');
    if (statActiveEl) statActiveEl.textContent = String(Object.keys(openSignals).length);

    // Reset the win/loss bar
    const bar = document.querySelector('.progress-fill');
    if (bar) bar.style.width = '0%';
    const perfRingReset = document.getElementById('perf-ring');
    if (perfRingReset) perfRingReset.style.setProperty('--p', '0');

    // Reset the trade history list
    const container = document.getElementById('losses-list-content');
    if (container) {
        container.innerHTML = '<div class="placeholder-text" style="padding:6px; text-align:center; color:var(--ds-text-3); font-size:0.76rem;">No recent trades.</div>';
    }

    UI.saveState(cachedState);
    UI.showToast(`Cleared ${cleared} closed signal records.`, 'success');
};

Actions._capitalRiskPosition = function () {
    const modal = document.getElementById('capital-risk-modal');
    const positionId = String(modal?.dataset?.positionId || '');
    const positions = Array.isArray(cachedState?.capital?.positions) ? cachedState.capital.positions : [];
    return positions.find(position => String(position?.position_id || '') === positionId) || null;
};

Actions._capitalRiskInputValue = function (value) {
    const price = Number(value);
    if (!Number.isFinite(price) || price <= 0) return '';
    const decimals = price >= 1000 ? 2 : price >= 1 ? 4 : 8;
    return price.toFixed(decimals).replace(/\.?0+$/, '');
};

Actions._setCapitalRiskValidation = function (kind, message) {
    const validation = document.getElementById('capital-risk-validation');
    if (!validation) return;
    validation.className = `capital-risk-validation${kind ? ` is-${kind}` : ''}`;
    const icon = kind === 'error' ? 'triangle-exclamation' : kind === 'valid' ? 'circle-check' : 'circle-info';
    validation.innerHTML = `<i class="fa-solid fa-${icon}"></i><span></span>`;
    const text = validation.querySelector('span');
    if (text) text.textContent = String(message || '');
};

Actions.openCapitalRiskEditor = function (positionId) {
    const positions = Array.isArray(cachedState?.capital?.positions) ? cachedState.capital.positions : [];
    const position = positions.find(item => (
        String(item?.position_id || '') === String(positionId || '')
        && String(item?.status || '').toUpperCase() === 'OPEN'
    ));
    if (!position) {
        UI.showToast('Open position not found. Refresh Capital and try again.', 'error');
        return;
    }

    const modal = document.getElementById('capital-risk-modal');
    if (!modal) return;
    const direction = String(position.direction || 'LONG').toUpperCase() === 'SHORT' ? 'SHORT' : 'LONG';
    const entry = Number(position.entry_price || 0);
    const current = Number(position.current_price || position.entry_price || 0);
    const stop = Number(position.stop_loss_price || 0);
    const target = Number(position.take_profit_price || 0);
    modal.dataset.positionId = String(position.position_id || '');
    modal.dataset.direction = direction;
    modal.dataset.entryPrice = String(entry);
    modal.dataset.currentPrice = String(current);
    modal.dataset.ticker = String(position.ticker || '');

    const setText = (id, value) => {
        const element = document.getElementById(id);
        if (element) element.textContent = value;
    };
    setText('capital-risk-symbol', String(position.ticker || '--'));
    setText('capital-risk-direction', direction);
    setText('capital-risk-entry', entry > 0 ? `$${UI.formatPrice(entry)}` : '--');
    setText('capital-risk-current', current > 0 ? `$${UI.formatPrice(current)}` : '--');
    const title = document.getElementById('capital-risk-title');
    if (title) title.textContent = `Edit SL / TP · ${String(position.ticker || '')}`;

    const stopInput = document.getElementById('capital-risk-stop');
    const targetInput = document.getElementById('capital-risk-target');
    const reasonInput = document.getElementById('capital-risk-reason');
    if (stopInput) stopInput.value = Actions._capitalRiskInputValue(stop);
    if (targetInput) targetInput.value = Actions._capitalRiskInputValue(target);
    if (reasonInput) reasonInput.value = '';

    const breakEven = document.getElementById('capital-risk-breakeven');
    const minimumGap = current * 0.0005;
    const breakEvenValid = direction === 'LONG'
        ? entry > 0 && entry < current - minimumGap
        : entry > current + minimumGap;
    if (breakEven) {
        breakEven.disabled = !breakEvenValid;
        breakEven.title = breakEvenValid
            ? 'Move stop loss to the entry price'
            : 'Break-even is not safely beyond the current market price.';
    }

    modal.classList.remove('hidden');
    document.body.classList.add('capital-risk-open');
    Actions.previewCapitalRiskLevels();
    window.setTimeout(() => stopInput?.focus(), 80);
};

Actions.closeCapitalRiskEditor = function () {
    const modal = document.getElementById('capital-risk-modal');
    modal?.classList.add('hidden');
    if (modal) {
        delete modal.dataset.positionId;
        delete modal.dataset.direction;
        delete modal.dataset.entryPrice;
        delete modal.dataset.currentPrice;
        delete modal.dataset.ticker;
    }
    document.body.classList.remove('capital-risk-open');
};

Actions.previewCapitalRiskLevels = function () {
    const modal = document.getElementById('capital-risk-modal');
    const stop = Number(document.getElementById('capital-risk-stop')?.value || 0);
    const target = Number(document.getElementById('capital-risk-target')?.value || 0);
    const current = Number(modal?.dataset?.currentPrice || 0);
    const direction = String(modal?.dataset?.direction || 'LONG');
    const minimumGap = current * 0.0005;
    const save = document.getElementById('capital-risk-save');
    let error = '';

    if (!Number.isFinite(stop) || stop <= 0 || !Number.isFinite(target) || target <= 0 || current <= 0) {
        error = 'Enter positive SL and TP prices.';
    } else if (direction === 'LONG' && stop >= current - minimumGap) {
        error = 'For LONG, stop loss must be at least 0.05% below the live price.';
    } else if (direction === 'LONG' && target <= current + minimumGap) {
        error = 'For LONG, take profit must be at least 0.05% above the live price.';
    } else if (direction === 'SHORT' && stop <= current + minimumGap) {
        error = 'For SHORT, stop loss must be at least 0.05% above the live price.';
    } else if (direction === 'SHORT' && target >= current - minimumGap) {
        error = 'For SHORT, take profit must be at least 0.05% below the live price.';
    }

    const stopDistance = current > 0
        ? (direction === 'LONG' ? current - stop : stop - current) / current * 100
        : 0;
    const targetDistance = current > 0
        ? (direction === 'LONG' ? target - current : current - target) / current * 100
        : 0;
    const rr = stopDistance > 0 && targetDistance > 0 ? targetDistance / stopDistance : null;
    const setText = (id, value) => {
        const element = document.getElementById(id);
        if (element) element.textContent = value;
    };
    setText('capital-risk-stop-gap', stopDistance > 0 ? `Distance from live price: ${stopDistance.toFixed(2)}%` : 'Distance from live price: --');
    setText('capital-risk-target-gap', targetDistance > 0 ? `Distance from live price: ${targetDistance.toFixed(2)}%` : 'Distance from live price: --');
    setText('capital-risk-summary-stop', stopDistance > 0 ? `${stopDistance.toFixed(2)}%` : '--');
    setText('capital-risk-summary-target', targetDistance > 0 ? `${targetDistance.toFixed(2)}%` : '--');
    setText('capital-risk-summary-rr', Number.isFinite(rr) ? `1 : ${rr.toFixed(2)}` : '--');

    if (save) save.disabled = Boolean(error) || !modal?.dataset?.positionId;
    if (error) {
        Actions._setCapitalRiskValidation('error', error);
        return { valid: false, stop, target, error };
    }
    Actions._setCapitalRiskValidation('valid', 'Levels are valid locally. A fresh verified price will be checked again when saving.');
    return { valid: true, stop, target, error: '' };
};

Actions.applyCapitalRiskPreset = function (stopPct, targetPct) {
    const modal = document.getElementById('capital-risk-modal');
    const current = Number(modal?.dataset?.currentPrice || 0);
    const direction = String(modal?.dataset?.direction || 'LONG');
    const stopPercent = Number(stopPct);
    const targetPercent = Number(targetPct);
    if (current <= 0 || stopPercent <= 0 || targetPercent <= 0) return;

    const stop = direction === 'LONG'
        ? current * (1 - stopPercent / 100)
        : current * (1 + stopPercent / 100);
    const target = direction === 'LONG'
        ? current * (1 + targetPercent / 100)
        : current * (1 - targetPercent / 100);
    const stopInput = document.getElementById('capital-risk-stop');
    const targetInput = document.getElementById('capital-risk-target');
    if (stopInput) stopInput.value = Actions._capitalRiskInputValue(stop);
    if (targetInput) targetInput.value = Actions._capitalRiskInputValue(target);
    Actions.previewCapitalRiskLevels();
};

Actions.applyCapitalBreakEven = function () {
    const modal = document.getElementById('capital-risk-modal');
    const entry = Number(modal?.dataset?.entryPrice || 0);
    const stopInput = document.getElementById('capital-risk-stop');
    if (entry > 0 && stopInput) {
        stopInput.value = Actions._capitalRiskInputValue(entry);
        Actions.previewCapitalRiskLevels();
    }
};

Actions.saveCapitalRiskLevels = async function () {
    const modal = document.getElementById('capital-risk-modal');
    const preview = Actions.previewCapitalRiskLevels();
    const positionId = String(modal?.dataset?.positionId || '');
    if (!preview.valid || !positionId) return null;

    const save = document.getElementById('capital-risk-save');
    const originalHtml = save?.innerHTML || '';
    if (save) {
        save.disabled = true;
        save.innerHTML = '<i class="fa-solid fa-spinner fa-spin"></i> Validating live price...';
    }
    Actions._setCapitalRiskValidation('', 'Requesting a verified live price and saving protection levels...');

    try {
        const reason = String(document.getElementById('capital-risk-reason')?.value || '').trim();
        const data = await API.updateCapitalPositionLevels({
            position_id: positionId,
            stop_loss_price: preview.stop,
            take_profit_price: preview.target,
            reason: reason || 'Manual SL/TP update from Capital',
        });
        if (!cachedState || typeof cachedState !== 'object') cachedState = {};
        cachedState.capital = {
            ...(cachedState.capital || {}),
            balance: Number(data.balance || 0),
            positions: Array.isArray(data.positions) ? data.positions : [],
            history: Array.isArray(data.history) ? data.history : [],
        };
        try {
            const fresh = await API.getState({
                includeNews: false,
                includeHotlist: false,
                hotlistDetails: false,
                lean: false,
                include: 'capital',
                unchanged: false,
                livePrices: false,
            });
            if (fresh?.capital) cachedState = UI.mergeStatePreserveDetails(cachedState, fresh);
        } catch (refreshError) {
            console.warn('Capital refreshed with persisted levels but without a new live quote:', refreshError);
        }
        UI._capitalCardsSig = null;
        UI.renderCapital(cachedState.capital);
        Actions.closeCapitalRiskEditor();
        UI.showToast('Stop loss and take profit updated. Automatic exit overrides are disabled for this position.', 'success');
        window.dispatchEvent(new CustomEvent('capital:position-levels-updated', { detail: data.position || { position_id: positionId } }));
        return data;
    } catch (error) {
        Actions._setCapitalRiskValidation('error', String(error?.message || 'Protection levels could not be updated.'));
        return null;
    } finally {
        if (save) {
            save.innerHTML = originalHtml;
            save.disabled = modal?.classList.contains('hidden') ? true : !preview.valid;
        }
    }
};

Actions.closeCapitalPosition = async function (positionId) {
    if (!positionId) return null;
    if (!confirm('Close this paper position at the current market price?')) return null;
    try {
        const data = await API.closeCapitalPosition({ position_id: positionId });
        if (!cachedState || typeof cachedState !== 'object') cachedState = {};
          cachedState.capital = {
              ...(cachedState.capital || {}),
              balance: Number(data.balance || 0),
              positions: Array.isArray(data.positions) ? data.positions : [],
              history: Array.isArray(data.history) ? data.history : []
          };
          try {
              const state = await API.getState({ includeNews: false, includeHotlist: false, hotlistDetails: false, lean: false, include: 'capital', unchanged: false, livePrices: false });
              if (state && state.capital) {
                  cachedState = UI.mergeStatePreserveDetails(cachedState, state);
              }
          } catch (e) { }
          UI.renderCapital(cachedState.capital);
          await UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);
          UI.showToast('Position closed.', 'success');
          window.dispatchEvent(new CustomEvent('capital:position-closed', { detail: data.position || { position_id: positionId } }));
          return data;
      } catch (e) {
          UI.showToast(String(e?.message || 'Failed to close position.'), 'error');
          return null;
      }
};

UI.flashCapitalTab = function () {
    const capitalTab = document.querySelector('[data-testid="nav-capital"]');
    if (!capitalTab) return;
    capitalTab.classList.add('capital-tab-flash');
    setTimeout(() => {
        capitalTab.classList.remove('capital-tab-flash');
    }, 1500);
};

// Patch ViewRouter to handle alerts
const originalNavigate = ViewRouter.navigate;
ViewRouter.navigate = function (viewName, ...args) {
    // Explicit handling for CAPITAL view to ensure it works
    if (viewName === 'capital') {
        if (IS_DEV) console.log('Navigating to Capital view...');
        window.location.hash = viewName;
        // 1. Hide all views
        document.querySelectorAll('.view-section').forEach(el => el.classList.add('hidden'));

        // 2. Show capital view
        const target = document.getElementById('view-capital');
        if (target) {
            target.classList.remove('hidden');
        } else {
            console.error('Capital view element #view-capital not found!');
        }

        // 3. Update active nav state
        document.querySelectorAll('.nav-item').forEach(el => {
            el.classList.remove('active');
            el.setAttribute('aria-selected', 'false');
        });
        const navItem = document.querySelector('[data-testid="nav-capital"]') ||
            Array.from(document.querySelectorAll('.nav-item')).find(el => el.textContent.includes('Capital'));
        if (navItem) {
            navItem.classList.add('active');
            navItem.setAttribute('aria-selected', 'true');
        }

        // 4. Update state tracking
        if (this.activeView) this.activeView = 'capital';

          // 5. Render data
          if (typeof cachedState !== 'undefined' && cachedState && cachedState.capital) {
              UI.renderCapital(cachedState.capital);
          }
          if (typeof cachedState !== 'undefined' && cachedState && Array.isArray(cachedState.capital_decisions)) {
              UI.renderCapitalDecisions(cachedState.capital_decisions);
          } else {
              UI.refreshCapitalDecisionFeed(UI.CAPITAL_DECISION_FETCH_LIMIT);
          }
          UI.refreshCapitalState().catch((err) => console.warn('Capital state refresh failed:', err));

          return; // Stop here to avoid conflict with original router if it doesn't support this view
      }

    // Explicit handling for ALERTS view
    if (viewName === 'alerts') {
        if (IS_DEV) console.log('Navigating to Alerts view...');
        window.location.hash = viewName;
        // 1. Hide all views
        document.querySelectorAll('.view-section').forEach(el => el.classList.add('hidden'));

        // 2. Show alerts view
        const target = document.getElementById('view-alerts');
        if (target) {
            target.classList.remove('hidden');
        } else {
            console.error('Alerts view element #view-alerts not found!');
        }

        // 3. Update active nav state
        document.querySelectorAll('.nav-item').forEach(el => {
            el.classList.remove('active');
            el.setAttribute('aria-selected', 'false');
        });
        const navItem = document.querySelector('[data-testid="nav-alerts"]') ||
            Array.from(document.querySelectorAll('.nav-item')).find(el => el.textContent.includes('Alerts'));
        if (navItem) {
            navItem.classList.add('active');
            navItem.setAttribute('aria-selected', 'true');
        }

        // 4. Update state tracking
        if (this.activeView) this.activeView = 'alerts';

        // 5. Render data. The list is fetched from /api/alerts and does not
        // need the cached state: waiting for it left "Loading alerts…" on
        // screen for good when the app was opened or reloaded on #alerts.
        UI.renderAlerts(cachedState);
        UI.loadTelegramDelivery();

        return;
    }

    if (originalNavigate) {
        originalNavigate.call(this, viewName, ...args);
    }

    // Custom handling for alerts
    if (viewName === 'alerts') {
        if (cachedState) UI.renderAlerts(cachedState);
        UI.loadTelegramDelivery();
    }
};

// Patch updateUI to check for triggered alerts
// Fired Smart Alerts → toast + sound, deduped per alert/timestamp. The
// backend exposes recent fires in /api/state (alerts_triggered) and the core
// auto-refresh loop calls this on every poll.
UI.processTriggeredAlerts = function (state) {
    if (!state || !Array.isArray(state.alerts_triggered) || state.alerts_triggered.length === 0) return;
    let fired = false;
    state.alerts_triggered.forEach(ta => {
        // This runs inside the main refresh loop: a malformed row must not
        // throw and stop the whole UI update.
        const alert = ta && ta.alert;
        if (!alert || !alert.id) return;
        const key = `triggered_${alert.id}_${ta.timestamp}`;
        if (!UI.seenManualActivity.has(key)) {
            UI.seenManualActivity.add(key);
            fired = true;

            // Show Toast — say what actually happened for each alert type.
            const price = Number(ta.current_price);
            const priceText = Number.isFinite(price) ? ` (now ${UI.formatPrice(price)})` : '';
            const type = String(alert.type || '');
            const what = type === 'PRICE_UP' ? `rose to your target ${alert.target}`
                : (type === 'PRICE_DOWN' ? `fell to your target ${alert.target}`
                    : (type === 'VOLATILITY' ? `moved ${alert.target}% or more today` : `hit ${type.replace(/_/g, ' ')} target ${alert.target}`));
            UI.showToast(`ALERT: ${alert.ticker} ${what}${priceText}`, "success");

            // Play Sound
            AudioSystem.playSignalSound();
        }
    });
    // The fired alert is now inactive on the server — refresh the table so it
    // does not keep showing "Active".
    if (fired && typeof ViewRouter !== 'undefined' && ViewRouter.activeView === 'alerts') UI.renderAlerts();
};

/* ── Sidebar Toggle (responsive) ── */
(function initSidebarToggles() {
    const overlay = document.getElementById('sidebarOverlay');
    const leftBtn = document.getElementById('sidebarToggleLeft');
    const rightBtn = document.getElementById('sidebarToggleRight');
    const leftSidebar = document.querySelector('.left-sidebar');
    const rightSidebar = document.querySelector('.right-sidebar');

    function closeAll() {
        if (leftSidebar) leftSidebar.classList.remove('open');
        if (rightSidebar) rightSidebar.classList.remove('open');
        if (overlay) overlay.classList.remove('active');
        if (leftBtn) leftBtn.setAttribute('aria-expanded', 'false');
        if (rightBtn) rightBtn.setAttribute('aria-expanded', 'false');
    }

    if (leftBtn) {
        leftBtn.addEventListener('click', () => {
            const isOpen = leftSidebar && leftSidebar.classList.contains('open');
            closeAll();
            if (!isOpen && leftSidebar) {
                leftSidebar.classList.add('open');
                if (overlay) overlay.classList.add('active');
                leftBtn.setAttribute('aria-expanded', 'true');
            }
        });
    }

    if (rightBtn) {
        rightBtn.addEventListener('click', () => {
            const isOpen = rightSidebar && rightSidebar.classList.contains('open');
            closeAll();
            if (!isOpen && rightSidebar) {
                rightSidebar.classList.add('open');
                if (overlay) overlay.classList.add('active');
                rightBtn.setAttribute('aria-expanded', 'true');
            }
        });
    }

    // Close sidebar on overlay click
    if (overlay) {
        overlay.addEventListener('click', closeAll);
    }

    // Close sidebar on Escape key
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') closeAll();
    });

    // Close sidebar when clicking a nav item (user navigated away)
    document.querySelectorAll('.nav-item').forEach((nav) => {
        nav.addEventListener('click', closeAll);
    });
})();
